37	impl PackageJson {
38	    pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Self, ManifestError> {
39	        let rel_path = decl.path.clone();
40	        let abs_path = ctx.workspace_root.join(&rel_path);
41	
42	        let content = fs::read_to_string(&abs_path).map_err(|e| ManifestError::Read {
43	            path: rel_path.clone(),
44	            message: e.to_string(),
45	        })?;
46	
47	        let common_fp = crate::common::FormatFingerprint::detect(&content);
48	        let clean_content = content.strip_prefix('\u{FEFF}').unwrap_or(&content);
49	        let fingerprint = detect_fingerprint(clean_content, common_fp);
50	
51	        let doc: Map<String, Value> = serde_json::from_str(clean_content).map_err(|e| ManifestError::Parse {
52	            path: rel_path.clone(),
53	            format: ManifestFormat::PackageJson,
54	            message: e.to_string(),
55	        })?;
56	
57	        Ok(PackageJson {
58	            path: rel_path,
59	            absolute: abs_path,
60	            role: decl.role.clone(),
61	            doc,
62	            fingerprint,
63	            npm_workspace_kind: ctx.npm_workspace_kind,
64	            workspace_root: ctx.workspace_root.to_path_buf(),
65	        })
66	    }
67	
68	    fn dependency_target(&self, name: &str, spec: &DepSpec) -> String {
69	        let DepSpec::WorkspaceProtocol(workspace) = spec else {
70	            return name.to_string();
71	        };
72	        if let Some(alias) = workspace.alias() {
73	            return alias.to_string();
74	        }
75	        let Some(relative) = workspace.relative_path() else {
76	            return name.to_string();
77	        };
78	        let target_name = self.absolute.parent().and_then(|parent| {
79	            let target = parent.join(relative).canonicalize().ok()?;
80	            let root = self.workspace_root.canonicalize().ok()?;
81	            if !target.starts_with(root) {
82	                return None;
83	            }
84	            let manifest = target.join("package.json");
85	            let source = fs::read_to_string(&manifest).ok()?;
86	            identity_from_source(&source, &manifest).ok()?.name
87	        });
88	        target_name.unwrap_or_else(|| format!("workspace:{}", workspace.suffix))
89	    }
90	}
91	
92	fn detect_fingerprint(content: &str, common: crate::common::FormatFingerprint) -> FormatFingerprint {
93	    let trailing_newline = content.ends_with('\n');
94	
95	    let mut indent = Indent::DefaultTwoSpaces;
96	    for line in content.lines() {
97	        let trimmed_start = line.trim_start();
98	        if trimmed_start.starts_with('"') && line.len() > trimmed_start.len() {
99	            let leading = &line[..line.len() - trimmed_start.len()];
100	            if leading.contains('\t') {
101	                indent = Indent::Tabs;
102	            } else {
103	                indent = Indent::Spaces(leading.len() as u8);
104	            }
105	            break;
106	        }
107	    }
108	
109	    FormatFingerprint {
110	        indent,
111	        trailing_newline,
112	        common,
113	    }
114	}
