116	fn format_json_pretty(map: &IndexMap<&String, &Value>, indent_str: &str) -> Result<String, ManifestError> {
117	    use serde::Serialize;
118	    let buf = Vec::new();
119	    let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
120	    let mut serializer = serde_json::Serializer::with_formatter(buf, formatter);
121	    map.serialize(&mut serializer)
122	        .map_err(|e| ManifestError::FormattingNotPreserved {
123	            path: std::path::PathBuf::new(),
124	            message: format!("JSON serialization failed: {e}"),
125	        })?;
126	    let bytes = serializer.into_inner();
127	    let mut out = String::from_utf8(bytes).map_err(|e| ManifestError::FormattingNotPreserved {
128	        path: std::path::PathBuf::new(),
129	        message: format!("JSON serialization produced invalid UTF-8: {e}"),
130	    })?;
131	    out.push('\n');
132	    Ok(out)
133	}
