135	/// Extracts `name` from an already-parsed `package.json` document. Pure and
136	/// I/O-free -- see [`crate::cargo::cargo_package_name`]'s doc comment for
137	/// why this exists as a standalone function rather than only living inside
138	/// [`Manifest::package_name`].
139	pub fn npm_package_name(doc: &serde_json::Map<String, serde_json::Value>) -> Option<&str> {
140	    doc.get("name").and_then(|n| n.as_str())
141	}
142	
143	/// [`crate::read_identity`]'s `package.json` implementation: parses
144	/// `source` and extracts `name` plus a [`crate::VersionSource::Literal`]
145	/// for `version` (npm has no workspace-inherited-version concept, unlike
146	/// Cargo).
147	pub(crate) fn identity_from_source(source: &str, path: &Path) -> Result<crate::ManifestIdentity, ManifestError> {
148	    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
149	    let doc: Map<String, Value> = serde_json::from_str(clean).map_err(|e| ManifestError::Parse {
150	        path: path.to_path_buf(),
151	        format: ManifestFormat::PackageJson,
152	        message: e.to_string(),
153	    })?;
154	
155	    let name = npm_package_name(&doc).map(str::to_string);
156	    let version = doc
157	        .get("version")
158	        .and_then(|v| v.as_str())
159	        .map(|s| crate::VersionSource::Literal(s.to_string()));
160	
161	    Ok(crate::ManifestIdentity { name, version })
162	}
