164	/// Reads `napi.targets` from an already-parsed `package.json` value.
165	/// `Ok(None)` when `napi` or `napi.targets` is absent -- not every napi
166	/// package.json declares platform targets. `Err` when `napi.targets` is
167	/// present but is not a JSON array of strings.
168	///
169	/// The single implementation both `NapiTargetsIndex::load` (lenient: `.ok()`
170	/// this, treating a malformed value the same as absent) and
171	/// `matrix::read_napi_targets` (strict: propagates the error) build their
172	/// differing policies on top of -- see each call site for which it chooses.
173	pub fn read_napi_targets(path: &Path, val: &Value) -> Result<Option<Vec<String>>, ManifestError> {
174	    let Some(napi) = val.get("napi") else {
175	        return Ok(None);
176	    };
177	    let Some(targets) = napi.get("targets") else {
178	        return Ok(None);
179	    };
180	
181	    let arr = targets.as_array().ok_or_else(|| ManifestError::Parse {
182	        path: path.to_path_buf(),
183	        format: ManifestFormat::PackageJson,
184	        message: "napi.targets must be a JSON array of strings".to_string(),
185	    })?;
186	
187	    let mut out = Vec::with_capacity(arr.len());
188	    for item in arr {
189	        let s = item.as_str().ok_or_else(|| ManifestError::Parse {
190	            path: path.to_path_buf(),
191	            format: ManifestFormat::PackageJson,
192	            message: "napi.targets entries must all be strings".to_string(),
193	        })?;
194	        out.push(s.to_string());
195	    }
196	    Ok(Some(out))
197	}
