199	/// The napi-rs binary name: `napi.binaryName`, else the deprecated `napi.name`, else napi-rs's `index`.
200	pub fn napi_binary_name(val: &Value) -> String {
201	    let napi = val.get("napi");
202	    ["binaryName", "name"]
203	        .iter()
204	        .find_map(|key| napi.and_then(|napi| napi.get(key)).and_then(Value::as_str))
205	        .unwrap_or("index")
206	        .to_owned()
207	}
