209	/// Detects whether `doc` (an already-parsed `package.json` document) declares
210	/// itself a napi-rs platform package -- `os`+`cpu` constraint arrays both
211	/// present and non-empty -- and if so, its platform/arch/abi. Pure and
212	/// I/O-free: the single implementation [`PackageJson::npm_role`] builds on,
213	/// so platform-role detection is available from an already-open `Manifest`
214	/// handle (e.g. one served from `callisto-graph`'s `manifest_cache`) without
215	/// a second `fs::read` of the same file.
216	/// `npm_role_from_doc` over raw `package.json` source, for callers (workspace
217	/// discovery) that have not opened a manifest handle. `None` on invalid JSON.
218	pub fn npm_role_from_source(source: &str) -> Option<NpmRole> {
219	    match serde_json::from_str::<Value>(source).ok()? {
220	        Value::Object(doc) => npm_role_from_doc(&doc),
221	        _ => None,
222	    }
223	}
224	
225	/// True when raw `package.json` `source` sets `"private": true`. `false` on
226	/// invalid JSON or an absent/non-true `private` field.
227	pub fn npm_declares_private(source: &str) -> bool {
228	    match serde_json::from_str::<Value>(source).ok() {
229	        Some(Value::Object(doc)) => doc.get("private").and_then(Value::as_bool).unwrap_or(false),
230	        _ => false,
231	    }
232	}
233	
234	fn npm_role_from_doc(doc: &Map<String, Value>) -> Option<NpmRole> {
235	    let has_os = doc.get("os").and_then(|v| v.as_array()).is_some_and(|a| !a.is_empty());
236	    let has_cpu = doc.get("cpu").and_then(|v| v.as_array()).is_some_and(|a| !a.is_empty());
237	
238	    if !has_os || !has_cpu {
239	        return None;
240	    }
241	
242	    let platform = doc
243	        .get("os")
244	        .and_then(|v| v.as_array())
245	        .and_then(|a| a.first())
246	        .and_then(|v| v.as_str())
247	        .map(str::to_string)?;
248	
249	    let arch = doc
250	        .get("cpu")
251	        .and_then(|v| v.as_array())
252	        .and_then(|a| a.first())
253	        .and_then(|v| v.as_str())
254	        .map(str::to_string)?;
255	
256	    // npm's standard `os`/`cpu` manifest fields have no libc/ABI concept at
257	    // all, so a real disk-discovered Linux napi platform package always
258	    // produces `abi: None` here -- but `napi.rs::role_to_triple`'s Linux
259	    // match arms all require a concrete ABI, meaning such a package could
260	    // never resolve to its triple. napi-rs's own package-generation
261	    // convention encodes the ABI in the package *name*'s suffix instead
262	    // (e.g. "@scope/pkg-linux-x64-gnu"), so infer it from there when the
263	    // platform is linux.
264	    let abi = if platform == "linux" {
265	        doc.get("name")
266	            .and_then(|v| v.as_str())
267	            .and_then(napi_linux_abi_from_package_name)
268	    } else {
269	        None
270	    };
271	
272	    Some(NpmRole::Platform { platform, arch, abi })
273	}
274	
275	/// Infers a Linux napi-rs platform package's libc ABI from its package
276	/// name's trailing suffix. Returns `None` when the name has no recognized
277	/// suffix -- this infers when the signal is present, it doesn't invent an
278	/// ABI that isn't actually there.
279	fn napi_linux_abi_from_package_name(name: &str) -> Option<String> {
280	    for abi in ["gnueabihf", "gnu", "musl"] {
281	        if name.ends_with(&format!("-{abi}")) {
282	            return Some(abi.to_string());
283	        }
284	    }
285	    None
286	}
