288	impl Manifest for PackageJson {
289	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
290	        let indent_str = match self.fingerprint.indent {
291	            Indent::Spaces(n) => " ".repeat(n as usize),
292	            Indent::Tabs => "\t".to_string(),
293	            Indent::DefaultTwoSpaces => "  ".to_string(),
294	        };
295	
296	        let mut map = IndexMap::new();
297	        for (k, v) in &self.doc {
298	            map.insert(k, v);
299	        }
300	
301	        let mut out = format_json_pretty(&map, &indent_str)?;
302	        if self.fingerprint.common.line_ending == crate::common::LineEnding::CrLf {
303	            out = out.replace("\r\n", "\n").replace('\n', "\r\n");
304	        }
305	
306	        // Trailing-newline trimming must happen strictly between the
307	        // line-ending conversion (above, so a trimmed "\r\n" is measured
308	        // correctly) and the BOM prepend (below, so a BOM byte is never
309	        // mistaken for part of the trailing newline) -- this ordering
310	        // dependency is why npm's own trailing_newline concern can't route
311	        // through `common::FormatFingerprint::apply`'s single combined
312	        // crlf-then-bom step the way cargo/python's simpler persist paths do.
313	        if !self.fingerprint.trailing_newline && out.ends_with('\n') {
314	            if out.ends_with("\r\n") {
315	                out.truncate(out.len() - 2);
316	            } else {
317	                out.truncate(out.len() - 1);
318	            }
319	        }
320	
321	        if self.fingerprint.common.has_bom {
322	            out = format!("\u{FEFF}{}", out);
323	        }
324	
325	        crate::atomic::atomic_write(&self.absolute, &out, permit).map_err(|e| ManifestError::Write {
326	            path: self.path.clone(),
327	            message: e.to_string(),
328	        })?;
329	        crate::record_persist_call();
330	        Ok(())
331	    }
332	
333	    fn path(&self) -> &Path {
334	        &self.path
335	    }
336	
337	    fn ecosystem(&self) -> Ecosystem {
338	        Ecosystem::Npm
339	    }
340	
341	    fn is_publishable(&self) -> bool {
342	        if self.doc.get("name").is_none() {
343	            return false;
344	        }
345	        if let Some(b) = self.doc.get("private").and_then(|p| p.as_bool())
346	            && b
347	        {
348	            return false;
349	        }
350	        true
351	    }
352	
353	    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
354	        if !self.is_publishable() {
355	            return vec![callisto_model::PublishTarget::None];
356	        }
357	        // Read `publishConfig.registry` from package.json, the standard npm
358	        // mechanism for targeting a private registry. When set, `npm publish`
359	        // must receive `--registry <url>`; when absent, the public registry is
360	        // used (npm's built-in default).
361	        let publish_config = self.doc.get("publishConfig");
362	        let registry = publish_config
363	            .and_then(|pc| pc.get("registry"))
364	            .and_then(|r| r.as_str())
365	            .map(|s| s.to_string());
366	        // Read `publishConfig.access` to propagate the operator's explicit
367	        // access intent. npm's `--access` CLI flag overrides publishConfig.access,
368	        // so callisto must read it here and honour it in release planning rather than
369	        // blindly passing `--access public` for all scoped packages. Any value
370	        // other than the two npm recognises (including absence) is `None`,
371	        // not an error -- an unrecognised value here isn't this layer's job
372	        // to validate.
373	        let access = publish_config
374	            .and_then(|pc| pc.get("access"))
375	            .and_then(|a| a.as_str())
376	            .and_then(|s| match s {
377	                "public" => Some(callisto_model::NpmAccess::Public),
378	                "restricted" => Some(callisto_model::NpmAccess::Restricted),
379	                _ => None,
380	            });
381	        vec![callisto_model::PublishTarget::Npm { registry, access }]
382	    }
