388	    fn package_name(&self) -> Result<String, ManifestError> {
389	        let name = npm_package_name(&self.doc).ok_or_else(|| ManifestError::MissingField {
390	            path: self.path.clone(),
391	            field: "name",
392	        })?;
393	        Ok(name.to_string())
