396	    fn current_version(&self) -> Result<Version, ManifestError> {
397	        let raw = self
398	            .doc
399	            .get("version")
400	            .and_then(|v| v.as_str())
401	            .ok_or_else(|| ManifestError::MissingField {
402	                path: self.path.clone(),
403	                field: "version",
404	            })?;
405	
406	        Version::parse(raw, VersionGrammar::SemVer).map_err(|source| ManifestError::InvalidVersion {
407	            path: self.path.clone(),
408	            raw: raw.to_string(),
409	            source,
410	        })
411	    }
412	
413	    fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
414	        self.doc
415	            .insert("version".to_string(), Value::String(v.render().to_string()));
416	        Ok(())
417	    }
418	
419	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
420	        let mut entries = Vec::new();
421	
422	        for (section_name, kind) in [
423	            ("dependencies", DepKind::Runtime),
424	            ("devDependencies", DepKind::Dev),
425	            ("peerDependencies", DepKind::Peer),
426	            ("optionalDependencies", DepKind::Optional),
427	        ] {
428	            if let Some(obj) = self.doc.get(section_name).and_then(|v| v.as_object()) {
429	                for (name, val) in obj {
430	                    if let Some(v_str) = val.as_str() {
431	                        let spec = parse_npm_spec_str(v_str, self.npm_workspace_kind);
432	                        entries.push(DependencyEntry {
433	                            name: name.clone(),
434	                            package_name: self.dependency_target(name, &spec),
435	                            kind,
436	                            spec,
437	                            inherited: false,
438	                            locator: DepLocator::default(),
439	                        });
440	                    }
441	                }
442	            }
443	        }
444	
445	        Box::new(entries.into_iter())
446	    }
447	
448	    fn update_dependency_spec(
449	        &mut self,
450	        name: &str,
451	        kind: DepKind,
452	        _at: &DepLocator,
453	        new: DepSpec,
454	        _permit: &ApplyPermit,
455	    ) -> Result<(), ManifestError> {
456	        if kind == DepKind::Build {
457	            return Err(ManifestError::DependencyNotFound {
458	                path: self.path.clone(),
459	                name: name.to_string(),
460	                kind,
461	            });
462	        }
463	
464	        let section_name = match kind {
465	            DepKind::Runtime => "dependencies",
466	            DepKind::Dev => "devDependencies",
467	            DepKind::Peer => "peerDependencies",
468	            DepKind::Optional => "optionalDependencies",
469	            DepKind::Build => unreachable!(),
470	        };
471	
472	        // Validate that the target dependency actually exists in the primary
473	        // section *before* mutating anything. This guarantees that a failed
474	        // update (dependency not found) leaves self.doc byte-for-byte
475	        // unchanged, including the overrides/resolutions tables below.
476	        let updated_in_section = self
477	            .doc
478	            .get(section_name)
479	            .and_then(|v| v.as_object())
480	            .is_some_and(|section| section.contains_key(name));
481	
482	        if !updated_in_section {
483	            return Err(ManifestError::DependencyNotFound {
484	                path: self.path.clone(),
485	                name: name.to_string(),
486	                kind,
487	            });
488	        }
489	
490	        if let Some(section) = self.doc.get_mut(section_name).and_then(|v| v.as_object_mut()) {
491	            section.insert(name.to_string(), Value::String(new.render()));
492	        }
493	
494	        if matches!(new, DepSpec::WorkspaceProtocol(_)) {
495	            return Ok(());
496	        }
497	
498	        for extra in ["overrides", "resolutions"] {
499	            if let Some(tbl) = self.doc.get_mut(extra).and_then(|v| v.as_object_mut())
500	                && tbl.get(name).is_some_and(|v| v.is_string())
501	            {
502	                tbl.insert(name.to_string(), Value::String(new.render()));
503	            }
504	        }
505	
506	        Ok(())
507	    }
508	
509	    fn update_optional_dependencies(
510	        &mut self,
511	        updates: &[(String, Version)],
512	        _permit: &ApplyPermit,
513	    ) -> Result<(), ManifestError> {
514	        let section = self
515	            .doc
516	            .entry("optionalDependencies".to_string())
517	            .or_insert_with(|| Value::Object(Map::new()))
518	            .as_object_mut()
519	            .ok_or_else(|| ManifestError::FormattingNotPreserved {
520	                path: self.path.clone(),
521	                message: "optionalDependencies is not an object".to_string(),
522	            })?;
523	
524	        for (name, ver) in updates {
525	            section.insert(name.clone(), Value::String(ver.render().to_string()));
526	        }
527	
528	        Ok(())
529	    }
530	
531	    fn npm_role(&self) -> Option<NpmRole> {
532	        npm_role_from_doc(&self.doc)
533	    }
