234	fn npm_role_from_doc(doc: &Map<String, Value>) -> Option<NpmRole> {
235	    let has_os = doc.get("os").and_then(|v| v.as_array()).is_some_and(|a| !a.is_empty());
236	    let has_cpu = doc.get("cpu").and_then(|v| v.as_array()).is_some_and(|a| !a.is_empty());
237	
238	    if !has_os || !has_cpu {
239	        return None;
240	    }
241	
242	    let platform = doc
243	        .get("os")
244	        .and_then(|v| v.as_array())
245	        .and_then(|a| a.first())
246	        .and_then(|v| v.as_str())
247	        .map(str::to_string)?;
248	
249	    let arch = doc
250	        .get("cpu")
251	        .and_then(|v| v.as_array())
252	        .and_then(|a| a.first())
253	        .and_then(|v| v.as_str())
254	        .map(str::to_string)?;
255	
256	    // npm's standard `os`/`cpu` manifest fields have no libc/ABI concept at
257	    // all, so a real disk-discovered Linux napi platform package always
258	    // produces `abi: None` here -- but `napi.rs::role_to_triple`'s Linux
259	    // match arms all require a concrete ABI, meaning such a package could
260	    // never resolve to its triple. napi-rs's own package-generation
261	    // convention encodes the ABI in the package *name*'s suffix instead
262	    // (e.g. "@scope/pkg-linux-x64-gnu"), so infer it from there when the
263	    // platform is linux.
264	    let abi = if platform == "linux" {
265	        doc.get("name")
