473	        // section *before* mutating anything. This guarantees that a failed
474	        // update (dependency not found) leaves self.doc byte-for-byte
475	        // unchanged, including the overrides/resolutions tables below.
476	        let updated_in_section = self
477	            .doc
478	            .get(section_name)
479	            .and_then(|v| v.as_object())
480	            .is_some_and(|section| section.contains_key(name));
481	
482	        if !updated_in_section {
483	            return Err(ManifestError::DependencyNotFound {
484	                path: self.path.clone(),
485	                name: name.to_string(),
486	                kind,
487	            });
488	        }
489	
490	        if let Some(section) = self.doc.get_mut(section_name).and_then(|v| v.as_object_mut()) {
491	            section.insert(name.to_string(), Value::String(new.render()));
492	        }
493	
494	        if matches!(new, DepSpec::WorkspaceProtocol(_)) {
495	            return Ok(());
496	        }
497	
498	        for extra in ["overrides", "resolutions"] {
499	            if let Some(tbl) = self.doc.get_mut(extra).and_then(|v| v.as_object_mut())
500	                && tbl.get(name).is_some_and(|v| v.is_string())
501	            {
502	                tbl.insert(name.to_string(), Value::String(new.render()));
503	            }
504	        }
505	
506	        Ok(())
507	    }
