509	    fn update_optional_dependencies(
510	        &mut self,
511	        updates: &[(String, Version)],
512	        _permit: &ApplyPermit,
513	    ) -> Result<(), ManifestError> {
514	        let section = self
515	            .doc
516	            .entry("optionalDependencies".to_string())
517	            .or_insert_with(|| Value::Object(Map::new()))
518	            .as_object_mut()
519	            .ok_or_else(|| ManifestError::FormattingNotPreserved {
520	                path: self.path.clone(),
521	                message: "optionalDependencies is not an object".to_string(),
522	            })?;
523	
524	        for (name, ver) in updates {
525	            section.insert(name.clone(), Value::String(ver.render().to_string()));
526	        }
527	
528	        Ok(())
529	    }
