548	fn parse_npm_spec_str(s: &str, ws_kind: Option<WorkspaceKind>) -> DepSpec {
549	    if let Some(rest) = s.strip_prefix("workspace:") {
550	        if let Some(kind) = ws_kind {
551	            return DepSpec::WorkspaceProtocol(WorkspaceSpec {
552	                kind,
553	                suffix: rest.to_string(),
554	            });
555	        }
556	        return DepSpec::Opaque(format!("workspace:{rest}"));
557	    }
558	    if let Some(rest) = s.strip_prefix("catalog:") {
559	        let name = if rest.is_empty() { None } else { Some(rest.to_string()) };
560	        return DepSpec::Catalog(name);
561	    }
562	
563	    if crate::common::is_bare_semver(s)
564	        && let Ok(v) = Version::parse(s, VersionGrammar::SemVer)
565	    {
566	        return DepSpec::Exact(v);
567	    }
568	
569	    if let Ok(req) = VersionReq::parse(s, Ecosystem::Npm) {
570	        return DepSpec::Range(req, s.to_string());
571	    }
572	
573	    DepSpec::Opaque(s.to_string())
574	}
575	
576	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
577	    match spec {
578	        DepSpec::WorkspaceProtocol(workspace) => {
579	            if workspace.coverage(target).ok()? != callisto_model::Coverage::DoesNotCover {
580	                return None;
581	            }
582	            let range = workspace.range()?;
583	            let rewritten = if Version::parse(range, VersionGrammar::SemVer).is_ok() {
584	                target.render().to_string()
585	            } else {
586	                let req = VersionReq::parse(range, Ecosystem::Npm).ok()?;
587	                round_trip(&DepSpec::Range(req, range.to_string()), target)?.render()
588	            };
589	            let updated = workspace.with_range(&rewritten);
590	            if updated.coverage(target).ok()? != callisto_model::Coverage::Covers {
591	                return None;
592	            }
593	            Some(DepSpec::WorkspaceProtocol(updated))
594	        }
595	        DepSpec::Exact(_) => Some(DepSpec::Exact(target.clone())),
596	        DepSpec::Range(_, original) => {
597	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
598	            // A prerelease clause (`^2.0.0-next.0`) is one version; a hyphen range or a set of ranges is not.
599	            let core = rest.split(['-', '+']).next().unwrap_or(rest);
600	            if rest.contains([' ', '|']) || core.contains(['x', 'X', '*']) {
601	                return None;
602	            }
603	            if core != rest && Version::parse(rest, VersionGrammar::SemVer).is_err() {
604	                return None;
605	            }
606	            let rendered = format!("{prefix}{}", render_at_precision(target, core));
607	            let req = VersionReq::parse(&rendered, Ecosystem::Npm).ok()?;
608	            Some(DepSpec::Range(req, rendered))
609	        }
610	        _ => None,
611	    }
612	}
613	
614	fn render_at_precision(target: &Version, original_clause: &str) -> String {
615	    if target.is_prerelease() {
616	        return target.render().to_string();
617	    }
618	    let parts: Vec<&str> = original_clause.split('.').collect();
619	    let maj = target.major().unwrap_or(0);
620	    let min = target.minor().unwrap_or(0);
621	    let pat = target.patch().unwrap_or(0);
622	
623	    match parts.len() {
624	        1 => format!("{maj}"),
625	        2 => format!("{maj}.{min}"),
626	        _ => format!("{maj}.{min}.{pat}"),
627	    }
628	}
