630	pub fn detect_npm_workspace_kind(workspace_root: &Path) -> Result<Option<WorkspaceKind>, ManifestError> {
631	    let present = |name: &str| -> Result<bool, ManifestError> {
632	        let path = workspace_root.join(name);
633	        callisto_model::strict_fs::exists(&path).map_err(|e| ManifestError::Read {
634	            path,
635	            message: e.to_string(),
636	        })
637	    };
638	    if present("pnpm-lock.yaml")? || present("pnpm-workspace.yaml")? {
639	        return Ok(Some(WorkspaceKind::Pnpm));
640	    }
641	    if present("yarn.lock")? {
642	        return Ok(Some(WorkspaceKind::Yarn));
643	    }
644	    if present("package-lock.json")? {
645	        return Ok(Some(WorkspaceKind::Npm));
646	    }
647	
648	    let root_pkg_json = workspace_root.join("package.json");
649	    let content = callisto_model::strict_fs::read_optional(&root_pkg_json).map_err(|e| ManifestError::Read {
650	        path: root_pkg_json.clone(),
651	        message: e.to_string(),
652	    })?;
653	    if let Some(content) = content {
654	        let val = serde_json::from_str::<Value>(content.strip_prefix('\u{FEFF}').unwrap_or(&content)).map_err(|e| {
655	            ManifestError::Parse {
656	                path: root_pkg_json.clone(),
657	                format: ManifestFormat::PackageJson,
658	                message: e.to_string(),
659	            }
660	        })?;
661	        if val.get("workspaces").is_some() {
662	            return Ok(Some(WorkspaceKind::Npm));
663	        }
664	    }
665	
666	    Ok(None)
667	}
