638	    fn update_dependency_spec(
639	        &mut self,
640	        name: &str,
641	        kind: DepKind,
642	        at: &DepLocator,
643	        new: DepSpec,
644	        permit: &ApplyPermit,
645	    ) -> Result<(), ManifestError> {
646	        let not_found = || ManifestError::DependencyNotFound {
647	            path: self.path.clone(),
648	            name: name.to_string(),
649	            kind,
650	        };
651	        if kind == DepKind::Peer {
652	            return Err(not_found());
653	        }
654	
655	        let (section, target) = match at {
656	            DepLocator::Cargo { section, target, .. } => (section_name(*section), target.as_deref()),
657	            DepLocator::Unspecified => (section_name(kind), None),
658	            _ => return Err(not_found()),
659	        };
660	        let item = dependency_table(&self.document, section, target)
661	            .and_then(|table| table.get(name))
662	            .ok_or_else(not_found)?;
663	
664	        if is_inherited_item(item) {
665	            let root_manifest = self.inheritance.as_ref().ok_or_else(not_found)?.root_manifest.clone();
666	            let root_cargo = self.workspace_root.join(&root_manifest);
667	            if self.absolute == root_cargo {
668	                return Err(ManifestError::InvariantViolation {
669	                    path: self.path.clone(),
670	                    message: format!(
671	                        "dependency `{name}` is workspace-inherited but this manifest IS the workspace root (`{}`); refusing to delegate to avoid overwriting the just-written root manifest with a stale in-memory document",
672	                        root_cargo.display()
673	                    ),
674	                });
675	            }
676	            let mut ws_res = WorkspaceCargoResolver::load_at(&self.workspace_root, &root_manifest)?;
677	            ws_res.write_dependency(name, new, permit)?;
678	            return ws_res.persist(permit);
679	        }
680	
681	        let item = dependency_table_mut(&mut self.document, section, target)
682	            .and_then(|table| table.get_mut(name))
683	            .ok_or_else(not_found)?;
684	        set_dependency_version(item, new.render()).map_err(|()| ManifestError::UnrecognizedDependencyValue {
685	            path: self.path.clone(),
686	            name: name.to_string(),
687	        })
688	    }
