776	fn parse_cargo_dep_item(item: &toml_edit::Item, kind: &mut DepKind) -> DepSpec {
777	    if let Some(table) = item.as_inline_table() {
778	        if table.get("optional").and_then(|o| o.as_bool()) == Some(true) {
779	            *kind = DepKind::Optional;
780	        }
781	        if let Some(v_str) = table.get("version").and_then(|v| v.as_str()) {
782	            return parse_cargo_spec_str(v_str);
783	        }
784	    } else if let Some(table) = item.as_table() {
785	        if table.get("optional").and_then(|o| o.as_bool()) == Some(true) {
786	            *kind = DepKind::Optional;
787	        }
788	        if let Some(v_str) = table.get("version").and_then(|v| v.as_str()) {
789	            return parse_cargo_spec_str(v_str);
790	        }
791	    } else if let Some(v_str) = item.as_str() {
792	        return parse_cargo_spec_str(v_str);
793	    }
794	
795	    DepSpec::Opaque(item.to_string().trim().to_string())
796	}
797	
798	fn parse_cargo_spec_str(s: &str) -> DepSpec {
799	    if crate::common::is_bare_semver(s)
800	        && let Ok(v) = Version::parse(s, VersionGrammar::SemVer)
801	    {
802	        return DepSpec::CargoBare(v);
803	    }
804	    if let Ok(req) = VersionReq::parse(s, Ecosystem::Cargo) {
805	        return DepSpec::Range(req, s.to_string());
806	    }
807	    DepSpec::Opaque(s.to_string())
808	}
