810	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
811	    match spec {
812	        DepSpec::CargoBare(_) => Some(DepSpec::CargoBare(target.clone())),
813	        DepSpec::Range(_, original) => {
814	            if original.contains(',') {
815	                let parts: Vec<&str> = original.split(',').collect();
816	                let mut rewritten_parts = Vec::new();
817	                for part in parts {
818	                    let part_trimmed = part.trim();
819	                    let (prefix, rest) = crate::common::split_single_operator_prefix(part_trimmed)?;
820	                    if prefix.starts_with('>')
821	                        || prefix.starts_with('=')
822	                        || prefix.starts_with('^')
823	                        || prefix.starts_with('~')
824	                    {
825	                        let rendered = format!("{prefix}{}", render_at_precision(target, rest));
826	                        rewritten_parts.push(rendered);
827	                    } else if prefix.starts_with('<') {
828	                        // Upper-bound clauses are never rewritten (the clause text
829	                        // is preserved verbatim), but we must still check whether
830	                        // the target actually falls within it. If it doesn't, the
831	                        // rewrite would silently produce an impossible constraint
832	                        // (e.g. ">=2.1.0, <2.0.0"), so decline with None. If it
833	                        // does, the upper bound clause is passed through unchanged.
834	                        let bound = Version::parse(rest, target.grammar()).ok()?;
835	                        let ordering = target.partial_compare(&bound)?;
836	                        let exceeds_bound = if prefix == "<=" {
837	                            ordering == std::cmp::Ordering::Greater
838	                        } else {
839	                            ordering != std::cmp::Ordering::Less
840	                        };
841	                        if exceeds_bound {
842	                            return None;
843	                        }
844	                        rewritten_parts.push(part_trimmed.to_string());
845	                    } else {
846	                        rewritten_parts.push(part_trimmed.to_string());
847	                    }
848	                }
849	                let rendered = rewritten_parts.join(", ");
850	                let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
851	                return Some(DepSpec::Range(req, rendered));
852	            }
853	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
854	            if rest.contains('*') {
855	                return None;
856	            }
857	            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
858	            let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
859	            Some(DepSpec::Range(req, rendered))
860	        }
861	        _ => None,
862	    }
863	}
864	
865	fn render_at_precision(target: &Version, original_clause: &str) -> String {
866	    if original_clause.contains('-') || target.is_prerelease() {
867	        return target.render().to_string();
868	    }
869	    let parts: Vec<&str> = original_clause.split('.').collect();
870	    let maj = target.major().unwrap_or(0);
871	    let min = target.minor().unwrap_or(0);
872	    let pat = target.patch().unwrap_or(0);
873	
874	    match parts.len() {
875	        1 => format!("{maj}"),
876	        2 => format!("{maj}.{min}"),
877	        _ => format!("{maj}.{min}.{pat}"),
878	    }
879	}
