57	/// Reads a manifest's effective version from text the caller already holds. `manifest_at` supplies any other
58	/// workspace-relative manifest by path, or `None` when there is none, so a Cargo `version.workspace = true` resolves
59	/// against the workspace that governs the package at the same revision. `reads` remembers the workspace manifests
60	/// already seen, so reading many packages of one revision parses each once.
61	///
62	/// # Errors
63	///
64	/// The manifest does not parse, declares an invalid version, or inherits one that no governing workspace declares; or
65	/// `manifest_at` fails.
66	pub fn read_effective_version<E: From<ManifestError>>(
67	    format: ManifestFormat,
68	    source: &str,
69	    path: &Path,
70	    reads: &mut WorkspaceReads,
71	    mut manifest_at: impl FnMut(&Path) -> Result<Option<String>, E>,
72	) -> Result<Option<EffectiveManifestVersion>, E> {
73	    let identity = read_identity(format, source, path)?;
74	    let (version, authority) = match identity.version {
75	        Some(VersionSource::Literal(raw)) => {
76	            let version = Version::parse(&raw, format.ecosystem().version_grammar()).map_err(|source| {
77	                ManifestError::InvalidVersion {
78	                    path: path.to_path_buf(),
79	                    raw,
80	                    source,
81	                }
82	            })?;
83	            (version, path.to_path_buf())
84	        }
85	        Some(VersionSource::InheritedFromWorkspace) => {
86	            let missing = |path: &Path| ManifestError::MissingField {
87	                path: path.to_path_buf(),
88	                field: "workspace.package.version",
89	            };
90	            let member = cargo::parse_manifest(path, source)?;
91	            let root_manifest = reads
92	                .enclosing(path, &member, &mut manifest_at)?
93	                .ok_or_else(|| missing(path))?;
94	            let version = reads
95	                .version(&root_manifest, &mut manifest_at)?
96	                .ok_or_else(|| missing(&root_manifest))?;
97	            (version, root_manifest)
98	        }
99	        None => return Ok(None),
100	    };
101	    Ok(Some(EffectiveManifestVersion { version, authority }))
102	}
