210	/// Context passed to open() to supply workspace-wide inheritance facts.
211	pub struct OpenContext<'a> {
212	    pub workspace_root: &'a Path,
213	    /// The inheritance of the Cargo workspace rooted at `workspace_root`, loaded once and shared by its members.
214	    /// A manifest governed by another Cargo workspace loads that workspace's own.
215	    pub cargo_workspace: Option<Arc<WorkspaceInheritance>>,
216	    /// The other Cargo workspaces met while opening manifests.
217	    pub cargo_roots: CargoRoots,
218	    pub npm_workspace_kind: Option<WorkspaceKind>,
219	}
