310	/// Test-observability counter: total number of times [`open`] has been
311	/// invoked. Production code never reads this; it exists so callers (in
312	/// particular, callers building a caching layer on top of `open()`) can
313	/// write regression tests asserting that a given manifest path is opened
314	/// (read + parsed from disk) at most once per logical operation, instead of
315	/// once per call site. See `callisto-graph`'s `manifest_cache` module.
316	static OPEN_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
317	
318	/// Resets the internal manifest-open call counter to zero. Intended for use in test setup.
319	pub fn reset_open_call_count() {
320	    OPEN_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
321	}
322	
323	/// Reads the current value of the internal manifest-open call counter.
324	pub fn open_call_count() -> usize {
325	    OPEN_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
326	}
327	
328	/// Test-observability counter: total number of times a `Manifest`
329	/// implementor's `persist` has returned `Ok`. Production code never reads
330	/// this; it exists so callers can write regression tests asserting a given
331	/// manifest path is flushed to disk at most once per logical operation.
332	/// Distinct from `OPEN_CALL_COUNT` so open-count and persist-count
333	/// assertions in the same test are independent.
334	static PERSIST_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
335	
336	/// Resets the internal manifest-persist call counter to zero. Intended for use in test setup.
337	pub fn reset_persist_call_count() {
338	    PERSIST_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
339	}
340	
341	/// Reads the current value of the internal manifest-persist call counter.
342	pub fn persist_call_count() -> usize {
343	    PERSIST_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
344	}
345	
346	/// Increments PERSIST_CALL_COUNT by one. Called by each Manifest
347	/// implementor's persist() immediately after its own atomic_write returns
348	/// Ok; PERSIST_CALL_COUNT itself is private to this module, so this is the
349	/// only way other modules in this crate may increment it.
350	pub(crate) fn record_persist_call() {
351	    PERSIST_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
352	}
353	
354	/// Test-observability counter: total number of times
355	/// [`cargo::WorkspaceCargoResolver::load`] has been invoked. Deliberately
356	/// NOT folded into `OPEN_CALL_COUNT`: `OpenContext::for_workspace_root`
357	/// calls `WorkspaceCargoResolver::load` unconditionally whenever the
358	/// workspace root has a `Cargo.toml`, regardless of whether that plan
359	/// touches any workspace-inherited field -- merging the two counters would
360	/// make nearly every existing `open_call_count()` assertion in this crate
361	/// (and `callisto-graph`) spuriously count an unrelated resolver load.
362	/// Production code never reads this.
363	static RESOLVER_LOAD_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
364	
365	/// Resets the internal `WorkspaceCargoResolver::load` call counter to zero. Intended for use in test setup.
366	pub fn reset_resolver_load_call_count() {
367	    RESOLVER_LOAD_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
368	}
369	
370	/// Reads the current value of the internal `WorkspaceCargoResolver::load` call counter.
371	pub fn resolver_load_call_count() -> usize {
372	    RESOLVER_LOAD_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
373	}
374	
375	/// Increments RESOLVER_LOAD_CALL_COUNT by one. Called at the top of
376	/// `WorkspaceCargoResolver::load`, mirroring where `open()` increments
377	/// `OPEN_CALL_COUNT` -- counts every invocation, including ones that go on
378	/// to fail parsing.
379	pub(crate) fn record_resolver_load_call() {
380	    RESOLVER_LOAD_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
381	}
382	
383	/// Test-observability counter: total number of times
384	/// [`cargo::WorkspaceCargoResolver::persist`] has returned `Ok`. Kept
385	/// separate from `PERSIST_CALL_COUNT` for the same reason
386	/// `RESOLVER_LOAD_CALL_COUNT` is kept separate from `OPEN_CALL_COUNT`:
387	/// `PERSIST_CALL_COUNT` is documented and consumed as scoped exclusively to
388	/// the `Manifest` trait's three implementors. Production code never reads
389	/// this.
390	static RESOLVER_PERSIST_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
391	
392	/// Resets the internal `WorkspaceCargoResolver::persist` call counter to zero. Intended for use in test setup.
393	pub fn reset_resolver_persist_call_count() {
394	    RESOLVER_PERSIST_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
395	}
396	
397	/// Reads the current value of the internal `WorkspaceCargoResolver::persist` call counter.
398	pub fn resolver_persist_call_count() -> usize {
399	    RESOLVER_PERSIST_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
400	}
401	
402	/// Increments RESOLVER_PERSIST_CALL_COUNT by one. Called by
403	/// `WorkspaceCargoResolver::persist` immediately after its own
404	/// `atomic_write` returns `Ok`.
405	pub(crate) fn record_resolver_persist_call() {
406	    RESOLVER_PERSIST_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
407	}
