300	/// Rewrites a dependency entry's `version` to `new_str`, preserving decor
301	/// across the three shapes Cargo allows for a dependency value: a bare
302	/// version string, an inline table with a `version` key, or a full
303	/// `[dependencies.name]` table with a `version` key. `Err(())` for any
304	/// other shape -- callers map that to their own
305	/// `ManifestError::UnrecognizedDependencyValue` (which needs a `path` this
306	/// function has no access to). Shared by the member-manifest
307	/// ([`CargoToml::update_dependency_spec`]) and workspace-root
308	/// ([`WorkspaceCargoResolver::write_dependency`]) dependency-write paths,
309	/// which were previously two copies of this exact three-shape dance,
310	/// differing only in which path they report on error.
311	fn set_dependency_version(item: &mut toml_edit::Item, new_str: String) -> Result<(), ()> {
312	    if let Some(value) = item.as_value_mut() {
313	        if value.is_str() {
314	            let decor = value.decor().clone();
315	            let mut new_val = toml_edit::Value::from(new_str);
316	            *new_val.decor_mut() = decor;
317	            *value = new_val;
318	        } else if let Some(inline) = value.as_inline_table_mut() {
319	            if let Some(existing_ver) = inline.get_mut("version") {
320	                let decor = existing_ver.decor().clone();
321	                let mut new_val = toml_edit::Value::from(new_str);
322	                *new_val.decor_mut() = decor;
323	                *existing_ver = new_val;
324	            } else {
325	                inline.insert("version", toml_edit::Value::from(new_str));
326	            }
327	        } else {
328	            return Err(());
329	        }
330	    } else if let Some(tbl) = item.as_table_mut() {
331	        let decor = tbl.get("version").and_then(|i| i.as_value()).map(|v| v.decor().clone());
332	        tbl.insert("version", toml_edit::value(new_str));
333	        if let Some(decor) = decor
334	            && let Some(new_item) = tbl.get_mut("version").and_then(|i| i.as_value_mut())
335	        {
336	            *new_item.decor_mut() = decor;
337	        }
338	    } else {
339	        return Err(());
340	    }
341	    Ok(())
342	}
