344	/// [`crate::read_identity`]'s `Cargo.toml` implementation: parses `source`
345	/// and extracts `[package].name` plus a [`crate::VersionSource`] for
346	/// `[package].version` -- `InheritedFromWorkspace` when it's
347	/// `version.workspace = true`, `Literal` when it's a bare string, `None`
348	/// when the field or the whole `[package]` table is absent.
349	pub(crate) fn identity_from_source(source: &str, path: &Path) -> Result<crate::ManifestIdentity, ManifestError> {
350	    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
351	    let doc: toml_edit::DocumentMut = clean.parse().map_err(|e: toml_edit::TomlError| ManifestError::Parse {
352	        path: path.to_path_buf(),
353	        format: ManifestFormat::CargoToml,
354	        message: e.to_string(),
355	    })?;
356	
357	    let name = cargo_package_name(&doc).map(str::to_string);
358	    let version = doc.get("package").and_then(|p| p.get("version")).and_then(|v| {
359	        if let Some(s) = v.as_str() {
360	            Some(crate::VersionSource::Literal(s.to_string()))
361	        } else if v.get("workspace").and_then(|w| w.as_bool()) == Some(true) {
362	            Some(crate::VersionSource::InheritedFromWorkspace)
363	        } else {
364	            None
365	        }
366	    });
367	
368	    Ok(crate::ManifestIdentity { name, version })
369	}
