371	pub(crate) fn workspace_version_from_source(source: &str, path: &Path) -> Result<Option<Version>, ManifestError> {
372	    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
373	    let doc: toml_edit::DocumentMut = clean.parse().map_err(|e: toml_edit::TomlError| ManifestError::Parse {
374	        path: path.to_path_buf(),
375	        format: ManifestFormat::CargoToml,
376	        message: e.to_string(),
377	    })?;
378	    workspace_package_version(&doc, path)
379	}
