381	fn workspace_package_version(doc: &toml_edit::DocumentMut, path: &Path) -> Result<Option<Version>, ManifestError> {
382	    let Some(raw) = doc
383	        .get("workspace")
384	        .and_then(|w| w.get("package"))
385	        .and_then(|p| p.get("version"))
386	        .and_then(|v| v.as_str())
387	    else {
388	        return Ok(None);
389	    };
390	    Version::parse(raw, VersionGrammar::SemVer)
391	        .map(Some)
392	        .map_err(|e| ManifestError::Parse {
393	            path: path.to_path_buf(),
394	            format: ManifestFormat::CargoToml,
395	            message: format!("invalid [workspace.package] version: {e}"),
396	        })
397	}
