400	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
401	        let text = self.fingerprint.apply(&self.document.to_string());
402	        crate::atomic::atomic_write(&self.absolute, &text, permit).map_err(|e| ManifestError::Write {
403	            path: self.path.clone(),
404	            message: e.to_string(),
405	        })?;
406	        crate::record_persist_call();
407	        Ok(())
408	    }
