414	    fn ecosystem(&self) -> Ecosystem {
415	        Ecosystem::Cargo
416	    }
417	
418	    fn is_publishable(&self) -> bool {
419	        let p = match self.document.get("package") {
420	            Some(p) => p,
421	            None => return false,
422	        };
423	        if let Some(pub_val) = p.get("publish") {
424	            if let Some(b) = pub_val.as_bool() {
425	                return b;
426	            }
427	            if let Some(arr) = pub_val.as_array() {
428	                return !arr.is_empty();
429	            }
430	        }
431	        true
432	    }
