438	    fn bin_names(&self) -> Result<Vec<String>, ManifestError> {
439	        let Some(package) = cargo_package_name(&self.document) else {
440	            return Ok(Vec::new());
441	        };
442	        let unreadable = |path: &Path, error: std::io::Error| ManifestError::Read {
443	            path: self.path.parent().unwrap_or(Path::new("")).join(path),
444	            message: error.to_string(),
445	        };
446	        let mut names = BTreeSet::new();
447	        if let Some(bins) = self.document.get("bin").and_then(|bin| bin.as_array_of_tables()) {
448	            for target in bins.iter() {
449	                let name = target
450	                    .get("name")
451	                    .and_then(|name| name.as_str())
452	                    .map(str::to_owned)
453	                    .or_else(|| {
454	                        let path = target.get("path").and_then(|path| path.as_str()).map(Path::new)?;
455	                        let stem = path.file_stem()?;
456	                        if stem == "main" {
457	                            path.parent()?.file_name()?.to_str().map(str::to_owned)
458	                        } else {
459	                            stem.to_str().map(str::to_owned)
460	                        }
461	                    })
462	                    .unwrap_or_else(|| package.to_owned());
463	                names.insert(name);
464	            }
465	        }
466	        let autobins = self
467	            .document
468	            .get("package")
469	            .and_then(|item| item.get("autobins"))
470	            .and_then(|item| item.as_bool())
471	            .unwrap_or(true);
472	        if autobins {
473	            let dir = self.absolute.parent().unwrap_or(Path::new("."));
474	            let is_file =
475	                |path: &Path| callisto_model::strict_fs::exists(path).map(|present| present && path.is_file());
476	            if is_file(&dir.join("src/main.rs")).map_err(|error| unreadable(Path::new("src/main.rs"), error))? {
477	                names.insert(package.to_owned());
478	            }
479	            // No `src/bin` is no extra binaries; one that cannot be read is an error.
480	            let entries = match fs::read_dir(dir.join("src/bin")) {
481	                Ok(entries) => entries,
482	                Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(names.into_iter().collect()),
483	                Err(error) => return Err(unreadable(Path::new("src/bin"), error)),
484	            };
485	            for entry in entries {
486	                let path = entry.map_err(|error| unreadable(Path::new("src/bin"), error))?.path();
487	                if path.is_file() && path.extension().is_some_and(|ext| ext == "rs") {
488	                    if let Some(name) = path.file_stem().and_then(|stem| stem.to_str()) {
489	                        names.insert(name.to_owned());
490	                    }
491	                } else if path.is_dir()
492	                    && is_file(&path.join("main.rs")).map_err(|error| unreadable(Path::new("src/bin"), error))?
493	                    && let Some(name) = path.file_name().and_then(|name| name.to_str())
494	                {
495	                    names.insert(name.to_owned());
496	                }
497	            }
498	        }
499	        Ok(names.into_iter().collect())
500	    }
