502	    fn napi_lib_name(&self) -> Option<String> {
503	        let lib = self.document.get("lib");
504	        let cdylib = lib
505	            .and_then(|lib| lib.get("crate-type"))
506	            .and_then(|types| types.as_array())
507	            .is_some_and(|types| types.iter().any(|kind| kind.as_str() == Some("cdylib")));
508	        let napi = self
509	            .document
510	            .get("dependencies")
511	            .and_then(|deps| deps.as_table_like())
512	            .is_some_and(|deps| deps.contains_key("napi"));
513	        if !(cdylib && napi) {
514	            return None;
515	        }
516	        lib.and_then(|lib| lib.get("name"))
517	            .and_then(|name| name.as_str())
518	            .or_else(|| cargo_package_name(&self.document))
519	            .map(|name| name.replace('-', "_"))
520	    }
