530	    fn current_version(&self) -> Result<Version, ManifestError> {
531	        if self.inherited_version {
532	            if let Some(ref inh) = self.inheritance
533	                && let Some(ref v) = inh.version
534	            {
535	                return Ok(v.clone());
536	            }
537	            return Err(ManifestError::WorkspaceInherited {
538	                path: self.path.clone(),
539	                key: "version".to_string(),
540	            });
541	        }
542	
543	        let raw = self
544	            .document
545	            .get("package")
546	            .and_then(|p| p.get("version"))
547	            .and_then(|v| v.as_str())
548	            .ok_or_else(|| ManifestError::MissingField {
549	                path: self.path.clone(),
550	                field: "package.version",
551	            })?;
552	
553	        Version::parse(raw, VersionGrammar::SemVer).map_err(|source| ManifestError::InvalidVersion {
554	            path: self.path.clone(),
555	            raw: raw.to_string(),
556	            source,
