560	    fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
561	        if self.inherited_version {
562	            // The member uses `version.workspace = true` (or `version = { workspace = true }`).
563	            // Routing the bump to [workspace.package] would silently change the version for
564	            // every other workspace member. Instead, write an explicit pinned version directly
565	            // to this member's [package] section, replacing the workspace-inherited entry with
566	            // a standalone string value.
567	            let pkg = self
568	                .document
569	                .get_mut("package")
570	                .and_then(|p| p.as_table_mut())
571	                .ok_or_else(|| ManifestError::MissingField {
572	                    path: self.path.clone(),
573	                    field: "package",
574	                })?;
575	            pkg.insert("version", toml_edit::value(v.render()));
576	            self.inherited_version = false;
577	            return Ok(());
578	        }
579	
580	        let pkg = self
581	            .document
582	            .get_mut("package")
583	            .and_then(|p| p.as_table_mut())
584	            .ok_or_else(|| ManifestError::MissingField {
585	                path: self.path.clone(),
586	                field: "package",
587	            })?;
588	
589	        crate::common::set_scalar_preserving_decor(pkg, "version", v.render());
590	        Ok(())
591	    }
