597	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
598	        let mut entries = Vec::new();
599	
600	        for (section_name, section_kind, target) in dependency_locations(&self.document) {
601	            if let Some(table) = dependency_table(&self.document, section_name, target.as_deref()) {
602	                for (name, item) in table.iter() {
603	                    let is_inherited = is_inherited_item(item);
604	                    let mut kind = section_kind;
605	                    let local_spec = parse_cargo_dep_item(item, &mut kind);
606	                    let inherited_dep = self.inheritance.as_ref().and_then(|inh| inh.inherited(name));
607	                    let package_name = if is_inherited {
608	                        inherited_dep.map(|dep| dep.package_name).unwrap_or(name)
609	                    } else {
610	                        cargo_dependency_package_name(name, item)
611	                    };
612	
613	                    let spec = if is_inherited {
614	                        if let Some(inherited_dep) = inherited_dep {
615	                            inherited_dep.spec.clone()
616	                        } else {
617	                            DepSpec::Opaque("workspace = true (unresolved)".to_string())
618	                        }
619	                    } else {
620	                        local_spec
621	                    };
622	
623	                    entries.push(DependencyEntry {
624	                        name: name.to_string(),
625	                        package_name: package_name.to_string(),
626	                        kind,
627	                        spec,
628	                        inherited: is_inherited,
629	                        locator: DepLocator::cargo(section_kind, target.clone()),
630	                    });
631	                }
632	            }
633	        }
634	
635	        Box::new(entries.into_iter())
636	    }
