690	    fn update_optional_dependencies(
691	        &mut self,
692	        _updates: &[(String, Version)],
693	        _permit: &ApplyPermit,
694	    ) -> Result<(), ManifestError> {
695	        Err(ManifestError::UnsupportedOperation {
696	            path: self.path.clone(),
697	            format: ManifestFormat::CargoToml,
698	            operation: "update_optional_dependencies",
699	        })
700	    }
701	}
