703	const DEPENDENCY_SECTIONS: [(&str, DepKind); 3] = [
704	    ("dependencies", DepKind::Runtime),
705	    ("dev-dependencies", DepKind::Dev),
706	    ("build-dependencies", DepKind::Build),
707	];
708	
709	/// The Cargo section a dependency kind is declared in; optional dependencies sit beside runtime ones.
710	fn section_name(kind: DepKind) -> &'static str {
711	    match kind {
712	        DepKind::Dev => "dev-dependencies",
713	        DepKind::Build => "build-dependencies",
714	        _ => "dependencies",
715	    }
716	}
