718	/// Every dependency table a manifest can declare: the top-level ones, then the same three
719	/// under each `[target.<cfg>]` key. Owned, so callers can mutate the document while iterating.
720	fn dependency_locations(doc: &toml_edit::DocumentMut) -> Vec<(&'static str, DepKind, Option<String>)> {
721	    let mut locations: Vec<_> = DEPENDENCY_SECTIONS
722	        .iter()
723	        .map(|(section, kind)| (*section, *kind, None))
724	        .collect();
725	    if let Some(targets) = doc.get("target").and_then(|item| item.as_table_like()) {
726	        for (cfg, _) in targets.iter() {
727	            for (section, kind) in DEPENDENCY_SECTIONS {
728	                locations.push((section, kind, Some(cfg.to_string())));
729	            }
730	        }
731	    }
732	    locations
733	}
734	
735	fn dependency_table<'a>(
736	    doc: &'a toml_edit::DocumentMut,
737	    section: &str,
738	    target: Option<&str>,
739	) -> Option<&'a dyn toml_edit::TableLike> {
740	    let parent = match target {
741	        Some(cfg) => doc.get("target")?.get(cfg)?,
742	        None => doc.as_item(),
743	    };
744	    parent.get(section)?.as_table_like()
745	}
746	
747	fn dependency_table_mut<'a>(
748	    doc: &'a mut toml_edit::DocumentMut,
749	    section: &str,
750	    target: Option<&str>,
751	) -> Option<&'a mut dyn toml_edit::TableLike> {
752	    let parent = match target {
753	        Some(cfg) => doc.get_mut("target")?.get_mut(cfg)?,
754	        None => doc.as_item_mut(),
755	    };
756	    parent.get_mut(section)?.as_table_like_mut()
757	}
