759	/// True when the declaration is `{ workspace = true }`.
760	fn is_inherited_item(item: &toml_edit::Item) -> bool {
761	    item.as_inline_table()
762	        .and_then(|table| table.get("workspace"))
763	        .and_then(|workspace| workspace.as_bool())
764	        == Some(true)
765	        || item
766	            .as_table()
767	            .and_then(|table| table.get("workspace"))
768	            .and_then(|workspace| workspace.as_bool())
769	            == Some(true)
