912	impl WorkspaceCargoResolver {
913	    /// Loads the Cargo workspace root manifest at `workspace_root/root_manifest`, keeping `root_manifest` (relative to
914	    /// `workspace_root`) as the path every report, diff and staged file names it by.
915	    pub fn load_at(workspace_root: &Path, root_manifest: &Path) -> Result<Self, ManifestError> {
916	        let rel_path = workspace_relative(root_manifest).map_err(|e| ManifestError::Read {
917	            path: root_manifest.to_path_buf(),
918	            message: e.to_string(),
919	        })?;
920	        let absolute_path = workspace_root.join(&rel_path);
921	        Self::read_from(rel_path, absolute_path)
922	    }
