924	    pub fn load(root_manifest_path: &Path) -> Result<Self, ManifestError> {
925	        let rel_path = if root_manifest_path.is_absolute() {
926	            root_manifest_path
927	                .file_name()
928	                .map(PathBuf::from)
929	                .unwrap_or_else(|| PathBuf::from("Cargo.toml"))
930	        } else {
931	            workspace_relative(root_manifest_path).map_err(|e| ManifestError::Read {
932	                path: root_manifest_path.to_path_buf(),
933	                message: e.to_string(),
934	            })?
935	        };
936	        Self::read_from(rel_path, root_manifest_path.to_path_buf())
937	    }
938	
939	    fn read_from(rel_path: PathBuf, absolute_path: PathBuf) -> Result<Self, ManifestError> {
940	        crate::record_resolver_load_call();
941	        let content = fs::read_to_string(&absolute_path).map_err(|e| ManifestError::Read {
942	            path: rel_path.clone(),
943	            message: e.to_string(),
944	        })?;
945	
946	        let doc: toml_edit::DocumentMut = content
947	            .parse()
948	            .map_err(|e: toml_edit::TomlError| ManifestError::Parse {
949	                path: rel_path.clone(),
950	                format: ManifestFormat::CargoToml,
951	                message: e.to_string(),
952	            })?;
953	
954	        Ok(WorkspaceCargoResolver {
955	            root_path: rel_path,
956	            absolute_path,
957	            document: doc,
958	        })
959	    }
