961	    pub fn inheritance(&self) -> Result<WorkspaceInheritance, ManifestError> {
962	        let version = workspace_package_version(&self.document, &self.root_path)?;
963	
964	        let mut dependencies = BTreeMap::new();
965	        if let Some(table) = self
966	            .document
967	            .get("workspace")
968	            .and_then(|w| w.get("dependencies"))
969	            .and_then(|d| d.as_table_like())
970	        {
971	            for (name, item) in table.iter() {
972	                let mut kind = DepKind::Runtime;
973	                let spec = parse_cargo_dep_item(item, &mut kind);
974	                dependencies.insert(
975	                    name.to_string(),
976	                    DependencyEntry {
977	                        name: name.to_string(),
978	                        package_name: cargo_dependency_package_name(name, item).to_string(),
979	                        kind,
980	                        spec,
981	                        inherited: false,
982	                        locator: DepLocator::default(),
983	                    },
984	                );
985	            }
986	        }
987	
988	        Ok(WorkspaceInheritance {
989	            root_manifest: self.root_path.clone(),
990	            version,
991	            dependencies,
992	        })
993	    }
