995	    /// Returns the `[workspace.package] version` currently on disk, or `None`
996	    /// when no such field exists (e.g. the workspace does not declare a shared
997	    /// version). Used by `apply_version_plan`'s idempotency guard.
998	    pub fn workspace_version(&self) -> Result<Option<Version>, ManifestError> {
999	        workspace_package_version(&self.document, &self.root_path)
1000	    }
1001	
1002	    /// Pure in-memory mutation of `[workspace.package] version` -- no disk
1003	    /// I/O. Mirrors `CargoToml`/`PackageJson`/`PyprojectToml`'s
1004	    /// `write_version`, which likewise never touches disk; callers must
1005	    /// call [`Self::persist`] explicitly afterward. `_permit` is accepted
1006	    /// (unused) purely for call-site symmetry with `persist`, which does
1007	    /// require one.
1008	    pub fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
1009	        let ws = self
1010	            .document
1011	            .get_mut("workspace")
1012	            .and_then(|w| w.as_table_like_mut())
1013	            .ok_or_else(|| ManifestError::MissingField {
1014	                path: self.root_path.clone(),
1015	                field: "workspace",
1016	            })?;
1017	
1018	        let pkg = ws
1019	            .entry("package")
1020	            .or_insert(toml_edit::Item::Table(toml_edit::Table::new()))
1021	            .as_table_mut()
1022	            .ok_or_else(|| ManifestError::MissingField {
1023	                path: self.root_path.clone(),
1024	                field: "workspace.package",
1025	            })?;
1026	
1027	        crate::common::set_scalar_preserving_decor(pkg, "version", v.render());
1028	        Ok(())
1029	    }
1030	
1031	    /// Pure in-memory mutation of a `[workspace.dependencies]` entry -- no
1032	    /// disk I/O. See [`Self::write_version`]'s doc for why this no longer
1033	    /// persists internally; callers must call [`Self::persist`] explicitly
1034	    /// afterward.
1035	    pub fn write_dependency(&mut self, name: &str, new: DepSpec, _permit: &ApplyPermit) -> Result<(), ManifestError> {
1036	        let ws = self
1037	            .document
1038	            .get_mut("workspace")
1039	            .and_then(|w| w.as_table_mut())
1040	            .ok_or_else(|| ManifestError::MissingField {
1041	                path: self.root_path.clone(),
1042	                field: "workspace",
1043	            })?;
1044	
1045	        let deps = ws
1046	            .entry("dependencies")
1047	            .or_insert(toml_edit::Item::Table(toml_edit::Table::new()))
1048	            .as_table_like_mut()
1049	            .ok_or_else(|| ManifestError::MissingField {
1050	                path: self.root_path.clone(),
1051	                field: "workspace.dependencies",
1052	            })?;
1053	
1054	        let item = deps.get_mut(name).ok_or_else(|| ManifestError::DependencyNotFound {
1055	            path: self.root_path.clone(),
1056	            name: name.to_string(),
1057	            kind: DepKind::Runtime,
1058	        })?;
1059	
1060	        let new_str = new.render();
1061	        set_dependency_version(item, new_str).map_err(|()| ManifestError::UnrecognizedDependencyValue {
1062	            path: self.root_path.clone(),
1063	            name: name.to_string(),
1064	        })?;
1065	
1066	        Ok(())
1067	    }
1068	
1069	    /// Flushes the in-memory document to disk via
1070	    /// [`crate::atomic::atomic_write`]. Distinct, explicitly-called step --
1071	    /// see [`Self::write_version`]/[`Self::write_dependency`]'s docs --
1072	    /// mirroring the `Manifest` trait's `persist` across `CargoToml`,
1073	    /// `PackageJson`, and `PyprojectToml`.
1074	    pub fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
1075	        let text = self.document.to_string();
1076	        crate::atomic::atomic_write(&self.absolute_path, &text, permit).map_err(|e| ManifestError::Write {
1077	            path: self.root_path.clone(),
1078	            message: e.to_string(),
1079	        })?;
1080	        crate::record_resolver_persist_call();
1081	        Ok(())
1082	    }
1083	}
