104	/// Extracts a package's name and version source directly from `source`,
105	/// the raw text of a manifest matching `format`. Pure and I/O-free.
106	///
107	/// Replaces hand-parsing `Cargo.toml`/`package.json`/`pyproject.toml` at
108	/// call sites that already hold manifest content as a string rather than a
109	/// path `open()` can read from disk (audit pattern B) -- e.g. a `git show`
110	/// blob, or a directory-walker's pre-read buffer.
111	///
112	/// `path` is used only to build accurate `ManifestError::Parse` locations
113	/// on a parse failure; it need not exist on disk. Only the three
114	/// canonical-identity formats ([`Ecosystem::CANONICAL`]) are supported --
115	/// any other format returns `Err(ManifestError::ReadOnlyFormat)`.
116	pub fn read_identity(format: ManifestFormat, source: &str, path: &Path) -> Result<ManifestIdentity, ManifestError> {
117	    match format {
118	        ManifestFormat::CargoToml => cargo::identity_from_source(source, path),
119	        ManifestFormat::PackageJson => npm::identity_from_source(source, path),
120	        ManifestFormat::PyprojectToml => python::identity_from_source(source, path),
121	        other => Err(ManifestError::ReadOnlyFormat {
122	            path: path.to_path_buf(),
123	            format: other,
124	            reason: "read_identity only supports the three canonical-identity manifest formats \
125	                     (Cargo.toml, package.json, pyproject.toml)",
126	        }),
127	    }
128	}
