148	/// Trait implemented by per-ecosystem manifest editors.
149	pub trait Manifest: Send + Sync {
150	    fn path(&self) -> &Path;
151	    fn ecosystem(&self) -> Ecosystem;
152	    fn role(&self) -> ManifestRole;
153	    fn package_name(&self) -> Result<String, ManifestError>;
154	    fn current_version(&self) -> Result<Version, ManifestError>;
155	    fn write_version(&mut self, v: &Version, permit: &ApplyPermit) -> Result<(), ManifestError>;
156	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError>;
157	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = callisto_model::DependencyEntry> + '_>;
158	    fn update_dependency_spec(
159	        &mut self,
160	        name: &str,
161	        kind: callisto_model::DepKind,
162	        at: &callisto_model::DepLocator,
163	        new: DepSpec,
164	        permit: &ApplyPermit,
165	    ) -> Result<(), ManifestError>;
166	    fn is_publishable(&self) -> bool {
167	        true
168	    }
169	    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
170	        if !self.is_publishable() {
171	            return vec![callisto_model::PublishTarget::None];
172	        }
173	        match self.ecosystem() {
174	            Ecosystem::Cargo => vec![callisto_model::PublishTarget::CratesIo],
175	            Ecosystem::Npm => vec![callisto_model::PublishTarget::Npm {
176	                registry: None,
177	                access: None,
178	            }],
179	            _ => vec![callisto_model::PublishTarget::None],
180	        }
181	    }
182	    fn update_optional_dependencies(
183	        &mut self,
184	        updates: &[(String, Version)],
185	        permit: &ApplyPermit,
186	    ) -> Result<(), ManifestError>;
187	    /// The role this manifest's own content declares itself to play (see
188	    /// [`NpmRole`]). `None` for every ecosystem other than npm, and for an
189	    /// npm manifest that isn't a platform package. Overridden by
190	    /// `PackageJson`, whose implementation derives this from the document
191	    /// already parsed at `open()` time -- no second disk read required.
192	    fn npm_role(&self) -> Option<NpmRole> {
193	        None
194	    }
195	    /// Executable names this package builds; empty for a library-only package.
196	    fn bin_names(&self) -> Result<Vec<String>, ManifestError> {
197	        Ok(Vec::new())
198	    }
199	    /// The lib name of a napi-rs addon crate: a `cdylib` depending on `napi`.
200	    fn napi_lib_name(&self) -> Option<String> {
201	        None
202	    }
203	    /// The workspace-level declaration that a `{ workspace = true }` dependency named `name` inherits. `None` for every
204	    /// ecosystem other than Cargo, and for a manifest that does not inherit it.
205	    fn inherited_dependency(&self, _name: &str) -> Option<InheritedDep<'_>> {
206	        None
207	    }
208	}
