221	/// Cargo workspaces met while opening manifests, remembered so each is read once however many members inherit from it.
222	#[derive(Default)]
223	pub struct CargoRoots {
224	    reads: std::sync::Mutex<WorkspaceReads>,
225	    inheritance: std::sync::Mutex<std::collections::BTreeMap<std::path::PathBuf, Arc<WorkspaceInheritance>>>,
226	}
227	
228	fn locked<T>(mutex: &std::sync::Mutex<T>) -> std::sync::MutexGuard<'_, T> {
229	    mutex.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
230	}
231	
232	impl<'a> OpenContext<'a> {
233	    /// Builds an [`OpenContext`] rooted at `root` by resolving Cargo
234	    /// workspace inheritance (when `root/Cargo.toml` exists) and detecting
235	    /// the npm workspace kind. This is the single reusable constructor for
236	    /// the "check Cargo.toml exists, load workspace inheritance, detect npm
237	    /// workspace kind" sequence that call sites previously reimplemented
238	    /// independently (audit pattern: duplication) -- see
239	    /// `callisto-graph`'s `walk`, `lib` (`Workspace::base_versions`),
240	    /// `apply`, and `commands::version` modules.
241	    ///
242	    /// # Errors
243	    ///
244	    /// A root `Cargo.toml` or `package.json` that exists but cannot be read or parsed. An inheriting member
245	    /// could not be opened without it, so a missing context is an error, never an empty one.
246	    pub fn for_workspace_root(root: &'a Path) -> Result<OpenContext<'a>, callisto_model::ManifestError> {
247	        let cargo_manifest = Path::new("Cargo.toml");
248	        let cargo_workspace = if callisto_model::strict_fs::exists(&root.join(cargo_manifest)).map_err(|e| {
249	            callisto_model::ManifestError::Read {
250	                path: cargo_manifest.to_path_buf(),
251	                message: e.to_string(),
252	            }
253	        })? {
254	            Some(Arc::new(
255	                WorkspaceCargoResolver::load_at(root, cargo_manifest)?.inheritance()?,
256	            ))
257	        } else {
258	            None
259	        };
260	
261	        let npm_workspace_kind = detect_npm_workspace_kind(root)?;
262	
263	        Ok(OpenContext {
264	            workspace_root: root,
265	            cargo_workspace,
266	            cargo_roots: CargoRoots::default(),
267	            npm_workspace_kind,
268	        })
269	    }
270	
271	    /// The inheritance a Cargo manifest at `manifest` (workspace-relative, already parsed as `doc`) draws on: that of the
272	    /// Cargo workspace that governs it, which need not be the one at `workspace_root`.
273	    ///
274	    /// # Errors
275	    ///
276	    /// No Cargo workspace governs it, or the one that does cannot be read.
277	    pub(crate) fn cargo_inheritance(
278	        &self,
279	        manifest: &Path,
280	        doc: &toml_edit::DocumentMut,
281	    ) -> Result<Arc<WorkspaceInheritance>, ManifestError> {
282	        let found =
283	            locked(&self.cargo_roots.reads).enclosing(manifest, doc, cargo::read_manifest_text(self.workspace_root))?;
284	        let Some(root_manifest) = found else {
285	            return Err(ManifestError::Read {
286	                path: manifest.to_path_buf(),
287	                message: "declares .workspace = true but no Cargo workspace governs it: no Cargo.toml at or above its \
288	                          directory has a [workspace] table"
289	                    .to_string(),
290	            });
291	        };
292	        if let Some(shared) = self
293	            .cargo_workspace
294	            .as_ref()
295	            .filter(|shared| shared.root_manifest == root_manifest)
296	        {
297	            return Ok(Arc::clone(shared));
298	        }
299	        let mut loaded = locked(&self.cargo_roots.inheritance);
300	        if let Some(known) = loaded.get(&root_manifest) {
301	            return Ok(Arc::clone(known));
302	        }
303	        let inheritance =
304	            Arc::new(WorkspaceCargoResolver::load_at(self.workspace_root, &root_manifest)?.inheritance()?);
305	        loaded.insert(root_manifest, Arc::clone(&inheritance));
306	        Ok(inheritance)
307	    }
308	}
