409	/// Opens a manifest file matching `decl.format`.
410	pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Box<dyn Manifest>, ManifestError> {
411	    OPEN_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
412	    if decl.role == ManifestRole::Lockfile {
413	        return Err(ManifestError::ReadOnlyFormat {
414	            path: decl.path.clone(),
415	            format: decl.format,
416	            reason: "lockfiles are regenerated via subprocess, never opened as a Manifest handle",
417	        });
418	    }
419	
420	    match decl.format {
421	        ManifestFormat::CargoToml => Ok(Box::new(CargoToml::open(decl, ctx)?)),
422	        ManifestFormat::PackageJson => Ok(Box::new(PackageJson::open(decl, ctx)?)),
423	        ManifestFormat::PyprojectToml => Ok(Box::new(PyprojectToml::open(decl, ctx)?)),
424	        other => Err(ManifestError::ReadOnlyFormat {
425	            path: decl.path.clone(),
426	            format: other,
427	            reason: "not implemented yet",
428	        }),
429	    }
430	}
