432	/// Dispatches spec round-trip rewriting to the appropriate ecosystem handler.
433	pub fn round_trip(ecosystem: Ecosystem, spec: &DepSpec, target: &Version) -> Option<DepSpec> {
434	    match (ecosystem, spec) {
435	        (Ecosystem::Cargo, _) => cargo::round_trip(spec, target),
436	        (Ecosystem::Npm, _) => npm::round_trip(spec, target),
437	        (Ecosystem::Pypi, _) => python::round_trip(spec, target),
438	        _ => None,
439	    }
440	}
