351	impl Manifest for PyprojectToml {
352	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
353	        let content = self.render();
354	        atomic_write(&self.absolute, &content, permit).map_err(|e| ManifestError::Write {
355	            path: self.path.clone(),
356	            message: e.to_string(),
357	        })?;
358	        crate::record_persist_call();
359	        Ok(())
360	    }
361	
362	    fn path(&self) -> &Path {
363	        &self.path
364	    }
365	
366	    fn ecosystem(&self) -> Ecosystem {
367	        Ecosystem::Pypi
368	    }
369	
370	    fn role(&self) -> ManifestRole {
371	        self.role.clone()
372	    }
373	
374	    fn bin_names(&self) -> Result<Vec<String>, ManifestError> {
375	        Ok(self
376	            .document
377	            .get("project")
378	            .and_then(|project| project.get("scripts"))
379	            .and_then(|scripts| scripts.as_table_like())
380	            .map(|scripts| scripts.iter().map(|(name, _)| name.to_string()).collect())
381	            .unwrap_or_default())
382	    }
383	
384	    fn package_name(&self) -> Result<String, ManifestError> {
385	        python_package_name(&self.document)
386	            .map(|s| s.to_string())
387	            .ok_or_else(|| ManifestError::MissingField {
388	                path: self.path.clone(),
389	                field: "project.name / tool.poetry.name / tool.flit.metadata.module",
390	            })
391	    }
392	
393	    fn current_version(&self) -> Result<Version, ManifestError> {
394	        // 1. PEP 621 [project].version
395	        let raw_ver = self
396	            .document
397	            .get("project")
398	            .and_then(|p| p.get("version"))
399	            .and_then(|v| v.as_str())
400	            // 2. Poetry [tool.poetry].version
401	            .or_else(|| {
402	                self.document
403	                    .get("tool")
404	                    .and_then(|t| t.get("poetry"))
405	                    .and_then(|p| p.get("version"))
406	                    .and_then(|v| v.as_str())
407	            })
408	            // 3. Flit [tool.flit.metadata].version
409	            .or_else(|| {
410	                self.document
411	                    .get("tool")
412	                    .and_then(|t| t.get("flit"))
413	                    .and_then(|f| f.get("metadata"))
414	                    .and_then(|m| m.get("version"))
415	                    .and_then(|v| v.as_str())
416	            });
417	
418	        let raw = raw_ver.ok_or_else(|| ManifestError::MissingField {
419	            path: self.path.clone(),
420	            field: "project.version / tool.poetry.version",
421	        })?;
422	
423	        Version::parse(raw, VersionGrammar::Pep440).map_err(|e| ManifestError::InvalidVersion {
424	            path: self.path.clone(),
425	            raw: raw.to_string(),
426	            source: e,
427	        })
428	    }
429	
430	    fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
431	        let new_ver = v.render();
432	
433	        let has_project_version = self.document.get("project").and_then(|p| p.get("version")).is_some();
434	
435	        if has_project_version {
436	            if let Some(proj) = self.document.get_mut("project").and_then(|p| p.as_table_like_mut()) {
437	                crate::common::set_scalar_preserving_decor(proj, "version", new_ver);
438	            }
439	        } else if let Some(poetry) = self
440	            .document
441	            .get_mut("tool")
442	            .and_then(|t| t.get_mut("poetry"))
443	            .and_then(|p| p.as_table_like_mut())
444	        {
445	            crate::common::set_scalar_preserving_decor(poetry, "version", new_ver);
446	        } else if let Some(flit) = self
447	            .document
448	            .get_mut("tool")
449	            .and_then(|t| t.get_mut("flit"))
450	            .and_then(|f| f.get_mut("metadata"))
451	            .and_then(|m| m.as_table_like_mut())
452	        {
453	            crate::common::set_scalar_preserving_decor(flit, "version", new_ver);
454	        } else {
455	            self.document["project"]["version"] = value(new_ver);
456	        }
457	
458	        Ok(())
459	    }
460	
461	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
462	        let mut entries = Vec::new();
463	
464	        // 1. PEP 621 [project].dependencies (array of requirement strings)
465	        if let Some(deps) = self
466	            .document
467	            .get("project")
468	            .and_then(|p| p.get("dependencies"))
469	            .and_then(|d| d.as_array())
470	        {
471	            entries.extend(requirement_entries(
472	                deps,
473	                DepKind::Runtime,
474	                &DepContainer::ProjectDependencies,
475	            ));
476	        }
477	
478	        // 1b. PEP 621 [project.optional-dependencies]: extras ship in the published metadata, so a
479	        // pin there goes stale exactly like a runtime one.
480	        if let Some(extras) = self
481	            .document
482	            .get("project")
483	            .and_then(|p| p.get("optional-dependencies"))
484	            .and_then(|d| d.as_table_like())
485	        {
486	            for (extra, group) in extras.iter() {
487	                if let Some(requirements) = group.as_array() {
488	                    entries.extend(requirement_entries(
489	                        requirements,
490	                        DepKind::Optional,
491	                        &DepContainer::Extra(extra.to_string()),
492	                    ));
493	                }
494	            }
495	        }
496	
497	        // 2. Poetry [tool.poetry.dependencies]
498	        if let Some(table) = self
499	            .document
500	            .get("tool")
501	            .and_then(|t| t.get("poetry"))
502	            .and_then(|p| p.get("dependencies"))
503	            .and_then(|d| d.as_table_like())
504	        {
505	            for (name, item) in table.iter() {
506	                if name == "python" {
507	                    continue;
508	                }
509	                // `as_table_like()` covers both inline tables
510	                // (`foo = { version = "^1.2" }`) and dotted-table syntax
511	                // (`[tool.poetry.dependencies.foo]` / `version = "^1.2"`),
512	                // which parse to different `toml_edit::Item` variants but
513	                // must both be recognized -- previously only the inline-table
514	                // variant was handled, so a dotted-table Poetry dependency
515	                // silently vanished from the graph entirely.
516	                let raw_req = match item {
517	                    toml_edit::Item::Value(toml_edit::Value::String(s)) => Some(s.value().as_str()),
518	                    _ => item
519	                        .as_table_like()
520	                        .and_then(|t| t.get("version"))
521	                        .and_then(|v| v.as_str()),
522	                };
523	
524	                let spec = match raw_req {
525	                    Some(req_str) => {
526	                        // Poetry allows caret/tilde/wildcard syntax on top of
527	                        // PEP 440 (e.g. `^1.2`, `~1.2.3`, `1.*`), which
528	                        // `pep440_rs` cannot parse directly -- normalize it
529	                        // to an equivalent PEP 440 range first.
530	                        let normalized = normalize_poetry_version_spec(req_str);
531	                        match VersionReq::parse(&normalized, Ecosystem::Pypi) {
532	                            Ok(spec) => DepSpec::Range(spec, req_str.to_string()),
533	                            // Genuinely unrepresentable (syntax this
534	                            // normalizer doesn't cover) -- never silently
535	                            // drop the dependency; keep it visible in the
536	                            // graph as an opaque spec instead.
537	                            Err(_) => DepSpec::Opaque(req_str.to_string()),
538	                        }
539	                    }
540	                    // No `version` key at all -- a path/git/url dependency
541	                    // (e.g. `foo = { git = "...", tag = "v1.0" }`) or an
542	                    // unrecognized value shape. Still must not silently
543	                    // vanish from the graph.
544	                    None => {
545	                        DepSpec::Opaque("non-versioned dependency (path/git/url or unrecognized shape)".to_string())
546	                    }
547	                };
548	
549	                entries.push(DependencyEntry {
550	                    name: name.to_string(),
551	                    package_name: name.to_string(),
552	                    inherited: false,
553	                    kind: DepKind::Runtime,
554	                    spec,
555	                    locator: DepLocator::python(DepContainer::PoetryDependencies, None),
556	                });
557	            }
558	        }
559	
560	        Box::new(entries.into_iter())
561	    }
562	
563	    fn update_dependency_spec(
564	        &mut self,
565	        name: &str,
566	        kind: DepKind,
567	        at: &DepLocator,
568	        new: DepSpec,
569	        _permit: &ApplyPermit,
570	    ) -> Result<(), ManifestError> {
571	        let new_spec_str = match new {
572	            DepSpec::Range(req, _) => req.render().to_string(),
573	            DepSpec::Exact(v) => format!("=={}", v.render()),
574	            _ => return Ok(()),
575	        };
576	        let not_found = || ManifestError::DependencyNotFound {
577	            path: self.path.clone(),
578	            name: name.to_string(),
579	            kind,
580	        };
581	
582	        let DepLocator::Python {
583	            container, position, ..
584	        } = at
585	        else {
586	            return Err(not_found());
587	        };
588	        match container {
589	            DepContainer::PoetryDependencies => {
590	                let table = self
591	                    .document
592	                    .get_mut("tool")
593	                    .and_then(|t| t.get_mut("poetry"))
594	                    .and_then(|p| p.get_mut("dependencies"))
595	                    .and_then(|d| d.as_table_like_mut())
596	                    .ok_or_else(not_found)?;
597	                let existing = table.get_mut(name).ok_or_else(not_found)?;
598	                match existing.as_table_like_mut() {
599	                    Some(fields) => {
600	                        fields.insert("version", value(new_spec_str));
601	                    }
602	                    None => {
603	                        table.insert(name, value(new_spec_str));
604	                    }
605	                }
606	            }
607	            container => {
608	                let position = position.ok_or_else(not_found)?;
609	                let requirements = match container {
610	                    DepContainer::ProjectDependencies => {
611	                        self.document.get_mut("project").and_then(|p| p.get_mut("dependencies"))
612	                    }
613	                    DepContainer::Extra(extra) => self
614	                        .document
615	                        .get_mut("project")
616	                        .and_then(|p| p.get_mut("optional-dependencies"))
617	                        .and_then(|d| d.get_mut(extra.as_str())),
618	                    _ => None,
619	                }
620	                .and_then(|item| item.as_array_mut())
621	                .ok_or_else(not_found)?;
622	                // The array may differ from the one the locator was read from: refuse to rewrite another dependency.
623	                let rewritten = requirements
624	                    .get(position)
625	                    .and_then(|item| item.as_str())
626	                    .and_then(|full_req| rewrite_requirement(full_req, name, &new_spec_str))
627	                    .ok_or_else(not_found)?;
628	                requirements.replace(position, rewritten);
629	            }
630	        }
631	
632	        Ok(())
633	    }
634	
635	    fn is_publishable(&self) -> bool {
636	        // A pyproject.toml without [project].name or [tool.poetry].name is a
637	        // workspace root or build-system-only file — not a publishable package.
638	        let has_pep621_name = self
639	            .document
640	            .get("project")
641	            .and_then(|p| p.get("name"))
642	            .and_then(|n| n.as_str())
643	            .is_some();
644	        let has_poetry_name = self
645	            .document
646	            .get("tool")
647	            .and_then(|t| t.get("poetry"))
648	            .and_then(|p| p.get("name"))
649	            .and_then(|n| n.as_str())
650	            .is_some();
651	        has_pep621_name || has_poetry_name
652	    }
653	
654	    fn publish_targets(&self) -> Vec<PublishTarget> {
655	        if !self.is_publishable() {
656	            return vec![PublishTarget::None];
657	        }
658	        vec![PublishTarget::Pypi { index: None }]
659	    }
660	
661	    fn update_optional_dependencies(
662	        &mut self,
663	        updates: &[(String, Version)],
664	        _permit: &ApplyPermit,
665	    ) -> Result<(), ManifestError> {
666	        if updates.is_empty() {
667	            return Ok(());
668	        }
669	
670	        // [project.optional-dependencies] is a table of group_name → [PEP 508 strings].
671	        // Collect the table keys first to avoid borrow conflicts.
672	        let group_keys: Vec<String> = self
673	            .document
674	            .get("project")
675	            .and_then(|p| p.get("optional-dependencies"))
676	            .and_then(|od| od.as_table_like())
677	            .map(|t| t.iter().map(|(k, _)| k.to_string()).collect())
678	            .unwrap_or_default();
679	
680	        for group_key in &group_keys {
681	            let Some(arr) = self
682	                .document
683	                .get_mut("project")
684	                .and_then(|p| p.get_mut("optional-dependencies"))
685	                .and_then(|od| od.get_mut(group_key.as_str()))
686	                .and_then(|g| g.as_array_mut())
687	            else {
688	                continue;
689	            };
690	
691	            for idx in 0..arr.len() {
692	                let Some(full_req) = arr.get(idx).and_then(|item| item.as_str()) else {
693	                    continue;
694	                };
695	                let Some(req) = Requirement::parse(full_req) else {
696	                    continue;
697	                };
698	
699	                if let Some((_dep_name, new_ver)) = updates.iter().find(|(dep_name, _)| {
700	                    normalize_pypi_package_name(dep_name) == normalize_pypi_package_name(&req.name)
701	                }) {
702	                    let new_req = Requirement {
703	                        name: req.name.clone(),
704	                        extras: req.extras.clone(),
705	                        spec: Some(format!(">={}", new_ver.render())),
706	                        marker: req.marker.clone(),
707	                    };
708	                    arr.replace(idx, new_req.render());
709	                }
710	            }
711	        }
712	
713	        Ok(())
714	    }
715	}
716	
717	/// Rewrites a PEP 508 dependency constraint to pin it to `target`.
718	///
719	/// The following single-clause and two-clause forms are recognized and rewritten:
720	///
721	/// - `==X.Y.Z` — exact pin — is rewritten to `==NEW`.
722	/// - `~=X.Y.Z` — compatible release — is rewritten to `~=NEW`.
723	/// - `>=X.Y.Z` — lower bound only — is rewritten to `>=NEW`.
724	/// - `>=X.Y.Z,<A.B` — two-clause range — is rewritten to `>=NEW,<NEXT_MAJOR`
725	///   where `NEXT_MAJOR` equals `target.major() + 1`.
726	///
727	/// A pre-release or dev/local target (e.g. a `snapshot` version) is rendered
728	/// in full rather than truncated to `major.minor.patch`, the same precision
729	/// rule `cargo::round_trip` applies for SemVer.
730	///
731	/// All other forms return `None` — including upper-bound-only (`<`, `<=`),
732	/// exclusion (`!=`), compound expressions beyond the two-clause range above,
733	/// and wildcard `*`. Callers must leave the original constraint unchanged
734	/// when `None` is returned.
735	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
736	    // Only Range specs are produced by iter_dependencies for Python.
737	    let original = match spec {
738	        DepSpec::Range(_, raw) => raw.as_str(),
739	        _ => return None,
740	    };
741	
742	    let trimmed = original.trim();
743	
744	    // Compound range: ">=X.Y.Z,<A.B" → ">=NEW,<NEXT_MAJOR"
745	    if trimmed.contains(',') {
746	        return rewrite_range(trimmed, target);
747	    }
748	
749	    // Single-clause forms matched by their PEP 508 operator prefix.
750	    if trimmed.starts_with("==") {
751	        return rewrite_single(trimmed, "==", target);
752	    }
753	    if trimmed.starts_with("~=") {
754	        return rewrite_single(trimmed, "~=", target);
755	    }
756	    if trimmed.starts_with(">=") {
757	        return rewrite_single(trimmed, ">=", target);
758	    }
759	    // Poetry's own operators: bare caret and tilde (PEP 440's `~=` was handled above).
760	    if let Some(core) = trimmed.strip_prefix('^') {
761	        return rewrite_poetry_operator("^", core, target);
762	    }
763	    if let Some(core) = trimmed.strip_prefix('~').filter(|rest| !rest.starts_with('=')) {
764	        return rewrite_poetry_operator("~", core, target);
765	    }
766	
767	    // Unknown or unsupported form (e.g. "<", "<=", "!=", bare "*").
768	    None
769	}
770	
771	/// Rewrites a single-clause PEP 508 specifier, preserving the operator.
772	fn rewrite_single(original: &str, op: &str, target: &Version) -> Option<DepSpec> {
773	    // Validate that the original clause parses correctly (guards against
774	    // unknown version syntax that happens to start with a known prefix).
775	    let _rest = original.strip_prefix(op)?;
776	    let rendered = format!("{op}{}", render_target(op, target)?);
777	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
778	    Some(DepSpec::Range(req, rendered))
779	}
780	
781	/// Rewrites a Poetry caret or tilde clause to the same window around the stable `target`; the caller writes it as the
782	/// equivalent PEP 440 range, which Poetry reads too. A pre-release target has no caret or tilde form, so it is left alone.
783	fn rewrite_poetry_operator(op: &str, core: &str, target: &Version) -> Option<DepSpec> {
784	    parse_version_core(core)?;
785	    if target.is_prerelease() {
786	        return None;
787	    }
788	    let rendered = format!("{op}{}", render_target(op, target)?);
789	    let req = VersionReq::parse(&normalize_poetry_version_spec(&rendered), Ecosystem::Pypi).ok()?;
790	    Some(DepSpec::Range(req, rendered))
791	}
792	
793	/// Renders `target` at the precision a rewritten spec should carry, for use after `op`:
794	/// `major.minor.patch` for a stable release; the version in full for a pre-release or
795	/// dev target paired with `==`/`!=` (the only operators PEP 440 allows on a local version);
796	/// the version with its local segment stripped for every other operator, since PEP 440
797	/// forbids `>=`, `<=`, `>`, `<` and `~=` from carrying one.
798	fn render_target(op: &str, target: &Version) -> Option<String> {
799	    if target.is_prerelease() {
800	        let full = target.render();
801	        if op == "==" || op == "!=" {
802	            return Some(full.to_string());
803	        }
804	        return Some(full.split('+').next().unwrap_or(full).to_string());
805	    }
806	    Some(format!("{}.{}.{}", target.major()?, target.minor()?, target.patch()?))
807	}
808	
809	/// Rewrites a two-clause `>=X.Y.Z,<A.B` range to `>=NEW,<NEXT_MAJOR`.
810	///
811	/// Returns `None` for anything that does not match exactly this two-clause
812	/// lower/upper pattern, including specs with three or more clauses (e.g.
813	/// `>=1.0,<2.0,!=1.5.0`) where silently dropping extra clauses would produce
814	/// a semantically incorrect constraint.
815	fn rewrite_range(original: &str, target: &Version) -> Option<DepSpec> {
816	    // Reject any spec with more than two comma-separated clauses: rewriting
817	    // would silently discard the extra clauses, changing the semantics.
818	    if original.split(',').count() != 2 {
819	        return None;
820	    }
821	
822	    let mut parts = original.splitn(2, ',');
823	    let lower = parts.next()?.trim();
824	    let upper = parts.next()?.trim();
825	
826	    // Lower clause must be `>=…`.
827	    if !lower.starts_with(">=") {
828	        return None;
829	    }
830	    // Upper clause must be strictly `<…` (not `<=`).
831	    if !upper.starts_with('<') || upper.starts_with("<=") {
832	        return None;
833	    }
834	
835	    // A window of one minor (`>=0.1.0,<0.2`) stays one minor wide; any other upper bound becomes the next major.
836	    let lower_core = lower
837	        .strip_prefix(">=")
838	        .and_then(|version| parse_version_core(version.trim()));
839	    let upper_core = upper
840	        .strip_prefix('<')
841	        .and_then(|version| parse_version_core(version.trim()));
842	    let one_minor_window = matches!(
843	        (lower_core, upper_core),
844	        (Some((lower_major, Some(lower_minor), _)), Some((upper_major, Some(upper_minor), upper_patch)))
845	            if upper_major == lower_major && upper_minor == lower_minor + 1 && upper_patch.unwrap_or(0) == 0
846	    );
847	    let upper_bound = if one_minor_window {
848	        format!("{}.{}", target.major()?, target.minor()? + 1)
849	    } else {
850	        (target.major()? + 1).to_string()
851	    };
852	    let rendered = format!(">={},<{upper_bound}", render_target(">=", target)?);
853	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
854	    Some(DepSpec::Range(req, rendered))
855	}
856	
857	/// Every requirement string of one array as a dependency edge addressed by its index in `container`.
858	fn requirement_entries<'a>(
859	    requirements: &'a toml_edit::Array,
860	    kind: DepKind,
861	    container: &'a DepContainer,
862	) -> impl Iterator<Item = DependencyEntry> + 'a {
863	    requirements.iter().enumerate().filter_map(move |(position, item)| {
864	        let locator = DepLocator::python(container.clone(), Some(position));
865	        pep508_entry(item.as_str()?, kind, locator)
866	    })
867	}
868	
869	/// One PEP 508 requirement string as a dependency edge, or `None` when it names no package.
870	fn pep508_entry(full_req_str: &str, kind: DepKind, locator: DepLocator) -> Option<DependencyEntry> {
871	    // `Requirement::parse` couldn't extract even a package name (an empty string or a
872	    // marker-only fragment): there is no name to key an entry on.
873	    let req = Requirement::parse(full_req_str)?;
874	    let req_str = req.spec.clone().unwrap_or_else(|| "*".to_string());
875	    let parsed_req_str = req.spec.as_deref().unwrap_or(">=0.0.0");
876	    let spec = match VersionReq::parse(parsed_req_str, Ecosystem::Pypi) {
877	        Ok(spec) => DepSpec::Range(spec, req_str),
878	        // A PEP 508 clause `pep440_rs` can't parse (exotic or malformed syntax): keep the
879	        // dependency visible in the graph rather than silently dropping it.
880	        Err(_) => DepSpec::Opaque(req_str),
881	    };
882	    Some(DependencyEntry {
883	        name: req.name.clone(),
884	        package_name: req.name.clone(),
885	        inherited: false,
886	        kind,
887	        spec,
888	        locator,
889	    })
890	}
891	
892	/// The requirement string with `name`'s constraint replaced by `new_spec_str`, or `None` when
893	/// the requirement names another package.
894	fn rewrite_requirement(full_req: &str, name: &str, new_spec_str: &str) -> Option<String> {
895	    let req = Requirement::parse(full_req)?;
896	    if normalize_pypi_package_name(&req.name) != normalize_pypi_package_name(name) {
897	        return None;
898	    }
899	    let formatted_spec = if new_spec_str.starts_with(['<', '>', '=', '!', '~']) {
900	        new_spec_str.to_string()
901	    } else {
902	        format!(">={new_spec_str}")
903	    };
904	    Some(
905	        Requirement {
906	            name: req.name.clone(),
907	            extras: req.extras.clone(),
908	            spec: Some(formatted_spec),
909	            marker: req.marker.clone(),
910	        }
911	        .render(),
912	    )
913	}
