563	    fn update_dependency_spec(
564	        &mut self,
565	        name: &str,
566	        kind: DepKind,
567	        at: &DepLocator,
568	        new: DepSpec,
569	        _permit: &ApplyPermit,
570	    ) -> Result<(), ManifestError> {
571	        let new_spec_str = match new {
572	            DepSpec::Range(req, _) => req.render().to_string(),
573	            DepSpec::Exact(v) => format!("=={}", v.render()),
574	            _ => return Ok(()),
575	        };
576	        let not_found = || ManifestError::DependencyNotFound {
577	            path: self.path.clone(),
578	            name: name.to_string(),
579	            kind,
580	        };
581	
582	        let DepLocator::Python {
583	            container, position, ..
584	        } = at
585	        else {
586	            return Err(not_found());
587	        };
588	        match container {
589	            DepContainer::PoetryDependencies => {
590	                let table = self
591	                    .document
592	                    .get_mut("tool")
593	                    .and_then(|t| t.get_mut("poetry"))
594	                    .and_then(|p| p.get_mut("dependencies"))
595	                    .and_then(|d| d.as_table_like_mut())
596	                    .ok_or_else(not_found)?;
597	                let existing = table.get_mut(name).ok_or_else(not_found)?;
598	                match existing.as_table_like_mut() {
599	                    Some(fields) => {
600	                        fields.insert("version", value(new_spec_str));
601	                    }
602	                    None => {
603	                        table.insert(name, value(new_spec_str));
604	                    }
605	                }
606	            }
607	            container => {
608	                let position = position.ok_or_else(not_found)?;
609	                let requirements = match container {
610	                    DepContainer::ProjectDependencies => {
611	                        self.document.get_mut("project").and_then(|p| p.get_mut("dependencies"))
612	                    }
613	                    DepContainer::Extra(extra) => self
614	                        .document
615	                        .get_mut("project")
616	                        .and_then(|p| p.get_mut("optional-dependencies"))
617	                        .and_then(|d| d.get_mut(extra.as_str())),
618	                    _ => None,
619	                }
620	                .and_then(|item| item.as_array_mut())
621	                .ok_or_else(not_found)?;
622	                // The array may differ from the one the locator was read from: refuse to rewrite another dependency.
623	                let rewritten = requirements
624	                    .get(position)
625	                    .and_then(|item| item.as_str())
626	                    .and_then(|full_req| rewrite_requirement(full_req, name, &new_spec_str))
627	                    .ok_or_else(not_found)?;
628	                requirements.replace(position, rewritten);
629	            }
630	        }
631	
632	        Ok(())
633	    }
