1	//! Callisto's single disk-write primitive.
2	//!
3	//! This lives in Layer 1 (`callisto-model`) rather than alongside the manifest
4	//! editors because durable file replacement is not a manifest concern: the
5	//! changelog writer, the pre-mode state file, and the config scaffolder all
6	//! need it too. Hosting it here means those callers do not have to take a
7	//! dependency on `callisto-manifests` purely to reach the filesystem.
8	
9	use std::io::{self, Write};
10	use std::path::Path;
11	
12	use crate::ApplyPermit;
13	use tempfile::NamedTempFile;
14	
15	/// Durably replaces `path`'s contents with `content`.
16	///
17	/// The [`ApplyPermit`] is unused at runtime and exists purely as a compile-time
18	/// obligation: this is callisto's single disk-write primitive, so requiring a
19	/// permit here means no code path can reach the filesystem without having first
20	/// consulted the dry-run flag. See [`crate::permit`].
21	///
22	/// # Errors
23	///
24	/// Returns the first I/O error encountered: creating parent directories, writing the temp file,
25	/// flushing, fsyncing, persisting (renaming) to `path`, or syncing the directory that holds it.
26	pub fn atomic_write(path: &Path, content: &str, permit: &ApplyPermit) -> io::Result<()> {
27	    write_durably(path, content, true, permit)
28	}
29	
30	/// [`atomic_write`] that never replaces: it fails with `AlreadyExists` if anything is at `path` when the file is put in
31	/// place, including a file created by another process after this call began. The content is durable before it appears.
32	///
33	/// # Errors
34	///
35	/// `AlreadyExists` when `path` is taken, otherwise the same errors as [`atomic_write`].
36	pub fn atomic_write_new(path: &Path, content: &str, permit: &ApplyPermit) -> io::Result<()> {
37	    write_durably(path, content, false, permit)
38	}
39	
40	fn write_durably(path: &Path, content: &str, replace: bool, permit: &ApplyPermit) -> io::Result<()> {
41	    let _permit = permit;
42	    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
43	    let parent = if raw_parent.as_os_str().is_empty() {
44	        Path::new(".")
45	    } else {
46	        raw_parent
47	    };
48	    let created_parent = !parent.try_exists()?;
49	    std::fs::create_dir_all(parent)?;
50	
51	    let mut temp = temp_file_in(parent)?;
52	    if replace {
53	        match_existing_mode(temp.as_file(), path)?;
54	    }
55	    temp.write_all(content.as_bytes())?;
56	    temp.flush()?;
57	    temp.as_file().sync_all()?;
58	    if replace {
59	        temp.persist(path).map_err(|e| e.error)?;
60	    } else {
61	        temp.persist_noclobber(path).map_err(|e| e.error)?;
62	    }
63	
64	    sync_directory(parent)?;
65	    // A directory this call created is itself a new entry in its parent.
66	    if created_parent && let Some(grandparent) = parent.parent().filter(|dir| !dir.as_os_str().is_empty()) {
67	        sync_directory(grandparent)?;
68	    }
69	    Ok(())
70	}
71	
72	/// A temp file whose mode follows the process umask like any new file, instead of `tempfile`'s owner-only `0600`.
73	fn temp_file_in(dir: &Path) -> io::Result<NamedTempFile> {
74	    #[cfg(unix)]
75	    {
76	        use std::os::unix::fs::PermissionsExt;
77	        tempfile::Builder::new()
78	            .permissions(std::fs::Permissions::from_mode(0o666))
79	            .tempfile_in(dir)
80	    }
81	    #[cfg(not(unix))]
82	    {
83	        NamedTempFile::new_in(dir)
84	    }
85	}
86	
87	/// Gives the temp file the mode of the file it replaces; a new file keeps the umask-derived mode.
88	fn match_existing_mode(temp: &std::fs::File, target: &Path) -> io::Result<()> {
89	    #[cfg(unix)]
90	    {
91	        use std::os::unix::fs::PermissionsExt;
92	        match std::fs::metadata(target) {
93	            Ok(existing) => {
94	                temp.set_permissions(std::fs::Permissions::from_mode(existing.permissions().mode() & 0o7777))
95	            }
96	            Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(()),
97	            Err(error) => Err(error),
98	        }
99	    }
100	    #[cfg(not(unix))]
101	    {
102	        let _ = (temp, target);
103	        Ok(())
104	    }
105	}
106	
107	/// Flushes `dir`'s entries so a rename survives power loss. A directory that may not be opened for reading (a `-wx`
108	/// mode, `PermissionDenied`) or a filesystem that cannot sync one (`Unsupported`, `InvalidInput`, macOS `ENOTSUP`) is
109	/// skipped: the file is already in place and failing the command now would misreport a write that happened. Any other
110	/// failure, whether opening or syncing, an I/O error above all, means the rename may not be durable and is reported.
111	fn sync_directory(dir: &Path) -> io::Result<()> {
112	    #[cfg(unix)]
113	    {
114	        let handle = match std::fs::File::open(dir) {
115	            Ok(handle) => handle,
116	            Err(error) if error.kind() == io::ErrorKind::PermissionDenied || sync_unsupported(&error) => {
117	                return Ok(());
118	            }
119	            Err(error) => return Err(error),
120	        };
121	        match handle.sync_all() {
122	            Err(error) if sync_unsupported(&error) => Ok(()),
123	            result => result,
124	        }
125	    }
126	    #[cfg(not(unix))]
127	    {
128	        let _ = dir;
129	        Ok(())
130	    }
131	}
132	
133	/// Fails now if [`atomic_write`] to `path` could not succeed, leaving nothing behind: no file and no directory.
134	/// A pre-existing regular file at `path` is accepted because the write replaces it. When the parent directory does not
135	/// exist yet, the nearest one that does must take a new file, which is what creating the missing ones needs.
136	///
137	/// # Errors
138	///
139	/// Returns the I/O error creating a temp file beside `path` (or in its nearest existing parent), or
140	/// `IsADirectory`-style `InvalidInput` when `path` is a directory or a parent is not.
141	pub fn probe_atomic_write(path: &Path, permit: &ApplyPermit) -> io::Result<()> {
142	    let _permit = permit;
143	    if path.is_dir() {
144	        return Err(io::Error::new(
145	            io::ErrorKind::InvalidInput,
146	            "destination is a directory",
147	        ));
148	    }
149	    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
150	    let parent = if raw_parent.as_os_str().is_empty() {
151	        Path::new(".")
152	    } else {
153	        raw_parent
154	    };
155	    let existing = parent
156	        .ancestors()
157	        .find(|ancestor| ancestor.try_exists().unwrap_or(false))
158	        .unwrap_or_else(|| Path::new("."));
159	    if !existing.is_dir() {
160	        return Err(io::Error::new(
161	            io::ErrorKind::InvalidInput,
162	            "a parent of the destination is not a directory",
163	        ));
164	    }
165	    NamedTempFile::new_in(existing)?;
166	    sync_directory(existing)
167	}
168	
169	/// `std` maps `EOPNOTSUPP` to `Unsupported` but leaves macOS's distinct `ENOTSUP` (45) uncategorized.
170	#[cfg(unix)]
171	fn sync_unsupported(error: &io::Error) -> bool {
172	    matches!(error.kind(), io::ErrorKind::Unsupported | io::ErrorKind::InvalidInput)
173	        || (cfg!(target_os = "macos") && error.raw_os_error() == Some(45))
174	}
175	
176	#[cfg(test)]
177	mod tests {
178	    use super::*;
179	    use crate::ApplyPermit;
180	    use tempfile::tempdir;
181	
182	    #[cfg(unix)]
183	    #[test]
184	    fn a_rewritten_file_keeps_its_mode_and_a_new_file_follows_the_umask() {
185	        use std::os::unix::fs::PermissionsExt;
186	        let dir = tempdir().unwrap();
187	        let permit = ApplyPermit::force_for_tests();
188	        let mode_of = |path: &Path| std::fs::metadata(path).unwrap().permissions().mode() & 0o7777;
189	
190	        for mode in [0o755, 0o640, 0o600] {
191	            let existing = dir.path().join(format!("existing-{mode:o}"));
192	            std::fs::write(&existing, "old").unwrap();
193	            std::fs::set_permissions(&existing, std::fs::Permissions::from_mode(mode)).unwrap();
194	            atomic_write(&existing, "new", &permit).unwrap();
195	            assert_eq!(std::fs::read_to_string(&existing).unwrap(), "new");
196	            assert_eq!(mode_of(&existing), mode);
197	        }
198	
199	        let created = dir.path().join("nested/created");
200	        atomic_write(&created, "x", &permit).unwrap();
201	        let plain = dir.path().join("plain");
202	        std::fs::write(&plain, "x").unwrap();
203	        assert_eq!(mode_of(&created), mode_of(&plain));
204	    }
205	
206	    #[test]
207	    fn atomic_write_new_never_replaces_what_is_there() {
208	        let dir = tempdir().unwrap();
209	        let permit = ApplyPermit::force_for_tests();
210	        let target = dir.path().join("changeset.md");
211	        atomic_write_new(&target, "first", &permit).unwrap();
212	        let error = atomic_write_new(&target, "second", &permit).unwrap_err();
213	        assert_eq!(error.kind(), io::ErrorKind::AlreadyExists);
214	        assert_eq!(std::fs::read_to_string(&target).unwrap(), "first");
215	        assert_eq!(
216	            std::fs::read_dir(dir.path()).unwrap().count(),
217	            1,
218	            "a refused write leaves no temp file behind"
219	        );
220	    }

