186	/// Propagates `input.seed`'s severities outward to dependents until no
187	/// target version changes, or `convergence_bound`'s iteration cap is
188	/// exceeded ([`GraphError::CascadeNotConverged`]) -- turns a would-be
189	/// infinite loop into a reportable bug, bound derived from package count.
190	///
191	/// One pass: pop a package, compute its bumped target, walk every
192	/// dependent edge, apply [`cascade_action`] to decide if that dependent's
193	/// severity/target changes and gets re-queued.
194	///
195	/// A genuine cross-grammar coverage failure (`coverage`'s `Err`, e.g.
196	/// SemVer target vs. PEP440 spec) aborts the whole cascade with
197	/// `Err(GraphError::GrammarMismatch)`. Soft instead: `Catalog`/`Opaque`
198	/// specs never have coverage tested (`coverage` returns `Unknown`
199	/// unconditionally), so they can't block anything -- `Catalog` gets
200	/// [`DiagnosticCode::CatalogSpecNotRewritten`], `Opaque` gets no
201	/// diagnostic. [`DiagnosticCode::RangeNotRoundTrippable`]'s real trigger
202	/// is a different step: [`rewrite_spec`], when a mechanical range rewrite
203	/// (not a coverage test) fails on an otherwise-known-coverage spec.
204	pub fn solve_cascade<D: DependencyResolver>(input: CascadeInput<'_, D>) -> Result<CascadeOutcome, GraphError> {
205	    let mut out = CascadeOutcome {
206	        severities: input.seed.clone(),
207	        reasons: input.reasons.clone(),
208	        ..Default::default()
209	    };
210	
211	    for (id, &sev) in input.seed {
212	        let t = bump_target(id, sev, &input)?;
213	        out.targets.insert(id.clone(), t);
214	    }
215	
216	    let mut worklist: BTreeSet<PackageId> = out.targets.keys().cloned().collect();
217	    let mut iterations = 0;
218	    let bound = convergence_bound(input.graph.packages().count());
219	    // Edges already run through rewrite_spec, so the floor-raise pass below doesn't re-diagnose them.
220	    let mut rewrite_attempted: BTreeSet<RewriteKey> = BTreeSet::new();
221	
222	    let mut changed = true;
223	    while changed {
224	        changed = false;
225	
226	        while let Some(pkg) = worklist.pop_first() {
227	            iterations += 1;
228	            if iterations > bound {
229	                return Err(GraphError::CascadeNotConverged { iterations });
230	            }
231	
232	            let new_version = out.targets[&pkg].clone();
233	            let src_sev = out.severities[&pkg];
234	
235	            let dependents: Vec<DepEdge> = input.graph.dependents_of(&pkg).cloned().collect();
236	            for edge in dependents {
237	                let cov = coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
238	                    from: edge.from.clone(),
239	                    to: edge.to.clone(),
240	                    source,
241	                })?;
242	
243	                let d = cascade_action(edge.kind, cov, src_sev, input.cfg);
244	
245	                if d.unknown_coverage && !matches!(edge.spec, DepSpec::Opaque(_)) {
246	                    let code = match edge.spec {
247	                        DepSpec::Catalog(_) => DiagnosticCode::CatalogSpecNotRewritten,
248	                        _ => DiagnosticCode::RangeNotRoundTrippable,
249	                    };
250	                    out.diagnostics.push(Diagnostic {
251	                        code,
252	                        severity: DiagnosticSeverity::Warning,
253	                        message: format!(
254	                            "spec `{}` for `{}` could not be tested for coverage",
255	                            edge.spec.render(),
256	                            edge.to.display_name()
257	                        ),
258	                        package: Some(edge.from.clone()),
259	                        path: Some(edge.from_manifest.clone()),
260	                        governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
261	                        escalated_by: None,
262	                    });
263	                }
264	
265	                if d.rewrite {
266	                    match rewrite_edge(&edge, &new_version, input.cfg)? {
267	                        RewriteOutcome::Rewritten(to_spec) => {
268	                            let key = dependency_rewrite_key(&edge);
269	                            rewrite_attempted.insert(key.clone());
270	                            out.rewrites.insert(
271	                                key.clone(),
272	                                SpecRewrite {
273	                                    key,
274	                                    dependency: edge.to.clone(),
275	                                    from: edge.spec.clone(),
276	                                    to: to_spec,
277	                                },
278	                            );
279	                        }
280	                        RewriteOutcome::LeftAlone(dg) => {
281	                            rewrite_attempted.insert(dependency_rewrite_key(&edge));
282	                            out.diagnostics.push(dg);
283	                        }
284	                    }
285	                }
286	
287	                let cur_sev = out.severities.get(&edge.from).copied().unwrap_or(Severity::None);
288	                if d.severity > cur_sev {
289	                    raise(
290	                        &edge.from,
291	                        d.severity,
292	                        &d,
293	                        &pkg,
294	                        &edge,
295	                        &new_version,
296	                        &mut out,
297	                        input.groups,
298	                        &mut worklist,
299	                        &input,
300	                    )?;
301	                }
302	            }
303	        }
304	
305	        // Linked group release severity propagation
306	        for g in input.groups.linked.values() {
307	            let max_sev = g.max_severity(&out.severities);
308	            if max_sev == Severity::None {
309	                continue;
310	            }
311	
312	            // A member absent from `input.base` was removed from the
313	            // workspace but is still listed in the group config. Skip it
314	            // rather than let `bump_target` below hit `MissingField` --
315	            // mirrors the guard `aggregate::union_fixed`/`union_linked`
316	            // already apply before cascade convergence ever starts.
317	            let mut live_members = Vec::new();
318	            for id in g.package_members() {
319	                if !input.base.contains_key(id) {
320	                    out.diagnostics.push(Diagnostic {
321	                        code: DiagnosticCode::UnknownPackage,
322	                        severity: DiagnosticSeverity::Warning,
323	                        message: format!(
324	                            "Linked group `{}` references package `{}` which is not in the \
325	                             workspace; the stale group member is skipped. Remove it from \
326	                             callisto.toml to silence this warning.",
327	                            g.name,
328	                            id.display_name()
329	                        ),
330	                        package: Some(id.clone()),
331	                        path: None,
332	                        governed_by: Some(ConfigKey::LINKED_GROUP),
333	                        escalated_by: None,
334	                    });
335	                    continue;
336	                }
337	                live_members.push(id.clone());
338	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
339	                if max_sev > cur_sev {
340	                    out.severities.insert(id.clone(), max_sev);
341	                }
342	            }
343	
344	            let mut winner: Option<Version> = None;
345	            for id in &live_members {
346	                let candidate = bump_target(id, max_sev, &input)?;
347	                winner = Some(match winner {
348	                    None => candidate,
349	                    Some(best) => {
