425	                crate::groups::fixed_group_target(&g.name, &live_members, input.base, max_sev, input.tags, input.pre)?;
426	
427	            for id in live_members {
428	                if out.targets.get(&id) != Some(&winner) {
429	                    out.targets.insert(id.clone(), winner.clone());
430	                    out.reasons
431	                        .insert(id.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
432	                    worklist.insert(id.clone());
433	                    changed = true;
434	                }
435	            }
436	        }
437	    }
438	
439	    // A releasing package's floor on a co-released dependency is always raised, even when the old spec still covers it.
440	    for pkg in out.severities.keys().cloned().collect::<Vec<_>>() {
441	        let deps: Vec<DepEdge> = input.graph.dependencies_of(&pkg).cloned().collect();
442	        for edge in deps {
443	            if edge.kind == DepKind::Dev {
444	                continue;
445	            }
446	            if matches!(
447	                edge.spec,
448	                DepSpec::Workspace(_) | DepSpec::Catalog(_) | DepSpec::Opaque(_)
449	            ) {
450	                continue;
451	            }
452	            let Some(new_version) = out.targets.get(&edge.to).cloned() else {
453	                continue;
454	            };
455	            if matches!(edge.spec, DepSpec::WorkspaceProtocol(_))
456	                && coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
457	                    from: edge.from.clone(),
458	                    to: edge.to.clone(),
459	                    source,
460	                })? != Coverage::DoesNotCover
461	            {
462	                continue;
463	            }
464	
465	            let key = dependency_rewrite_key(&edge);
466	            if rewrite_attempted.contains(&key) {
467	                continue;
468	            }
469	
470	            match rewrite_edge(&edge, &new_version, input.cfg)? {
471	                RewriteOutcome::Rewritten(to_spec) => {
472	                    out.rewrites.entry(key.clone()).or_insert_with(|| SpecRewrite {
473	                        key,
474	                        dependency: edge.to.clone(),
475	                        from: edge.spec.clone(),
476	                        to: to_spec,
477	                    });
478	                }
479	                RewriteOutcome::LeftAlone(dg) => {
480	                    out.diagnostics.push(dg);
481	                }
482	            }
483	        }
484	    }
485	
486	    out.iterations = iterations;
487	    Ok(out)
488	}
489	
490	fn bump_target<D: DependencyResolver>(
491	    id: &PackageId,
492	    sev: Severity,
493	    input: &CascadeInput<'_, D>,
494	) -> Result<Version, GraphError> {
495	    let base = input.base.get(id).cloned().ok_or_else(|| {
496	        GraphError::Manifest(callisto_model::ManifestError::MissingField {
497	            path: PathBuf::from(id.name()),
498	            field: "version",
499	        })
500	    })?;
501	
502	    // PreMode::Exit falls through to a plain `versioning.bump`, which strips a matching pre-release tag directly.
503	    crate::groups::versioned_bump(id, &base, sev, input.pre)
504	}
505	
506	#[allow(clippy::too_many_arguments)]
507	fn raise<D: DependencyResolver>(
508	    pkg: &PackageId,
509	    sev: Severity,
510	    decision: &CascadeDecision,
511	    via: &PackageId,
512	    edge: &DepEdge,
513	    dependency_to: &Version,
514	    out: &mut CascadeOutcome,
515	    groups: &GroupTable,
516	    worklist: &mut BTreeSet<PackageId>,
517	    input: &CascadeInput<'_, D>,
518	) -> Result<bool, GraphError> {
519	    let cur_sev = out.severities.get(pkg).copied().unwrap_or(Severity::None);
520	    if sev <= cur_sev {
521	        return Ok(false);
522	    }
523	
524	    out.severities.insert(pkg.clone(), sev);
525	
526	    let new_reason = if decision.escalated {
527	        BumpReason::PeerEscalation {
528	            via: via.clone(),
529	            spec: edge.spec.render(),
530	        }
531	    } else {
532	        BumpReason::Cascade {
533	            via: via.clone(),
534	            dep_kind: edge.kind,
535	            spec: edge.spec.render(),
536	            dependency_to: dependency_to.clone(),
537	        }
538	    };
539	    out.reasons.insert(pkg.clone(), new_reason);
540	
541	    if let Some(ref gov) = decision.governed_by {
542	        out.governed_by.insert(pkg.clone(), gov.clone());
543	    }
544	
545	    let new_t = bump_target(pkg, sev, input)?;
546	    out.targets.insert(pkg.clone(), new_t);
547	    worklist.insert(pkg.clone());
548	
549	    for sib in groups.fixed_siblings(pkg) {
550	        let sib_sev = out.severities.get(sib).copied().unwrap_or(Severity::None);
551	        if sev > sib_sev {
552	            out.severities.insert(sib.clone(), sev);
553	            out.reasons.insert(
554	                sib.clone(),
555	                BumpReason::FixedGroupUnion {
556	                    group: groups
557	                        .fixed_group_of(pkg)
558	                        .expect("a fixed-group sibling implies the package has a fixed group")
559	                        .name
560	                        .clone(),
561	                },
562	            );
563	            let sib_t = bump_target(sib, sev, input)?;
564	            out.targets.insert(sib.clone(), sib_t);
565	            worklist.insert(sib.clone());
566	        }
567	    }
568	
569	    Ok(true)
570	}
571	
572	pub(crate) fn convergence_bound(package_count: usize) -> usize {
573	    4 * package_count + 1
574	}
575	
576	#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
577	pub enum DepWriteTarget {
578	    Manifest(PathBuf),
579	    CargoWorkspaceDependency { root_manifest: PathBuf },
580	}
581	
582	#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
583	pub struct RewriteKey {
584	    pub target: DepWriteTarget,
585	    pub name: String,
586	    pub kind: Option<DepKind>,
587	    pub locator: DepLocator,
588	}
589	
590	#[derive(Clone, Debug, PartialEq, Eq)]
591	pub struct SpecRewrite {
592	    pub key: RewriteKey,
593	    pub dependency: PackageId,
594	    pub from: DepSpec,
595	    pub to: DepSpec,
596	}
597	
598	pub enum RewriteOutcome {
599	    Rewritten(DepSpec),
600	    LeftAlone(Diagnostic),
601	}
602	
603	/// Rewrites one dependency edge toward `new`. A range a consumer's published manifest would keep excluding `new`
604	/// stops the run; only a dev dependency, which consumers never install, is left alone with a warning.
605	pub(crate) fn rewrite_edge(edge: &DepEdge, new: &Version, cfg: &CascadeConfig) -> Result<RewriteOutcome, GraphError> {
606	    let eco = manifest_ecosystem(&edge.from_manifest);
607	    match rewrite_spec(&edge.spec, new, eco, cfg) {
608	        RewriteOutcome::LeftAlone(_) if edge.kind != DepKind::Dev => Err(GraphError::UnrewritableRange {
609	            dependent: edge.from.display_name(),
610	            dependency: edge.to.display_name(),
611	            spec: edge.spec.render(),
612	            version: new.render().to_string(),
613	            manifest: edge.from_manifest.display().to_string(),
614	        }),
615	        outcome => Ok(outcome),
616	    }
617	}
618	
619	pub fn rewrite_spec(original: &DepSpec, new: &Version, eco: Ecosystem, cfg: &CascadeConfig) -> RewriteOutcome {
620	    if !cfg.preserve_npm_ranges && eco == Ecosystem::Npm && !matches!(original, DepSpec::WorkspaceProtocol(_)) {
621	        return RewriteOutcome::Rewritten(DepSpec::Exact(new.clone()));
622	    }
623	
624	    match callisto_manifests::round_trip(eco, original, new) {
625	        Some(rewritten) => RewriteOutcome::Rewritten(rewritten),
626	        _ => RewriteOutcome::LeftAlone(Diagnostic {
627	            code: DiagnosticCode::RangeNotRoundTrippable,
628	            severity: DiagnosticSeverity::Warning,
629	            message: format!(
630	                "spec `{}` could not be round-tripped toward version `{}`",
631	                original.render(),
632	                new.render()
633	            ),
634	            package: None,
635	            path: None,
636	            governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
637	            escalated_by: None,
638	        }),
639	    }
640	}
