490	fn bump_target<D: DependencyResolver>(
491	    id: &PackageId,
492	    sev: Severity,
493	    input: &CascadeInput<'_, D>,
494	) -> Result<Version, GraphError> {
495	    let base = input.base.get(id).cloned().ok_or_else(|| {
496	        GraphError::Manifest(callisto_model::ManifestError::MissingField {
497	            path: PathBuf::from(id.name()),
498	            field: "version",
499	        })
500	    })?;
501	
502	    // PreMode::Exit falls through to a plain `versioning.bump`, which strips a matching pre-release tag directly.
503	    crate::groups::versioned_bump(id, &base, sev, input.pre)
