507	fn raise<D: DependencyResolver>(
508	    pkg: &PackageId,
509	    sev: Severity,
510	    decision: &CascadeDecision,
511	    via: &PackageId,
512	    edge: &DepEdge,
513	    dependency_to: &Version,
514	    out: &mut CascadeOutcome,
515	    groups: &GroupTable,
516	    worklist: &mut BTreeSet<PackageId>,
517	    input: &CascadeInput<'_, D>,
518	) -> Result<bool, GraphError> {
519	    let cur_sev = out.severities.get(pkg).copied().unwrap_or(Severity::None);
520	    if sev <= cur_sev {
521	        return Ok(false);
522	    }
523	
524	    out.severities.insert(pkg.clone(), sev);
525	
526	    let new_reason = if decision.escalated {
527	        BumpReason::PeerEscalation {
528	            via: via.clone(),
529	            spec: edge.spec.render(),
530	        }
531	    } else {
532	        BumpReason::Cascade {
533	            via: via.clone(),
534	            dep_kind: edge.kind,
535	            spec: edge.spec.render(),
536	            dependency_to: dependency_to.clone(),
537	        }
538	    };
539	    out.reasons.insert(pkg.clone(), new_reason);
540	
541	    if let Some(ref gov) = decision.governed_by {
542	        out.governed_by.insert(pkg.clone(), gov.clone());
543	    }
544	
545	    let new_t = bump_target(pkg, sev, input)?;
546	    out.targets.insert(pkg.clone(), new_t);
547	    worklist.insert(pkg.clone());
548	
549	    for sib in groups.fixed_siblings(pkg) {
550	        let sib_sev = out.severities.get(sib).copied().unwrap_or(Severity::None);
551	        if sev > sib_sev {
552	            out.severities.insert(sib.clone(), sev);
553	            out.reasons.insert(
554	                sib.clone(),
555	                BumpReason::FixedGroupUnion {
556	                    group: groups
557	                        .fixed_group_of(pkg)
558	                        .expect("a fixed-group sibling implies the package has a fixed group")
559	                        .name
560	                        .clone(),
561	                },
562	            );
563	            let sib_t = bump_target(sib, sev, input)?;
564	            out.targets.insert(sib.clone(), sib_t);
565	            worklist.insert(sib.clone());
566	        }
567	    }
568	
569	    Ok(true)
570	}
