619	pub fn rewrite_spec(original: &DepSpec, new: &Version, eco: Ecosystem, cfg: &CascadeConfig) -> RewriteOutcome {
620	    if !cfg.preserve_npm_ranges && eco == Ecosystem::Npm && !matches!(original, DepSpec::WorkspaceProtocol(_)) {
621	        return RewriteOutcome::Rewritten(DepSpec::Exact(new.clone()));
622	    }
623	
624	    match callisto_manifests::round_trip(eco, original, new) {
625	        Some(rewritten) => RewriteOutcome::Rewritten(rewritten),
626	        _ => RewriteOutcome::LeftAlone(Diagnostic {
627	            code: DiagnosticCode::RangeNotRoundTrippable,
628	            severity: DiagnosticSeverity::Warning,
629	            message: format!(
630	                "spec `{}` could not be round-tripped toward version `{}`",
631	                original.render(),
632	                new.render()
633	            ),
634	            package: None,
635	            path: None,
636	            governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
637	            escalated_by: None,
638	        }),
639	    }
640	}
