23	fn canonical_if_present(path: &Path) -> std::io::Result<Option<PathBuf>> {
24	    match path.canonicalize() {
25	        Ok(canonical) => Ok(Some(canonical)),
26	        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
27	        Err(error) => Err(error),
28	    }
29	}
