31	/// The npm package a relative `workspace:../path` dependency of `declaring_manifest` names, or `None` when the path
32	/// leaves the workspace, does not exist, or holds no admitted npm package.
33	fn relative_workspace_package<'a>(
34	    root: &Path,
35	    declaring_manifest: &Path,
36	    relative: &str,
37	    mut packages: impl Iterator<Item = &'a Package>,
38	) -> std::io::Result<Option<PackageId>> {
39	    let root = root.canonicalize()?;
40	    let Some(source) = root
41	        .join(declaring_manifest)
42	        .parent()
43	        .map(canonical_if_present)
44	        .transpose()?
45	        .flatten()
46	    else {
47	        return Ok(None);
48	    };
49	    let Some(target) = canonical_if_present(&source.join(relative))? else {
50	        return Ok(None);
51	    };
52	    if !target.starts_with(&root) {
53	        return Ok(None);
54	    }
55	    for package in packages.by_ref() {
56	        for manifest in package.canonical_manifests() {
57	            if manifest.ecosystem() != Ecosystem::Npm {
58	                continue;
59	            }
60	            let dir = root.join(manifest.path.parent().unwrap_or(Path::new("")));
61	            if canonical_if_present(&dir)?.as_ref() == Some(&target) {
62	                return Ok(Some(package.id.clone()));
63	            }
64	        }
65	    }
66	    Ok(None)
67	}
