71	/// Returns (name-scoped claiming-ecosystem set, complete unfiltered native-key list)
72	/// for one path's own `list` of (ecosystem, declared-id) pairs. The first is filtered
73	/// to entries whose declared name equals `primary_id.name()`; the second is not filtered.
74	fn compute_claiming_ecosystems_and_native_keys(
75	    list: &[(Ecosystem, PackageId)],
76	    primary_id: &PackageId,
77	) -> (BTreeSet<Ecosystem>, Vec<(Ecosystem, String)>) {
78	    let claiming = list
79	        .iter()
80	        .filter(|(_, id)| id.name() == primary_id.name())
81	        .map(|(eco, _)| *eco)
82	        .collect();
83	    let native_keys = list.iter().map(|(eco, id)| (*eco, id.name().to_string())).collect();
84	    (claiming, native_keys)
85	}
