98	/// has disjoint claiming-ecosystem sets in `claiming_ecosystems`.
99	///
100	/// Overlapping claiming sets indicate a true duplicate package error (handled
101	/// separately during graph construction), NOT a valid multi-ecosystem promotion.
102	#[cfg(test)]
103	fn is_promoted_bare_name(paths: &[PathBuf], claiming_ecosystems: &BTreeMap<PathBuf, BTreeSet<Ecosystem>>) -> bool {
104	    if paths.len() <= 1 {
105	        return false;
106	    }
