121	/// is reported as an error-level diagnostic that makes loading the workspace for planning fail.
122	fn unresolved(manifest: &Path, what: &str, cause: impl std::fmt::Display) -> Diagnostic {
123	    // `./package.json` and `package.json` are one manifest.
124	    let manifest: PathBuf = manifest
