189	fn discover<L: ProjectLocator>(
190	    root: &Path,
191	    locator: &L,
192	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
193	    ctx: &OpenContext<'_>,
194	    diagnostics: &mut Vec<Diagnostic>,
195	) -> Result<Discovered, GraphError> {
196	    let (projects, platform_candidates) = locator.projects_and_platform_candidates()?;
