198	    // The locator already parsed each manifest, so reuse `proj.id`.
199	    let mut by_path: BTreeMap<PathBuf, Vec<(Ecosystem, PackageId)>> = BTreeMap::new();
200	    for proj in &projects {
201	        by_path
202	            .entry(proj.path.clone())
203	            .or_default()
204	            .push((proj.ecosystem, proj.id.clone()));
205	    }
206	
207	    let attached_platforms = platform_owners(root, &by_path, &platform_candidates, manifest_cache, ctx, diagnostics);
208	    Ok(Discovered {
209	        by_path,
210	        attached_platforms,
