214	fn assign_identities(
215	    discovered: Discovered,
216	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
217	    ctx: &OpenContext<'_>,
218	) -> Result<Identified, GraphError> {
219	    let Discovered {
220	        by_path,
221	        attached_platforms,
222	    } = discovered;
223	    let mut assigner = IdentityAssigner::new(manifest_cache, ctx);
224	    for (rel_path, list) in by_path {
225	        if attached_platforms.contains_key(&rel_path) {
226	            continue;
227	        }
228	        assigner.assign(rel_path, list)?;
229	    }
230	    assigner.attach_platforms(attached_platforms);
231	    Ok(assigner.finish())
