234	/// The order-dependent identity assignment: whether a path's identity is bare or ecosystem-prefixed depends on the
235	/// names seen in earlier paths, so this is one incremental pass that owns all of its bookkeeping.
236	struct IdentityAssigner<'a> {
237	    manifest_cache: &'a RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
238	    ctx: &'a OpenContext<'a>,
239	    package_manifest_decls: BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)>,
240	    index: IdentityIndex,
241	    claiming_ecosystems: BTreeMap<PathBuf, BTreeSet<Ecosystem>>,
242	    // Every (ecosystem, native name) any path declares, anywhere in that path's
243	    // manifest list -- not only its primary name -- belongs to exactly one directory.
244	    native_owner: BTreeMap<(Ecosystem, String), PathBuf>,
245	    path_native_keys: BTreeMap<PathBuf, Vec<(Ecosystem, String)>>,
246	    path_platform_keys: BTreeMap<PathBuf, Vec<String>>,
247	    primary_ecosystems: BTreeMap<PathBuf, Ecosystem>,
248	    promoted_siblings: BTreeMap<String, Vec<(PackageId, BTreeSet<Ecosystem>)>>,
249	    unresolved: Vec<Diagnostic>,
250	}
