252	impl<'a> IdentityAssigner<'a> {
253	    fn new(manifest_cache: &'a RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>, ctx: &'a OpenContext<'a>) -> Self {
254	        IdentityAssigner {
255	            manifest_cache,
256	            ctx,
257	            package_manifest_decls: BTreeMap::new(),
258	            index: IdentityIndex::default(),
259	            claiming_ecosystems: BTreeMap::new(),
260	            native_owner: BTreeMap::new(),
261	            path_native_keys: BTreeMap::new(),
262	            path_platform_keys: BTreeMap::new(),
263	            primary_ecosystems: BTreeMap::new(),
264	            promoted_siblings: BTreeMap::new(),
265	            unresolved: Vec::new(),
266	        }
267	    }
268	
269	    fn assign(&mut self, rel_path: PathBuf, mut list: Vec<(Ecosystem, PackageId)>) -> Result<(), GraphError> {
270	        // Explicit precedence: Cargo (0) > Npm (1) > Pypi (2) > others.
271	        // Do NOT rely on enum discriminant order -- sort by this named
272	        // priority function so the precedence survives future variant
273	        // additions to `Ecosystem`.
274	        list.sort_by_key(|a| a.0.primary_priority());
275	
276	        // E100 whenever any (ecosystem, native name) this path declares -- primary
277	        // or not -- is already owned by a different path; names both. Checked before
278	        // any promotion bookkeeping so a dual-manifest directory's non-primary name
279	        // (e.g. an npm sibling of a Cargo-primary package) is covered too, not just
280	        // each path's own primary name.
281	        if let Some((eco, id)) = list.iter().find(|(eco, id)| {
282	            self.native_owner
283	                .get(&(*eco, id.name().to_string()))
284	                .is_some_and(|p| *p != rel_path)
285	        }) {
286	            let owner_path = self.native_owner[&(*eco, id.name().to_string())].clone();
287	            return Err(GraphError::DuplicatePackage {
288	                id: id.clone(),
289	                paths: vec![owner_path, rel_path],
290	            });
291	        }
292	        for (eco, id) in &list {
293	            self.native_owner
294	                .insert((*eco, id.name().to_string()), rel_path.clone());
295	        }
296	
297	        let mut primary_id = list[0].1.clone();
298	        let (this_claiming, this_native_keys) = compute_claiming_ecosystems_and_native_keys(&list, &primary_id);
299	        self.claiming_ecosystems.insert(rel_path.clone(), this_claiming.clone());
300	        self.path_native_keys.insert(rel_path.clone(), this_native_keys);
301	        self.primary_ecosystems.insert(rel_path.clone(), list[0].0);
302	
303	        let mut branch_ii_promoted = false;
304	        if self.promoted_siblings.contains_key(primary_id.name()) {
305	            let this_set = self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
306	            let promoted_id = PackageId::Prefixed {
307	                ecosystem: self.primary_ecosystems[&rel_path],
308	                name: primary_id.name().to_string(),
309	            };
310	            self.promoted_siblings
311	                .entry(primary_id.name().to_string())
312	                .or_default()
313	                .push((promoted_id.clone(), this_set));
314	            primary_id = promoted_id;
315	            branch_ii_promoted = true;
316	        }
317	
318	        if !branch_ii_promoted {
319	            self.index
320	                .bare
321	                .insert(primary_id.name().to_string(), primary_id.clone());
322	        }
323	
324	        let mut decls = Vec::new();
325	        for (eco, id) in &list {
326	            let (fmt, filename) = match eco {
327	                Ecosystem::Cargo => (ManifestFormat::CargoToml, "Cargo.toml"),
328	                Ecosystem::Npm => (ManifestFormat::PackageJson, "package.json"),
329	                Ecosystem::Pypi => (ManifestFormat::PyprojectToml, "pyproject.toml"),
330	                _ => (ManifestFormat::PackageJson, "package.json"),
331	            };
332	            let manifest_rel = rel_path.join(filename);
333	            let canonical_decl = match ManifestDecl::new(manifest_rel.clone(), ManifestRole::Canonical, fmt) {
334	                Ok(decl) => {
335	                    decls.push(decl.clone());
336	                    Some(decl)
337	                }
338	                Err(error) => {
339	                    self.unresolved
340	                        .push(unresolved(&manifest_rel, "declare its manifest", error));
341	                    None
342	                }
343	            };
344	            // For napi platform packages (os + cpu constraints in package.json),
345	            // also push a Platform-role decl so release derivation can route them
346	            // as platform publishes instead of main packages. Reuses
347	            // the canonical decl's manifest handle via the shared
348	            // `manifest_cache` (`npm_role()`) instead of a second, raw
349	            // `fs::read` of the same package.json -- the handle opened here
350	            // is the same one `publish_targets`/`iter_dependencies` reuse
351	            // further down.
352	            if *eco == Ecosystem::Npm {
353	                let opened = canonical_decl
354	                    .as_ref()
355	                    .map(|decl| open_cached(self.manifest_cache, decl, self.ctx));
356	                let manifest = match opened {
357	                    Some(Ok(manifest)) => Some(manifest),
358	                    Some(Err(error)) => {
359	                        self.unresolved.push(unresolved(
360	                            &manifest_rel,
361	                            "open its manifest to read its platform role",
362	                            error,
363	                        ));
364	                        None
365	                    }
366	                    None => None,
367	                };
368	                let role = manifest
369	                    .and_then(|m| m.npm_role())
370	                    .map(|npm_role| match npm_role {
371	                        callisto_manifests::NpmRole::Platform { platform, arch, abi } => {
372	                            ManifestRole::Platform { platform, arch, abi }
373	                        }
374	                    })
375	                    .unwrap_or(ManifestRole::Canonical);
376	                if let ManifestRole::Platform { .. } = role {
377	                    match ManifestDecl::new(manifest_rel.clone(), role.clone(), fmt) {
378	                        Ok(platform_decl) => decls.push(platform_decl),
379	                        Err(error) => {
380	                            self.unresolved
381	                                .push(unresolved(&manifest_rel, "declare its platform manifest", error))
382	                        }
383	                    }
384	                    // `id` is this manifest's own npm identity, resolved from its
385	                    // own `name` field -- distinct from `primary_id` whenever a
386	                    // higher-priority ecosystem (Cargo) shares this directory.
387	                    // Config authors reference the platform package by
388	                    // its own name in `[[fixed-group]] members`, so that must be
389	                    // the index key; `primary_id` is who it belongs to.
390	                    self.index
391	                        .platform
392	                        .insert(id.name().to_string(), (primary_id.clone(), manifest_rel, role));
393	                    self.path_platform_keys
394	                        .entry(rel_path.clone())
395	                        .or_default()
396	                        .push(id.name().to_string());
397	                }
398	            }
399	            self.index
400	                .native
401	                .insert((*eco, id.name().to_string()), primary_id.clone());
402	            if id.name() == primary_id.name() {
403	                self.index
404	                    .prefixed
405	                    .insert((*eco, id.name().to_string()), primary_id.clone());
406	            }
407	        }
408	
409	        let current_decls = decls.clone();
410	        if let Some((existing_path, existing_decls)) = self
411	            .package_manifest_decls
412	            .insert(primary_id.clone(), (rel_path.clone(), decls))
413	        {
414	            self.promotion_rekey(primary_id, existing_path, existing_decls, rel_path, current_decls);
415	        }
416	        Ok(())
417	    }
418	
419	    /// A second path just claimed the bare name `primary_id`, so both paths are promoted to ecosystem-prefixed ids
420	    /// and every key already stored under the stale bare id is re-keyed.
421	    fn promotion_rekey(
422	        &mut self,
423	        primary_id: PackageId,
424	        existing_path: PathBuf,
425	        existing_decls: Vec<ManifestDecl>,
426	        rel_path: PathBuf,
427	        current_decls: Vec<ManifestDecl>,
428	    ) {
429	        // Both paths' claiming ecosystems are guaranteed disjoint here: an
430	        // overlap would already have failed at the native_owner check above.
431	        let name = primary_id.name().to_string();
432	        // STALE-KEY REWRITE location (4): re-key package_manifest_decls under
433	        // each path's own newly-promoted Prefixed id, sourcing each path's own
434	        // decls -- captured via the `existing_decls` returned by `insert` above
435	        // and the `current_decls` clone taken before `insert` overwrote the map,
436	        // never via a `.get(&primary_id)` lookup after the fact (a lookup miss
437	        // there would silently substitute an empty Vec -- the
438	        // manifests-bleed bug).
439	        let existing_id = PackageId::Prefixed {
440	            ecosystem: self.primary_ecosystems[&existing_path],
441	            name: name.clone(),
442	        };
443	        let current_id = PackageId::Prefixed {
444	            ecosystem: self.primary_ecosystems[&rel_path],
445	            name: name.clone(),
446	        };
447	        self.package_manifest_decls
448	            .insert(existing_id.clone(), (existing_path.clone(), existing_decls));
449	        self.package_manifest_decls
450	            .insert(current_id.clone(), (rel_path.clone(), current_decls));
451	        self.package_manifest_decls.remove(&primary_id);
452	        // STALE-KEY REWRITE location (1): once a bare name is promoted,
453	        // it MUST NOT remain in index.bare.
454	        self.index.bare.remove(&name);
455	        // STALE-KEY REWRITE location (2): update index.native values
456	        // for all native keys declared by either path so they map to
457	        // their path's newly-promoted Prefixed id, not the stale primary_id.
458	        if let Some(keys) = self.path_native_keys.get(&existing_path) {
459	            for key in keys {
460	                self.index.native.insert(key.clone(), existing_id.clone());
461	            }
462	        }
463	        if let Some(keys) = self.path_native_keys.get(&rel_path) {
464	            for key in keys {
465	                self.index.native.insert(key.clone(), current_id.clone());
466	            }
467	        }
468	        // STALE-KEY REWRITE location (3)/(5): update index.prefixed values
469	        // for the primary identities so they point to the newly-promoted
470	        // Prefixed id rather than the pre-promotion primary_id.
471	        for eco in self
472	            .claiming_ecosystems
473	            .get(&existing_path)
474	            .cloned()
475	            .unwrap_or_default()
476	        {
477	            self.index.prefixed.insert((eco, name.clone()), existing_id.clone());
478	        }
479	        for eco in self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default() {
480	            self.index.prefixed.insert((eco, name.clone()), current_id.clone());
481	        }
482	        // STALE-KEY REWRITE location (6): update index.platform's owner-id
483	        // component for every platform manifest declared under either path,
484	        // so a platform sibling co-located with a promoted owner keeps
485	        // pointing at that owner's newly-promoted Prefixed id rather than
486	        // the stale pre-promotion primary_id.
487	        if let Some(keys) = self.path_platform_keys.get(&existing_path) {
488	            for key in keys {
489	                if let Some((_, manifest_rel, role)) = self.index.platform.get(key).cloned() {
490	                    self.index
491	                        .platform
492	                        .insert(key.clone(), (existing_id.clone(), manifest_rel, role));
493	                }
494	            }
495	        }
496	        if let Some(keys) = self.path_platform_keys.get(&rel_path) {
497	            for key in keys {
498	                if let Some((_, manifest_rel, role)) = self.index.platform.get(key).cloned() {
499	                    self.index
500	                        .platform
501	                        .insert(key.clone(), (current_id.clone(), manifest_rel, role));
502	                }
503	            }
504	        }
505	        let existing_set = self
506	            .claiming_ecosystems
507	            .get(&existing_path)
508	            .cloned()
509	            .unwrap_or_default();
510	        let current_set = self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
511	        self.promoted_siblings
512	            .entry(name.clone())
513	            .or_default()
514	            .extend([(existing_id, existing_set), (current_id, current_set)]);
515	    }
