257	pub struct IdentityIndex {
258	    pub bare: BTreeMap<String, PackageId>,
259	    pub prefixed: BTreeMap<(Ecosystem, String), PackageId>,
260	    pub native: BTreeMap<(Ecosystem, String), PackageId>,
261	    /// Keyed by a platform npm manifest's own package name (e.g.
262	    /// `"@myorg/my-crate-linux-x64-gnu"`) -- distinct from `owner`'s name
263	    /// when the owning package's primary identity comes from a
264	    /// higher-priority ecosystem sharing the same directory (a Cargo+npm
265	    /// dual project: platform manifests belong to the owning
266	    /// `Package`, they are never independently-registered `Package`s of
267	    /// their own). The `ManifestRole::Platform` is carried alongside so
268	    /// `GroupTable::resolve` doesn't need a second disk read to recover it.
269	    pub platform: BTreeMap<String, (PackageId, PathBuf, ManifestRole)>,
270	}
271	
272	impl IdentityIndex {
273	    /// The one selector resolver: resolves a user- or config-typed package
274	    /// selector (`eco/name` or a bare name; the colon form is `E316`) against registered
275	    /// native manifest names.
276	    ///
277	    /// A qualified selector is an exact `(ecosystem, native name)` lookup: no
278	    /// match is `E102` ([`GraphError::UnknownPackage`]), regardless of what a
279	    /// different ecosystem calls itself. A bare selector searches every
280	    /// ecosystem's native names: no match is `E102`; more than one distinct
281	    /// package answering to that name in different ecosystems is `E103`
282	    /// ([`GraphError::AmbiguousName`]). Resolving by any registered native
283	    /// name -- not just a package's primary/display name -- is what lets a
284	    /// dual-manifest package be named by either of its manifests' names.
285	    pub fn resolve(&self, selector: &str) -> Result<PackageId, GraphError> {
286	        ConfigError::reject_colon_form(selector, "package selector")?;
287	        let id = PackageId::parse(selector).unwrap_or_else(|_| PackageId::Bare(selector.to_string()));
288	        self.resolve_id(&id)
289	    }
290	
291	    /// [`Self::resolve`] for an already-parsed selector.
292	    pub fn resolve_id(&self, id: &PackageId) -> Result<PackageId, GraphError> {
293	        match id {
294	            PackageId::Prefixed { ecosystem, name } => self
295	                .native
296	                .get(&(*ecosystem, name.clone()))
297	                .cloned()
298	                .ok_or_else(|| GraphError::UnknownPackage { id: id.clone() }),
299	            PackageId::Bare(name) => {
300	                let candidates: BTreeSet<PackageId> = self
301	                    .native
302	                    .iter()
303	                    .filter(|((_, n), _)| n == name)
304	                    .map(|(_, registered)| registered.clone())
305	                    .collect();
306	                match candidates.len() {
307	                    0 => Err(GraphError::UnknownPackage { id: id.clone() }),
308	                    1 => Ok(candidates.into_iter().next().expect("len checked above")),
309	                    _ => Err(GraphError::AmbiguousName {
310	                        name: name.clone(),
311	                        candidates: candidates.into_iter().collect(),
312	                    }),
313	                }
314	            }
315	        }
316	    }
317	
318	    /// True when `selector` (an ecosystem-qualified or bare configured
319	    /// package identity, e.g. from `[[release.artifact]]` or
320	    /// `product-package`) resolves to `candidate`.
321	    ///
322	    /// The single replacement for the `selector.matches(&candidate) &&
323	    /// selector.ecosystem() == Some(candidate_ecosystem)` guard that was
324	    /// hand-rolled at every config-selector call site: `PackageId::matches`
325	    /// alone treats a bare id as an ecosystem wildcard, so a qualified
326	    /// selector for one ecosystem's package would otherwise match a
327	    /// same-named package in another.
328	    pub fn identifies(&self, selector: &PackageId, candidate: &PackageId) -> bool {
329	        self.resolve_id(selector).is_ok_and(|resolved| &resolved == candidate)
330	    }

