92	    /// The same (raw, pre-`PackageId`-resolution) name appears twice in one changeset's
93	    /// frontmatter.
94	    #[error("line {line}: package {name:?} is named more than once in this changeset's frontmatter (first on line {first_line})")]
95	    #[diagnostic(code(E047))]
96	    DuplicateEntry {
97	        line: usize,
98	        first_line: usize,
99	        name: String,
100	    },
101	
102	    /// A changeset with one or more entries must have a non-empty summary.
103	    #[error("changeset has entries but an empty or whitespace-only summary")]
104	    #[diagnostic(code(E055), help("Add a non-empty summary after the closing `---` delimiter."))]
