110	pub enum WriteError {
111	    /// A changeset with one or more entries must have a non-empty summary.
112	    #[error("cannot write changeset: entries present but summary is empty or whitespace-only")]
113	    #[diagnostic(code(E056), help("Provide a non-empty summary describing the change."))]
114	    EmptySummary,
115	
116	    /// `entries[index]`'s name is the empty string.
117	    #[error("entry {index} has an empty package name")]
118	    #[diagnostic(code(E057))]
119	    EmptyName { index: usize },
120	
121	    /// `entries[index]`'s name contains a literal `"`, which cannot be written — no escaping
122	    /// convention is defined for this grammar.
123	    #[error("entry {index} name {name:?} contains a literal `\"`, which cannot be written (no escaping convention is defined for this grammar)")]
124	    #[diagnostic(
125	        code(E268),
126	        help("Remove the literal `\"` from the package name before writing the changeset.")
127	    )]
128	    NameContainsQuote { index: usize, name: String },
129	}
130	
131	/// Parses one `.changeset/*.md` file's contents.
132	///
133	/// Grammar: a `---`-delimited frontmatter block starting on line 1, each non-blank,
134	/// non-comment line inside it shaped `<name>: <severity>`, followed by the file's remaining
135	/// content as `summary` (trimmed). `#`-comment lines and blank lines inside the frontmatter
136	/// block are skipped. CRLF line endings are normalized to LF before parsing.
137	pub fn parse_changeset(source: &str) -> Result<Changeset, ParseError> {
138	    let trimmed_bom = source.strip_prefix('\u{FEFF}').unwrap_or(source);
139	    let normalized = trimmed_bom.replace("\r\n", "\n").replace('\r', "\n");
140	    let lines: Vec<&str> = normalized.split('\n').collect();
141	
142	    if lines.first().map(|l| l.trim_end()) != Some("---") {
143	        return Err(ParseError::MissingFrontmatterStart);
144	    }
145	
146	    // Two-pass, deliberately: find the frontmatter's boundaries FIRST, then parse content
147	    // within them. A single pass that tries to parse every line as an entry until it
148	    // happens to hit a literal "---" cannot tell "this entry is malformed" apart from "the
149	    // frontmatter was never closed at all" — the first non-entry-shaped line after a missing
150	    // closing delimiter would otherwise surface as a misleading parse error on that line
151	    // instead of `UnclosedFrontmatter`.
152	    let closing_index = lines[1..].iter().position(|&l| l.trim_end() == "---").map(|i| i + 1);
153	    let Some(closing_index) = closing_index else {
154	        return Err(ParseError::UnclosedFrontmatter);
155	    };
156	
157	    let mut entries: Vec<Entry> = Vec::new();
158	    let mut first_seen: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
159	
160	    for (offset, &line) in lines[1..closing_index].iter().enumerate() {
161	        let line_no = offset + 2; // absolute, 1-indexed; line 1 was "---"
162	        if line.trim().is_empty() || line.trim_start().starts_with('#') {
163	            continue;
164	        }
165	        let entry = parse_entry_line(line).map_err(|e| promote_line_error(e, line_no))?;
166	        if let Some(&first_line) = first_seen.get(&entry.name) {
167	            return Err(ParseError::DuplicateEntry {
168	                line: line_no,
169	                first_line,
170	                name: entry.name,
171	            });
172	        }
173	        first_seen.insert(entry.name.clone(), line_no);
174	        entries.push(entry);
175	    }
176	
177	    let summary = lines[closing_index + 1..].join("\n").trim().to_string();
178	
179	    // No entries and no summary is a valid empty changeset (the shape `@changesets/cli add
180	    // --empty` writes) -- entries and an empty summary is still rejected below.
181	    if !entries.is_empty() && summary.is_empty() {
182	        return Err(ParseError::EmptySummary);
183	    }
184	
185	    Ok(Changeset { entries, summary })
186	}
187	
188	fn promote_line_error(err: LineError, line: usize) -> ParseError {
189	    match err {
190	        LineError::UnclosedQuotedName => ParseError::UnclosedQuotedName { line },
191	        LineError::AmbiguousNameQuoting { raw } => ParseError::AmbiguousNameQuoting { line, raw },
192	        LineError::MissingSeparator { raw } => ParseError::MissingSeparator { line, raw },
193	        LineError::EmptyName => ParseError::EmptyName { line },
194	        LineError::InvalidSeverity { name, source } => ParseError::InvalidSeverity { line, name, source },
195	    }
196	}
197	
198	/// Serializes a [`Changeset`] back to `.changeset/*.md` bytes.
199	///
200	/// Names are quoted only when necessary. Severities are always written lowercase. Output
201	/// always uses `\n` line endings and ends with a single trailing newline after the summary.
202	/// An empty changeset (no entries, no summary) writes as `---\n---\n\n`.
203	pub fn write_changeset(changeset: &Changeset) -> Result<String, WriteError> {
204	    if changeset.summary.trim().is_empty() && !changeset.entries.is_empty() {
205	        return Err(WriteError::EmptySummary);
206	    }
207	    for (index, entry) in changeset.entries.iter().enumerate() {
208	        if entry.name.is_empty() {
209	            return Err(WriteError::EmptyName { index });
210	        }
211	        if entry.name.contains('"') {
212	            return Err(WriteError::NameContainsQuote {
213	                index,
214	                name: entry.name.clone(),
215	            });
216	        }
217	    }
218	
219	    let mut out = String::from("---\n");
220	    for entry in &changeset.entries {
221	        if needs_quoting(&entry.name) {
222	            out.push_str(&format!("\"{}\": {}\n", entry.name, entry.severity));
223	        } else {
224	            out.push_str(&format!("{}: {}\n", entry.name, entry.severity));
225	        }
226	    }
227	    out.push_str("---\n");
228	    let summary = changeset.summary.trim();
229	    if !summary.is_empty() {
230	        out.push('\n');
231	        out.push_str(summary);
232	    }
233	    out.push('\n');
234	    Ok(out)
235	}
