51	/// One `.changeset/*.md` file that failed `parse_changeset`, kept alongside its (workspace-root-
52	/// relative) path so a caller that must survive a malformed changeset -- `status` -- can report
53	/// it as a diagnostic instead of aborting.
54	#[derive(Clone, Debug, PartialEq, Eq)]
55	pub struct ChangesetLoadFailure {
56	    pub path: PathBuf,
57	    pub source: callisto_model::format::ParseError,
58	}
59	
60	/// Every changeset `*.md` file in `dir` (not the README), sorted. A missing directory holds none; any other failure,
61	/// including an entry that cannot be read, is an error rather than a changeset left out of the release.
62	pub(crate) fn list_changeset_files(dir: &Path) -> std::io::Result<Vec<PathBuf>> {
63	    let named =
64	        |path: &Path, error: std::io::Error| std::io::Error::new(error.kind(), format!("{}: {error}", path.display()));
65	    let entries = match fs::read_dir(dir) {
66	        Ok(entries) => entries,
67	        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
68	        Err(error) => return Err(named(dir, error)),
69	    };
70	    let mut files = Vec::new();
71	    for entry in entries {
72	        let path = entry.map_err(|error| named(dir, error))?.path();
73	        let is_changeset = path.extension().and_then(|ext| ext.to_str()) == Some("md")
74	            && path.file_name().and_then(|name| name.to_str()) != Some("README.md");
75	        if !is_changeset {
76	            continue;
77	        }
78	        // A dangling link (an editor lock file such as `.#x.md`) or an entry removed mid-listing holds no changeset.
79	        match fs::metadata(&path) {
80	            Ok(metadata) if metadata.is_file() => files.push(path),
81	            Ok(_) => {}
82	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
83	            Err(error) => return Err(named(&path, error)),
84	        }
85	    }
86	    files.sort();
87	    Ok(files)
88	}
89	
90	/// Loads and parses every `.changeset/*.md` file, splitting successes from parse failures
91	/// rather than aborting on the first one -- `status` must report every unparseable changeset,
92	/// not just the first. [`load_changesets`] collapses this to the first failure for callers
93	/// (`aggregate`/`version`) that must hard-fail instead.
94	pub fn load_changesets_permissive(
95	    root: &Path,
96	    cfg: &ResolvedConfig,
97	) -> Result<(Vec<LoadedChangeset>, Vec<ChangesetLoadFailure>), GraphError> {
98	    let dir = root.join(&cfg.changesets_dir);
99	    let files = list_changeset_files(&dir).map_err(|e| callisto_model::ManifestError::Read {
100	        path: dir.clone(),
101	        message: e.to_string(),
102	    })?;
103	
104	    let mut loaded = Vec::new();
105	    let mut failures = Vec::new();
106	    for path in files {
107	        let content = fs::read_to_string(&path).map_err(|e| callisto_model::ManifestError::Read {
108	            path: path.clone(),
109	            message: e.to_string(),
110	        })?;
111	        let rel_path = path.strip_prefix(root).unwrap_or(&path).to_path_buf();
112	        match parse_changeset(&content) {
113	            Ok(changeset) => {
114	                for entry in &changeset.entries {
115	                    ConfigError::reject_colon_form(&entry.name, &format!("changeset `{}`", rel_path.display()))?;
116	                }
117	                let stem = path.file_stem().and_then(|s| s.to_str()).unwrap_or("").to_string();
118	                loaded.push(LoadedChangeset {
119	                    path: rel_path,
120	                    id: stem,
121	                    changeset,
122	                });
123	            }
124	            Err(source) => failures.push(ChangesetLoadFailure { path: rel_path, source }),
125	        }
126	    }
127	
128	    Ok((loaded, failures))
129	}
130	
131	pub fn load_changesets(root: &Path, cfg: &ResolvedConfig) -> Result<Vec<LoadedChangeset>, GraphError> {
132	    let (loaded, mut failures) = load_changesets_permissive(root, cfg)?;
133	    if !failures.is_empty() {
134	        let failure = failures.remove(0);
135	        return Err(GraphError::ParseChangeset {
136	            path: failure.path,
137	            source: failure.source,
138	        });
139	    }
140	    Ok(loaded)
141	}
142	
143	pub fn apply_pre_major(
144	    inferred: Severity,
145	    policy: PreMajorInferencePolicy,
146	    current: &Version,
147	    has_prior_release: bool,
148	) -> (Severity, bool) {
149	    if policy == PreMajorInferencePolicy::Off {
150	        return (inferred, false);
151	    }
152	    if current.major() != Some(0) || current.minor() == Some(0) || !has_prior_release {
153	        return (inferred, false);
154	    }
155	
156	    match (policy, inferred) {
157	        (PreMajorInferencePolicy::Conservative | PreMajorInferencePolicy::ConservativeFeat, Severity::Major) => {
158	            (Severity::Minor, true)
159	        }
160	        (PreMajorInferencePolicy::ConservativeFeat, Severity::Minor) => (Severity::Patch, true),
161	        (_, s) => (s, false),
162	    }
163	}
164	
165	/// Resolves a release tag name to the commit SHA it points at, so that
166	/// severity inference can be scoped to `since..HEAD` instead of walking the
167	/// entire history on every `aggregate()`-driven command.
168	///
169	/// A tag that is listed but does not resolve to a commit is an error: guessing "infer over full history" would
170	/// plan a bump from commits the last release already covered.
171	fn resolve_since(git: &GitAccess<'_>, tag_name: &str) -> Result<CommitSha, GraphError> {
172	    git.resolve_commit(&format!("refs/tags/{tag_name}"))?.ok_or_else(|| {
173	        GraphError::Vcs(callisto_model::vcs::VcsError::RefNotFound {
174	            ref_name: tag_name.to_string(),
175	        })
176	    })
177	}
178	
179	/// Resolves a changeset entry's or `--package` argument's parsed `PackageId`
180	/// against the packages in the graph, through [`IdentityIndex::resolve_id`] --
181	/// the one selector resolver, not a `PackageId::matches` scan (which treats a
182	/// Bare query as an ecosystem wildcard and would wrongly let a qualified
183	/// selector for one ecosystem select a same-named package in another).
184	///
185	/// `Ok(None)`: no match (unknown package, reported separately by
186	/// `validate`). `Ok(Some(pkg))`: unambiguous. `Err(AmbiguousName)`: two or
187	/// more matches (E103).
188	pub(crate) fn resolve_target_package<'a>(
189	    packages: impl Iterator<Item = &'a Package>,
190	    identity: &IdentityIndex,
191	    id: &PackageId,
192	) -> Result<Option<&'a Package>, GraphError> {
193	    match identity.resolve_id(id) {
194	        Ok(resolved) => Ok(packages.into_iter().find(|p| p.id == resolved)),
195	        Err(GraphError::UnknownPackage { .. }) => Ok(None),
196	        Err(e) => Err(e),
197	    }
198	}
199	
200	#[allow(clippy::too_many_arguments)]
201	pub fn aggregate<D, I>(
202	    graph: &D,
203	    identity: &IdentityIndex,
204	    config: &ResolvedConfig,
205	    git: &GitAccess<'_>,
206	    tags: &TagIndex,
207	    base_versions: &BTreeMap<PackageId, Version>,
208	    pre: Option<&callisto_model::format::PreState>,
209	    inference: &I,
210	) -> Result<Aggregation, GraphError>
211	where
212	    D: DependencyResolver,
213	    I: SeverityInference,
214	{
215	    let loaded = load_changesets(&config.root, config)?;
216	    let mut agg = Aggregation::default();
217	    // Inference reads `since..HEAD`; in a shallow clone that range is silently shorter than the real one.
218	    if graph.packages().any(|pkg| pkg.release_trigger == ReleaseTrigger::Auto) {
219	        git.require_full_history()?;
220	    }
221	
222	    for pkg in graph.packages() {
223	        let cur_sev = agg.severities.get(&pkg.id).copied().unwrap_or(Severity::None);
224	        let pathspecs: Vec<PathBuf> = crate::changed::package_paths(pkg);
225	        let last_tag = tags.last_tag(&pkg.id);
226	        let cur_ver = last_tag
227	            .map(|t| t.version.clone())
228	            .or_else(|| base_versions.get(&pkg.id).cloned())
229	            .ok_or_else(|| {
230	                GraphError::Manifest(callisto_model::ManifestError::MissingField {
231	                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
232	                    field: "version",
233	                })
234	            })?;
235	
236	        let package_ecosystems: Vec<Ecosystem> = pkg.canonical_manifests().map(|m| m.ecosystem()).collect();
237	        let policy = resolve_package_config(&pkg.id, &package_ecosystems, config)
238	            .and_then(|pcfg| pcfg.pre_major_inference)
239	            .unwrap_or(PreMajorInferencePolicy::Off);
240	
241	        // release_trigger: Changeset packages take severity from pending changesets only --
242	        // commit inference must not run for them, so neither does resolving its window.
243	        let inferred = if pkg.release_trigger == ReleaseTrigger::Auto {
244	            let since = last_tag.map(|t| resolve_since(git, t.name.as_str())).transpose()?;
245	            let window = crate::infer::InferenceWindowSpec {
246	                pathspecs: &pathspecs,
247	                since,
248	                current_version: &cur_ver,
249	                has_prior_release: last_tag.is_some(),
250	                policy,
251	            };
252	            inference.infer(pkg, git, window)
253	        } else {
254	            Ok(None)
255	        };
256	
257	        match inferred {
258	            Ok(Some(outcome)) => {
259	                if outcome.severity > cur_sev {
260	                    agg.severities.insert(pkg.id.clone(), outcome.severity);
261	                    agg.reasons.insert(
262	                        pkg.id.clone(),
263	                        BumpReason::Inference {
264	                            commits: outcome.commit_count,
265	                            remapped: outcome.remapped,
266	                        },
267	                    );
268	                    agg.named_by.insert(pkg.id.clone(), NamedBy::Inference);
269	                    agg.inference_commits.insert(pkg.id.clone(), outcome.commits.clone());
270	                }
271	            }
272	            Ok(None) => {}
273	            Err(e) => {
274	                agg.diagnostics.push(Diagnostic {
275	                    code: callisto_model::DiagnosticCode::PreMajorInferenceInert,
276	                    severity: callisto_model::DiagnosticSeverity::Warning,
277	                    message: format!("Commit inference failed for package `{}`: {e}", pkg.id.display_name()),
278	                    package: Some(pkg.id.clone()),
279	                    path: None,
280	                    governed_by: None,
281	                    escalated_by: None,
282	                });
283	            }
284	        }
285	    }
286	
287	    // During a pre-release cycle (PreMode::Pre) changesets must NOT be consumed:
288	    // they remain on disk so they can be re-applied when the cycle exits.
289	    let is_pre_mode = pre
290	        .map(|s| s.mode == callisto_model::format::PreMode::Pre)
291	        .unwrap_or(false);
292	    // Ids already recorded in pre.json still resolve for severity, but are not re-added to the changelog.
293	    let already_recorded: std::collections::HashSet<&str> = pre
294	        .map(|s| s.changesets.iter().map(String::as_str).collect())
295	        .unwrap_or_default();
296	    let mut recorded_only: std::collections::HashSet<PackageId> = std::collections::HashSet::new();
297	
298	    for cs in loaded {
299	        let is_already_recorded = is_pre_mode && already_recorded.contains(cs.id.as_str());
300	        // Defer adding to `consumed` until after we confirm at least one entry
301	        // resolved to a real workspace package. A changeset where every entry
302	        // names a removed package must NOT be consumed (which would delete it
303	        // on disk); instead, an UnknownPackage diagnostic is emitted and the
304	        // file is left for the user to clean up manually.
305	        //
306	        // A changeset with a MIX of resolved and unresolved entries must also
307	        // stay unconsumed: consuming it would delete the file (or, in pre
308	        // mode, mark it as already-applied) and permanently lose the
309	        // unresolved entry's bump once that entry's target reappears.
310	        let mut matched_any = false;
311	        let mut has_unresolved = false;
312	        for entry in cs.changeset.entries {
313	            let id = match PackageId::parse(&entry.name) {
314	                Ok(id) => id,
315	                Err(_) => {
316	                    has_unresolved = true;
317	                    agg.diagnostics.push(Diagnostic {
318	                        code: callisto_model::DiagnosticCode::UnknownPackage,
319	                        severity: callisto_model::DiagnosticSeverity::Warning,
320	                        message: format!(
321	                            "Changeset `{}` contains invalid package name `{}`; the changeset \
322	                             will not be consumed until this entry is resolved",
323	                            cs.path.display(),
324	                            entry.name
325	                        ),
326	                        package: None,
327	                        path: Some(cs.path.clone()),
328	                        governed_by: None,
329	                        escalated_by: None,
330	                    });
331	                    continue;
332	                }
333	            };
334	            match resolve_target_package(graph.packages(), identity, &id)? {
335	                Some(target_pkg) => {
336	                    matched_any = true;
337	                    let canonical_id = target_pkg.id.clone();
338	                    let cur_sev = agg.severities.get(&canonical_id).copied().unwrap_or(Severity::None);
339	                    if entry.severity > cur_sev {
340	                        agg.severities.insert(canonical_id.clone(), entry.severity);
341	                        agg.reasons.insert(
342	                            canonical_id.clone(),
343	                            BumpReason::Changeset {
344	                                changesets: vec![cs.id.clone()],
345	                            },
346	                        );
347	                        agg.named_by.insert(canonical_id.clone(), NamedBy::Changeset);
348	                    }
349	
350	                    if entry.severity != Severity::None && is_already_recorded {
351	                        recorded_only.insert(canonical_id.clone());
352	                    }
353	                    if entry.severity != Severity::None && !is_already_recorded {
354	                        // In pre-release mode use the pre-cycle entry version as the
355	                        // changelog "from" baseline so the log covers the full pre
356	                        // range rather than reflecting live (pre-tagged) versions.
357	                        let pkg_ver = if is_pre_mode {
358	                            pre.and_then(|s| crate::pre_initial_version(s, &canonical_id))
359	                                .cloned()
360	                                .or_else(|| base_versions.get(&canonical_id).cloned())
361	                                .unwrap_or_else(|| Version::semver(0, 0, 0))
362	                        } else {
363	                            tags.last_tag(&canonical_id)
364	                                .map(|t| t.version.clone())
365	                                .or_else(|| base_versions.get(&canonical_id).cloned())
366	                                .unwrap_or_else(|| Version::semver(0, 0, 0))
367	                        };
368	                        let cl_input =
369	                            agg.changelog_inputs
370	                                .entry(canonical_id.clone())
371	                                .or_insert_with(|| ChangelogInput {
372	                                    package: canonical_id.clone(),
373	                                    from: pkg_ver,
374	                                    to: None,
375	                                    entries: Vec::new(),
376	                                });
377	                        cl_input.entries.push(ChangelogEntry {
378	                            severity: entry.severity,
379	                            source: ChangeSource::Changeset {
380	                                filename: cs.id.clone(),
381	                                summary: cs.changeset.summary.clone(),
382	                            },
383	                        });
384	                    }
385	                }
386	                None => {
387	                    // Entry references a package not in the workspace (e.g. a
388	                    // package that was removed since the changeset was written).
389	                    // Emit a diagnostic so the user knows, but do NOT count
390	                    // this as a match -- a fully-orphaned changeset stays on
391	                    // disk rather than being silently deleted.
392	                    has_unresolved = true;
393	                    agg.diagnostics.push(Diagnostic {
394	                        code: callisto_model::DiagnosticCode::UnknownPackage,
395	                        severity: callisto_model::DiagnosticSeverity::Warning,
396	                        message: format!(
397	                            "Changeset `{}` references package `{}` which is not in the \
398	                             workspace; the changeset will not be consumed until this entry \
399	                             is resolved",
400	                            cs.path.display(),
401	                            entry.name
402	                        ),
403	                        package: None,
404	                        path: Some(cs.path.clone()),
405	                        governed_by: None,
406	                        escalated_by: None,
407	                    });
408	                }
409	            }
410	        }
411	        // A changeset with any unresolved entry (orphaned or invalid) is left on disk and
412	        // unrecorded regardless of mode, so a later rerun can still pick up its bump.
413	        if matched_any && !has_unresolved {
414	            if is_pre_mode {
415	                // Records newly-seen ids so a rerun treats them as already-applied and skips the changelog entry.
416	                if !is_already_recorded {
417	                    agg.new_pre_changesets.push(cs.id.clone());
418	                }
419	            } else {
420	                agg.consumed.push(cs.path.clone());
421	            }
422	        }
423	    }
424	
425	    // A package whose only changesets are already recorded in `pre.json` has nothing new to release, so a rerun
426	    // plans no further prerelease for it; recorded changesets still count when a new one names the package.
427	    for id in recorded_only {
428	        if !agg.changelog_inputs.contains_key(&id) && agg.named_by.get(&id) == Some(&NamedBy::Changeset) {
429	            agg.severities.remove(&id);
430	            agg.reasons.remove(&id);
431	            agg.named_by.remove(&id);
432	        }
433	    }
434	
435	    loop {
436	        let mut changed = false;
437	        if union_fixed(&mut agg, &config.groups, base_versions) {
438	            changed = true;
439	        }
440	        if union_linked(&mut agg, &config.groups, base_versions) {
441	            changed = true;
442	        }
443	        if !changed {
444	            break;
445	        }
446	    }
447	
448	    Ok(agg)
449	}
450	
451	pub(crate) fn union_fixed(
452	    agg: &mut Aggregation,
453	    groups: &GroupTable,
454	    base_versions: &BTreeMap<PackageId, Version>,
455	) -> bool {
456	    let mut changed = false;
457	    for g in groups.fixed.values() {
458	        let target = g.max_severity(&agg.severities);
459	        if target == Severity::None {
460	            continue;
461	        }
462	
463	        for m in g.package_members().cloned().collect::<Vec<_>>() {
464	            let cur = agg.severities.get(&m).copied().unwrap_or(Severity::None);
465	            if target > cur {
466	                // Guard against stale group members: a package listed in the
467	                // config group that was subsequently removed from the workspace
468	                // must not be inserted into severities.  Doing so causes
469	                // `bump_target` in `solve_cascade` to call
470	                // `input.base.get(stale_id)` -> `None` ->
471	                // `Err(GraphError::Manifest(MissingField))`, which surfaces as
472	                // a misleading crash.  Emit a warning instead and skip.
473	                if !base_versions.contains_key(&m) {
474	                    agg.diagnostics.push(Diagnostic {
475	                        code: callisto_model::DiagnosticCode::UnknownPackage,
476	                        severity: callisto_model::DiagnosticSeverity::Warning,
477	                        message: format!(
478	                            "Fixed group `{}` references package `{}` which is not in the \
479	                             workspace; the stale group member is skipped. Remove it from \
480	                             callisto.toml to silence this warning.",
481	                            g.name,
482	                            m.display_name()
483	                        ),
484	                        package: Some(m.clone()),
485	                        path: None,
486	                        governed_by: Some(callisto_model::ConfigKey::FIXED_GROUP),
487	                        escalated_by: None,
488	                    });
489	                    continue;
490	                }
491	                agg.severities.insert(m.clone(), target);
492	                agg.reasons
493	                    .insert(m.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
494	                changed = true;
495	            }
496	        }
497	    }
498	    changed
499	}
500	
501	pub(crate) fn union_linked(
502	    agg: &mut Aggregation,
503	    groups: &GroupTable,
504	    base_versions: &BTreeMap<PackageId, Version>,
505	) -> bool {
506	    let mut changed = false;
507	    for g in groups.linked.values() {
508	        let named_any = g.package_members().any(|id| agg.named_by.contains_key(id));
509	        if !named_any {
510	            continue;
511	        }
512	
513	        // Unlike `union_fixed`'s max_severity (over every member), a linked
514	        // group's target severity comes only from members a changeset or
515	        // inference actually named -- an unnamed sibling's stale leftover
516	        // severity from an earlier fixed-point round must not count.
517	        let target_sev = g
518	            .package_members()
519	            .filter(|id| agg.named_by.contains_key(*id))
520	            .filter_map(|id| agg.severities.get(id).copied())
521	            .max()
522	            .unwrap_or(Severity::None);
523	
524	        for m in g.package_members().cloned().collect::<Vec<_>>() {
525	            let cur = agg.severities.get(&m).copied().unwrap_or(Severity::None);
526	            if target_sev > cur {
527	                // Guard against stale linked-group members, same rationale as
528	                // in `union_fixed`: a removed package must not enter
529	                // `agg.severities`, which would cause `bump_target` to crash.
530	                if !base_versions.contains_key(&m) {
531	                    agg.diagnostics.push(Diagnostic {
532	                        code: callisto_model::DiagnosticCode::UnknownPackage,
533	                        severity: callisto_model::DiagnosticSeverity::Warning,
534	                        message: format!(
535	                            "Linked group `{}` references package `{}` which is not in the \
536	                             workspace; the stale group member is skipped. Remove it from \
537	                             callisto.toml to silence this warning.",
538	                            g.name,
539	                            m.display_name()
540	                        ),
541	                        package: Some(m.clone()),
542	                        path: None,
543	                        governed_by: Some(callisto_model::ConfigKey::LINKED_GROUP),
544	                        escalated_by: None,
545	                    });
546	                    continue;
547	                }
548	                agg.severities.insert(m.clone(), target_sev);
549	                agg.reasons
550	                    .insert(m.clone(), BumpReason::LinkedGroupUnion { group: g.name.clone() });
551	                changed = true;
552	            }
553	        }
554	    }
555	    changed
556	}
