376	    pub fn commit_time(&self, rev: &str) -> Result<u64, VcsError> {
377	        let output = self.runner.run(
378	            "git",
379	            &["show", "-s", "--no-show-signature", "--format=%ct", rev],
380	            &self.root,
381	        )?;
