393	    /// Whether `path` (relative to this root) exists in `rev`'s tree; a revision that does not resolve has no paths.
394	    pub fn path_exists_at(&self, rev: &str, path: &Path) -> Result<bool, VcsError> {
395	        let spec = format!("{rev}:./{}", path.display());
396	        let args = ["rev-parse", "--verify", "--quiet", &spec];
397	        let output = self.runner.run("git", &args, &self.root)?;
398	        if output.success() {
399	            return Ok(true);
400	        }
401	        if output.exit_code == Some(1) {
402	            return Ok(false);
403	        }
404	        Err(probe_failed(&args, &self.root, &output))
405	    }
