407	    /// Files in `rev`'s tree matching one of `pathspecs` whose text contains `needle`, ignoring case.
408	    ///
409	    /// No match is an empty list; a revision that cannot be searched is an error.
410	    pub fn files_containing_at(&self, rev: &str, needle: &str, pathspecs: &[&str]) -> Result<Vec<PathBuf>, VcsError> {
411	        let mut args = vec!["grep", "-l", "-z", "-F", "-i", "-e", needle, rev, "--"];
412	        args.extend_from_slice(pathspecs);
413	        let output = self.runner.run("git", &args, &self.root)?;
414	        if output.exit_code == Some(1) {
415	            return Ok(Vec::new());
416	        }
417	        if !output.success() {
418	            return Err(probe_failed(&args, &self.root, &output));
419	        }
420	        let prefix = format!("{rev}:");
421	        Ok(output
422	            .stdout
423	            .split('\0')
424	            .filter_map(|entry| entry.strip_prefix(&prefix))
425	            .map(PathBuf::from)
426	            .collect())
427	    }
