483	    pub fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
484	        let output = self.runner.run("git", &["tag", "--list"], &self.root)?;
485	        if !output.success() {
486	            return Err(probe_failed(&["tag", "--list"], &self.root, &output));
487	        }
488	        let all = output.stdout_lines().map(|s| s.to_string());
489	
490	        let matcher = glob.map(crate::vcs::compile_tag_glob).transpose()?;
491	
492	        Ok(all
493	            .filter(|t| matcher.as_ref().is_none_or(|m| m.is_match(t)))
