499	    /// Resolves `refname` (tag, branch, or partial/full SHA) to the commit
500	    /// it points at. An unresolvable ref resolves to `Ok(None)`, which
501	    /// callers treat as "no bound" / "infer over full history".
502	    pub fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
503	        let rev = format!("{refname}^{{commit}}");
504	        let args = ["rev-parse", "--verify", "--quiet", &rev];
505	        let output = self.runner.run("git", &args, &self.root)?;
506	
507	        if output.exit_code == Some(1) {
508	            return Ok(None);
509	        }
510	        if !output.success() {
511	            return Err(probe_failed(&args, &self.root, &output));
512	        }
513	        let sha_str = output.stdout_trimmed();
514	        if sha_str.is_empty() {
515	            return Ok(None);
516	        }
517	        Ok(CommitSha::parse(sha_str).ok())
518	    }
