569	    /// Resolves every ref in `refs` to its commit with one `git rev-parse`.
570	    /// `None` when any of them does not resolve.
571	    pub fn resolve_commits(&self, refs: &[String]) -> Result<Option<Vec<CommitSha>>, VcsError> {
572	        let revs: Vec<String> = refs.iter().map(|r| format!("{r}^{{commit}}")).collect();
573	        let mut args = vec!["rev-parse"];
574	        args.extend(revs.iter().map(String::as_str));
575	        let output = self.runner.run("git", &args, &self.root)?;
576	        if !output.success() {
577	            // The batch exits 128 for a missing ref and for a broken repository alike; one probe each tells them apart.
578	            for r in refs {
579	                if self.resolve_commit(r)?.is_none() {
580	                    return Ok(None);
581	                }
582	            }
583	            return Err(probe_failed(&args, &self.root, &output));
584	        }
585	        let shas: Option<Vec<CommitSha>> = output.stdout_lines().map(|l| CommitSha::parse(l).ok()).collect();
586	        Ok(shas.filter(|shas| shas.len() == refs.len()))
587	    }
