623	    fn name_only(&self, args: &[&str]) -> Result<Vec<PathBuf>, VcsError> {
624	        let output = self.runner.run("git", args, &self.root)?;
625	        if !output.success() {
626	            return Err(VcsError::Git(format!(
627	                "`git {}` failed in `{}`: {}",
628	                args[0],
629	                self.root.display(),
630	                output.redacted_stderr()
631	            )));
632	        }
633	        Ok(output
634	            .stdout
635	            .split('\0')
