681	    /// `None` when Git can resolve a committer identity itself. Otherwise the
682	    /// target commit's committer, as `-c` overrides, since an annotated tag
683	    /// needs a tagger and a release runner's checkout often configures none.
684	    fn tagger_identity_override(&self, target_sha: &CommitSha) -> Result<Option<[String; 2]>, VcsError> {
685	        let ident = self.runner.run("git", &["var", "GIT_COMMITTER_IDENT"], &self.root)?;
686	        if ident.success() {
687	            return Ok(None);
688	        }
689	        let commit = self
690	            .runner
691	            .run("git", &["cat-file", "commit", target_sha.as_str()], &self.root)?;
692	        let committer = commit
693	            .stdout
694	            .lines()
695	            .take_while(|line| !line.is_empty())
696	            .find_map(|line| line.strip_prefix("committer "))
697	            .and_then(|ident| ident.split_once(" <"))
698	            .and_then(|(name, rest)| Some((name, rest.split_once('>')?.0)));
699	        match committer {
700	            Some((name, email)) if commit.success() && !name.is_empty() && !email.is_empty() => {
701	                Ok(Some([format!("user.name={name}"), format!("user.email={email}")]))
702	            }
703	            _ => Err(VcsError::Git(format!(
704	                "no Git identity for the tagger and could not read the committer of `{}`: {}",
705	                target_sha.as_str(),
706	                commit.redacted_stderr()
707	            ))),
708	        }
709	    }
