733	/// Parses the `<RECORD_SEP>%H<FIELD_SEP>%B`-formatted `git log` output
734	/// produced by [`GitAccess::commits_since`] into [`GitCommit`]s, splitting
735	/// each raw message on its first blank line into `summary`/`body`.
736	fn parse_git_log_output(stdout: &str, cwd: &Path) -> Result<Vec<GitCommit>, VcsError> {
737	    let mut commits = Vec::new();
738	
739	    for record in stdout.split(RECORD_SEP) {
740	        // `tformat:`-style `--format=` output (the default when the format
741	        // string doesn't start with `format:`/`tformat:`) appends a
742	        // trailing newline after every entry; strip it rather than the
743	        // message's own content.
744	        let record = record.trim_end_matches('\n');
745	        if record.is_empty() {
746	            continue;
747	        }
748	
749	        let Some((sha_str, message)) = record.split_once(FIELD_SEP) else {
750	            return Err(VcsError::MalformedLogOutput {
751	                detail: format!(
752	                    "in `{}`: expected a `<sha>{FIELD_SEP:?}<message>` record, got: {record:?}",
753	                    cwd.display()
754	                ),
755	            });
756	        };
757	
758	        let sha = CommitSha::parse(sha_str).map_err(|e| VcsError::InvalidCommitSha {
759	            context: format!("in `git log` output in `{}`", cwd.display()),
760	            message: e.to_string(),
761	        })?;
762	
763	        let message = message.replace("\r\n", "\n");
764	        let (summary, body) = match message.split_once("\n\n") {
765	            Some((title, rest)) => (title.trim_end().to_string(), Some(rest.to_string())),
766	            None => (message.trim_end().to_string(), None),
767	        };
768	
769	        commits.push(GitCommit { sha, summary, body });
770	    }
771	
772	    Ok(commits)
773	}
