24	/// Filters `all_tags` down to those matching `template`'s glob.
25	///
26	/// Compiles the glob via [`callisto_model::vcs::compile_tag_glob`] -- the same
27	/// helper `GitAccess::list_tags` uses -- so tag selection is identical
28	/// either way. Includes error behavior: a
29	/// `template.glob()` that fails to compile surfaces as
30	/// `Err(GraphError::Vcs(VcsError::InvalidGlob))` -- matching every tag is
31	/// the unsafe alternative, since a malformed template must never silently
32	/// make "last tag" resolution pick an unrelated package's tag.
33	fn matching_tags<'a>(all_tags: &'a [String], template: &TagTemplate) -> Result<Vec<&'a str>, GraphError> {
34	    let glob = template.glob();
35	    GLOB_COMPILE_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
36	    let matcher = callisto_model::vcs::compile_tag_glob(&glob).map_err(GraphError::Vcs)?;
37	
38	    Ok(all_tags
39	        .iter()
40	        .filter(|t| matcher.is_match(t.as_str()))
41	        .map(|s| s.as_str())
42	        .collect())
43	}
