87	/// The tags matching `template`, scanned once per distinct glob.
88	fn candidates_cached<'a>(
89	    all_tags: &'a [String],
90	    template: &TagTemplate,
91	    cache: &mut std::collections::HashMap<String, Vec<&'a str>>,
92	) -> Result<Vec<&'a str>, GraphError> {
93	    let glob = template.glob();
94	    if let Some(cached) = cache.get(&glob) {
95	        return Ok(cached.clone());
96	    }
97	    let matched = matching_tags(all_tags, template)?;
98	    cache.insert(glob, matched.clone());
99	    Ok(matched)
100	}
101	
102	/// Keeps the chosen tag and records each skipped-tag warning once, however many packages scan the same tags.
103	fn take_chosen(selection: LastTagSelection, diagnostics: &mut Vec<Diagnostic>) -> Option<LastTag> {
104	    for diagnostic in selection.skipped {
105	        if !diagnostics.iter().any(|seen| seen.message == diagnostic.message) {
106	            diagnostics.push(diagnostic);
107	        }
108	    }
109	    selection.chosen
110	}
111	
112	/// The higher-versioned of two tags found for one package; `first` wins a tie.
113	fn newest(first: Option<LastTag>, second: Option<LastTag>) -> Option<LastTag> {
114	    match (first, second) {
115	        (Some(first), Some(second)) => {
116	            let newer = second
117	                .version
118	                .compare(&first.version)
119	                .is_ok_and(std::cmp::Ordering::is_gt);
120	            Some(if newer { second } else { first })
121	        }
122	        (first, second) => first.or(second),
123	    }
124	}
125	
126	/// E101 when a package's default template (`{name}@{version}`) is also another package's template.
127	fn reject_shared_default_templates<D: DependencyResolver>(graph: &D) -> Result<(), GraphError> {
128	    let mut by_template: BTreeMap<String, (bool, Vec<PackageId>)> = BTreeMap::new();
129	    for pkg in graph.packages() {
130	        let tmpl = pkg
131	            .tag_template
132	            .clone()
133	            .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
134	        let (has_default, ids) = by_template.entry(tmpl.as_str()).or_default();
135	        *has_default |= pkg.tag_template.is_none();
136	        ids.push(pkg.id.clone());
137	    }
138	    match by_template
139	        .into_iter()
140	        .find(|(_, (has_default, ids))| *has_default && ids.len() > 1)
141	    {
142	        Some((template, (_, packages))) => Err(GraphError::SharedDefaultTagTemplate { template, packages }),
143	        None => Ok(()),
144	    }
145	}
146	
147	/// The advisory for a tag a package matched by name but did not make.
148	fn foreign_tag_diagnostic(id: &PackageId, tag: &str) -> Diagnostic {
149	    Diagnostic {
150	        code: DiagnosticCode::TagOwnedByAnotherPackage,
151	        severity: DiagnosticSeverity::Info,
152	        message: format!(
153	            "tag `{tag}` was made when `{name}` named a manifest of another ecosystem, so `{id}` does not take it; if \
154	             this package was renamed, set `previous-tag-templates` on its `[[package]]` rule",
155	            name = id.name(),
156	            id = id.display_name(),
157	        ),
158	        package: Some(id.clone()),
159	        path: None,
160	        escalated_by: None,
161	        governed_by: None,
162	    }
163	}
