165	pub struct TagIndex {
166	    last: BTreeMap<PackageId, Option<LastTag>>,
167	    templates: BTreeMap<PackageId, TagTemplate>,
168	    pre_cursor: BTreeMap<PackageId, Option<CommitSha>>,
169	    /// Tags that match a package's default template by name but were made by another package.
170	    foreign: BTreeMap<PackageId, std::collections::BTreeSet<String>>,
171	    /// The full, unfiltered raw tag list fetched once during `build` (see
172	    /// `fetch_all_tags`), kept around so callers checking whether a specific
173	    /// tag name already exists (e.g. the unreleased-version check, once per
174	    /// package) can consult this in-memory set instead of re-querying `git`
175	    /// once per check.
176	    all_tags: std::collections::BTreeSet<String>,
177	    pub diagnostics: Vec<Diagnostic>,
178	}
179	
180	impl TagIndex {
181	    pub fn build<D: DependencyResolver>(
182	        git: &GitAccess<'_>,
183	        graph: &D,
184	        identity: &IdentityIndex,
185	        cfg: &ResolvedConfig,
186	    ) -> Result<Self, GraphError> {
187	        reject_shared_default_templates(graph)?;
188	        let mut last = BTreeMap::new();
189	        let mut templates = BTreeMap::new();
190	        let mut pre_cursor = BTreeMap::new();
191	        let mut foreign: BTreeMap<PackageId, std::collections::BTreeSet<String>> = BTreeMap::new();
192	        let mut diagnostics = Vec::new();
193	
194	        // Fetch the raw tag list exactly once for the whole build, not once
195	        // per package -- see `fetch_all_tags` for why.
196	        let all_tags = fetch_all_tags(git)?;
197	        let all_tags_set: std::collections::BTreeSet<String> = all_tags.iter().cloned().collect();
198	        let mut glob_cache: std::collections::HashMap<String, Vec<&str>> = std::collections::HashMap::new();
199	
200	        let mut rosters = crate::history::Rosters::default();
201	
202	        for pkg in graph.packages() {
203	            // `TagTemplate::default_for` is the single source of truth for a
204	            // package's default tag template -- matches `release.rs`'s own
205	            // `unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))`.
206	            // Deliberately not `TagTemplate::parse(&format!("{name}@{{version}}"))`:
207	            // `parse` additionally validates git-ref-name legality, which
208	            // `default_for` does not, so the two could previously reject/accept a
209	            // package name differently. Using `default_for` here removes that
210	            // extra validation from this call site to align with the
211	            // already-shipped `release.rs` behavior.
212	            let tmpl = pkg
213	                .tag_template
214	                .clone()
215	                .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
216	            let grammar = pkg.version_grammar()?;
217	            let mut chosen = if pkg.tag_template.is_none() && pkg.id.ecosystem().is_none() {
218	                // A bare name is the only evidence the default template has, so a tag is the package's only if its
219	                // commit did not hold the name in another ecosystem.
220	                let mut candidates = candidates_cached(&all_tags, &tmpl, &mut glob_cache)?;
221	                loop {
222	                    let selection = select_last_tag(&tmpl, grammar, candidates.iter().copied())?;
223	                    let Some(tag) = take_chosen(selection, &mut diagnostics) else {
224	                        break None;
225	                    };
226	                    // History that cannot be read is no evidence of another owner.
227	                    let held = crate::history::may_have_held_name_at(
228	                        git,
229	                        tag.name.as_str(),
230	                        pkg.id.name(),
231	                        pkg,
232	                        identity,
233	                        &mut rosters,
234	                    )
235	                    .unwrap_or(true);
236	                    if held {
237	                        break Some(tag);
238	                    }
239	                    diagnostics.push(foreign_tag_diagnostic(&pkg.id, tag.name.as_str()));
240	                    foreign
241	                        .entry(pkg.id.clone())
242	                        .or_default()
243	                        .insert(tag.name.as_str().to_string());
244	                    candidates.retain(|candidate| *candidate != tag.name.as_str());
245	                }
246	            } else {
247	                take_chosen(
248	                    select_from_tags_cached(&all_tags, &tmpl, grammar, &mut glob_cache)?,
249	                    &mut diagnostics,
250	                )
251	            };
252	            if chosen.is_none() {
253	                let package_ecosystems: Vec<Ecosystem> = pkg.canonical_manifests().map(|m| m.ecosystem()).collect();
254	                if let Some(previous) =
255	                    crate::config::resolve::resolve_package_config(&pkg.id, &package_ecosystems, cfg)
256	                        .map(|package_config| package_config.previous_tag_templates.as_slice())
257	                {
258	                    for template in previous {
259	                        chosen = take_chosen(
260	                            select_from_tags_cached(&all_tags, template, grammar, &mut glob_cache)?,
261	                            &mut diagnostics,
262	                        );
263	                        if chosen.is_some() {
264	                            break;
265	                        }
266	                    }
267	                }
268	            }
269	            if chosen.is_none() && pkg.tag_template.is_none() && pkg.id.ecosystem().is_some() {
270	                // A promoted package keeps the `{name}@` tags it made while its name was unique.
271	                let unqualified = TagTemplate::default_for(&PackageId::Bare(pkg.id.name().to_string()));
272	                let same: Vec<&callisto_model::Package> = graph
273	                    .packages()
274	                    .filter(|p| p.id.ecosystem().is_some() && p.id.name() == pkg.id.name())
275	                    .collect();
276	                let mut owned = Vec::new();
277	                for tag in matching_tags(&all_tags, &unqualified)? {
278	                    if crate::history::sole_owner_at(git, tag, pkg.id.name(), &same, identity, &mut rosters)?
279	                        .is_some_and(|owner| owner.id == pkg.id)
280	                    {
281	                        owned.push(tag);
282	                    }
283	                }
284	                chosen = take_chosen(
285	                    select_last_tag(&unqualified, grammar, owned).map_err(GraphError::from)?,
286	                    &mut diagnostics,
287	                );
288	            }
289	            if pkg.tag_template.is_none() && pkg.id.ecosystem().is_none() {
290	                // A demoted package keeps the qualified tags it made while its name was shared.
291	                if let Some(manifest) = pkg.canonical_manifests().next() {
292	                    let qualified = TagTemplate::default_for(&PackageId::Prefixed {
293	                        ecosystem: manifest.ecosystem(),
294	                        name: pkg.id.name().to_string(),
295	                    });
296	                    let qualified_last = take_chosen(
297	                        select_last_tag(&qualified, grammar, all_tags.iter().map(String::as_str))
298	                            .map_err(GraphError::from)?,
299	                        &mut diagnostics,
300	                    );
301	                    chosen = newest(chosen, qualified_last);
302	                }
303	            }
304	            last.insert(pkg.id.clone(), chosen);
305	            templates.insert(pkg.id.clone(), tmpl);
306	            pre_cursor.insert(pkg.id.clone(), None);
307	        }
308	
309	        Ok(TagIndex {
310	            last,
311	            templates,
312	            pre_cursor,
313	            foreign,
314	            all_tags: all_tags_set,
315	            diagnostics,
316	        })
317	    }
318	
319	    pub fn last_tag(&self, id: &PackageId) -> Option<&LastTag> {
320	        self.last.get(id).and_then(|opt| opt.as_ref())
321	    }
322	
323	    pub fn template(&self, id: &PackageId) -> &TagTemplate {
324	        &self.templates[id]
325	    }
326	
327	    pub fn pre_cursor(&self, id: &PackageId) -> Option<&CommitSha> {
328	        self.pre_cursor.get(id).and_then(|opt| opt.as_ref())
329	    }
330	
331	    /// Returns whether `tag_name` is present in the raw tag list fetched
332	    /// during `build` -- an exact match, not a glob. Lets callers checking
333	    /// tag existence once per package (e.g. `derive_unreleased_decision`)
334	    /// consult this in-memory set instead of shelling out to `git` again
335	    /// for each one.
336	    pub fn contains_tag(&self, tag_name: &str) -> bool {
337	        self.all_tags.contains(tag_name)
338	    }
339	
340	    /// Whether `tag_name` exists and was made by `id`, not by another package that held the same name.
341	    pub fn is_tag_of(&self, id: &PackageId, tag_name: &str) -> bool {
342	        self.contains_tag(tag_name) && !self.foreign.get(id).is_some_and(|tags| tags.contains(tag_name))
343	    }
344	
345	    /// Constructs an empty `TagIndex` with no packages or tags — useful in
346	    /// unit tests that do not exercise tag-based logic.
347	    pub fn empty() -> Self {
348	        TagIndex {
349	            last: BTreeMap::new(),
350	            templates: BTreeMap::new(),
351	            pre_cursor: BTreeMap::new(),
352	            foreign: BTreeMap::new(),
353	            all_tags: std::collections::BTreeSet::new(),
354	            diagnostics: Vec::new(),
355	        }
356	    }
357	}
