243	    grammar: VersionGrammar,
244	    candidates: impl IntoIterator<Item = &'a str>,
245	) -> Result<LastTagSelection, VersionParseError> {
246	    let mut chosen: Option<LastTag> = None;
247	    let mut skipped = Vec::new();
