249	    for candidate in candidates {
250	        let Some(extracted) = template.extract_version_str(candidate) else {
251	            continue;
252	        };
253	
254	        match Version::parse(extracted, grammar) {
255	            Ok(ver) => {
256	                let tag = LastTag {
257	                    // Unchecked: `candidate` matched `template`'s
258	                    // already-validated prefix/suffix (see
259	                    // `TagTemplate::render`'s justification) surrounding
260	                    // `extracted`, which just parsed successfully as a
