265	                };
266	                match &chosen {
267	                    None => chosen = Some(tag),
268	                    Some(prev) => {
269	                        let ord = tag.version.compare(&prev.version).map_err(|_err| VersionParseError {
270	                            raw: extracted.to_string(),
271	                            grammar,
272	                            message: "grammar mismatch during candidate selection".to_string(),
273	                        })?;
274	                        match ord {
275	                            std::cmp::Ordering::Greater => chosen = Some(tag),
276	                            std::cmp::Ordering::Equal => {
277	                                if tag.name.as_str() > prev.name.as_str() {
278	                                    chosen = Some(tag);
279	                                }
280	                            }
281	                            std::cmp::Ordering::Less => {}
282	                        }
283	                    }
284	                }
285	            }
286	            Err(_) => {
287	                skipped.push(Diagnostic {
288	                    code: DiagnosticCode::TagGlobNonVersionMatch,
289	                    severity: DiagnosticSeverity::Warning,
290	                    message: format!(
291	                        "tag candidate `{candidate}` matched glob but placeholder `{extracted}` is not a valid {grammar:?} version"
292	                    ),
293	                    package: None,
294	                    path: None,
295	                    escalated_by: None,
296	                    governed_by: None,
297	                });
298	            }
299	        }
300	    }
