310	/// Refuses when a canonical manifest version differs from `HEAD` while release inputs remain or the change is staged.
311	pub fn check_partial_run<R: CommandRunner, D: DependencyResolver>(ws: &Workspace<'_, R, D>) -> Result<(), GraphError> {
312	    let head = match ws.git_access().head_sha() {
313	        Ok(head) => head,
314	        Err(error) => {
315	            let output = ws
316	                .runner
317	                .run("git", &["rev-parse", "--verify", "--quiet", "HEAD"], &ws.root)
318	                .map_err(GraphError::Command)?;
319	            match output.exit_code {
320	                Some(1) => return Ok(()),
321	                Some(0) => return Err(error.into()),
322	                exit_code => {
323	                    return Err(GraphError::Command(callisto_model::CommandError::Failed {
324	                        program: "git".to_string(),
325	                        exit_code,
326	                        stderr: output.stderr,
327	                    }))
328	                }
329	            }
330	        }
331	    };
332	    let head = head.as_str();
333	
334	    // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
335	    let pre_mode = {
336	        let path = ws.root.join(ws.config.pre_json_path());
337	        let text = callisto_model::strict_fs::read_optional(&path)
338	            .map_err(|e| GraphError::PreJsonRead { message: e.to_string() })?;
339	        if let Some(text) = text {
340	            let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
341	            Some(state.mode)
342	        } else {
343	            None
344	        }
345	    };
346	    let in_pre_release_cycle = pre_mode == Some(callisto_model::format::PreMode::Pre);
347	
348	    let changed = SourceChanges::since(ws, head)?;
349	    let staged_manifests = if in_pre_release_cycle {
350	        BTreeSet::new()
351	    } else {
352	        canonical_manifest_staged_paths(ws, head, &changed)?
353	    };
354	    let pending = !in_pre_release_cycle
355	        && (head_has_pending_changeset(ws, head)?
356	            || working_tree_has_pending_changeset(ws)?
357	            || !staged_manifests.is_empty());
358	    if !pending {
359	        return Ok(());
360	    }
361	
362	    let head_texts = RefCell::new(HashMap::new());
363	    let index_texts = RefCell::new(HashMap::new());
364	    let mut head_reads = callisto_manifests::WorkspaceReads::default();
365	    let mut index_reads = callisto_manifests::WorkspaceReads::default();
366	    let base_versions = ws.base_versions()?;
367	    for pkg in ws.graph.packages() {
368	        let Some(disk) = base_versions.get(&pkg.id) else {
369	            continue;
370	        };
371	        for decl in pkg.canonical_manifests() {
372	            let path = super::release_decision::normalized_git_path(&decl.path)?;
373	            let Some(head_version) = manifest_version_at(ws, head, &path, &head_texts, &mut head_reads)? else {
374	                continue;
375	            };
376	            let index_path_changed = version_source_paths(ws, head, &changed, decl)?
377	                .iter()
378	                .any(|source| staged_manifests.contains(source));
379	            let index_version = if index_path_changed {
380	                manifest_version_in_index(ws, head, &path, &index_texts, &mut index_reads)?
381	            } else {
382	                None
383	            };
384	            let index_display = match &index_version {
385	                Some(version) => version.version.render().to_string(),
386	                None if index_path_changed => "absent".to_string(),
387	                None => head_version.version.render().to_string(),
388	            };
389	            let index_differs = index_path_changed
390	                && index_version
391	                    .as_ref()
392	                    .is_none_or(|version| version.version != head_version.version);
393	            let completing_prerelease = pre_mode == Some(callisto_model::format::PreMode::Exit)
394	                && disk.is_prerelease()
395	                && (!index_path_changed
396	                    || index_version
397	                        .as_ref()
398	                        .is_some_and(|version| version.version.is_prerelease()));
399	            if completing_prerelease {
400	                continue;
401	            }
402	            if *disk != head_version.version || index_differs {
403	                return Err(GraphError::PartialVersionRun {
404	                    path: head_version.authority,
405	                    disk: disk.clone(),
406	                    index: index_display,
407	                    head: head_version.version,
408	                });
409	            }
410	        }
411	    }
412	
413	    Ok(())
414	}
