416	/// True when an untracked or tracked changeset remains in the configured directory on disk.
417	fn working_tree_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
418	    ws: &Workspace<'_, R, D>,
419	) -> Result<bool, GraphError> {
420	    let dir = ws.root.join(&ws.config.changesets_dir);
421	    let files = crate::aggregate::list_changeset_files(&dir).map_err(|error| GraphError::ApplyIo {
422	        path: ws.config.changesets_dir.clone(),
423	        message: error.to_string(),
424	    })?;
425	    Ok(!files.is_empty())
426	}
427	
428	/// True when a canonical manifest differs between index and HEAD: `git add`ed by a prior `apply` but never committed.
429	fn canonical_manifest_staged_paths<R: CommandRunner, D: DependencyResolver>(
430	    ws: &Workspace<'_, R, D>,
431	    head: &str,
432	    changed: &SourceChanges,
433	) -> Result<BTreeSet<String>, GraphError> {
434	    let mut paths = BTreeSet::new();
435	    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
436	        paths.extend(version_source_paths(ws, head, changed, decl)?);
437	    }
438	    let mut staged = BTreeSet::new();
439	    for path in paths {
440	        let output = ws
441	            .runner
442	            .run("git", &["diff", "--cached", "--quiet", "--", &path], &ws.root)
443	            .map_err(GraphError::Command)?;
444	        match output.exit_code {
445	            Some(0) => {}
446	            Some(1) => {
447	                staged.insert(path);
448	            }
449	            exit_code => {
450	                return Err(GraphError::Command(callisto_model::CommandError::Failed {
451	                    program: "git".to_string(),
452	                    exit_code,
453	                    stderr: output.stderr,
454	                }))
455	            }
456	        }
457	    }
458	    Ok(staged)
459	}
460	
461	/// Whether `<rev>:<path>` names an object; `--quiet` keeps a missing path from printing to stderr.
462	fn head_object_exists<R: CommandRunner, D: DependencyResolver>(
463	    ws: &Workspace<'_, R, D>,
464	    spec: &str,
465	) -> Result<bool, GraphError> {
466	    let output = ws
467	        .runner
468	        .run("git", &["rev-parse", "--verify", "--quiet", spec], &ws.root)
469	        .map_err(GraphError::Command)?;
470	    match output.exit_code {
471	        Some(0) => Ok(true),
472	        Some(1) => Ok(false),
473	        exit_code => Err(GraphError::Command(callisto_model::CommandError::Failed {
474	            program: "git".to_string(),
475	            exit_code,
476	            stderr: output.stderr,
477	        })),
478	    }
479	}
480	
481	/// True when `HEAD`'s tree still has an unconsumed changeset file, read from the commit, not the working tree.
482	fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
483	    ws: &Workspace<'_, R, D>,
484	    head: &str,
485	) -> Result<bool, GraphError> {
486	    let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
487	    let spec = format!("{head}:{dir}");
488	    if !head_object_exists(ws, &spec)? {
489	        // The changesets directory didn't exist at HEAD (e.g. the first `version` run); nothing left pending.
490	        return Ok(false);
491	    }
492	    let output = ws
493	        .runner
494	        .run("git", &["ls-tree", "--name-only", &spec], &ws.root)
495	        .map_err(GraphError::Command)?;
496	    if !output.success() {
497	        return Err(GraphError::Command(callisto_model::CommandError::Failed {
498	            program: "git".to_string(),
499	            exit_code: output.exit_code,
500	            stderr: output.stderr,
501	        }));
502	    }
503	    Ok(output.stdout.lines().any(|name| {
504	        let name = name.trim();
505	        name.ends_with(".md") && name != "README.md"
506	    }))
507	}
508	
509	fn manifest_blob_at<R: CommandRunner, D: DependencyResolver>(
510	    ws: &Workspace<'_, R, D>,
511	    head: &str,
512	    path: &str,
513	) -> Result<Option<String>, GraphError> {
514	    let spec = format!("{head}:{path}");
515	    if !head_object_exists(ws, &spec)? {
516	        return Ok(None);
517	    }
518	    let output = ws
519	        .runner
520	        .run("git", &["show", &spec], &ws.root)
521	        .map_err(GraphError::Command)?;
522	    if !output.success() {
523	        return Err(GraphError::Command(callisto_model::CommandError::Failed {
524	            program: "git".to_string(),
525	            exit_code: output.exit_code,
526	            stderr: output.stderr,
527	        }));
528	    }
529	    Ok(Some(output.stdout))
530	}
531	
532	fn manifest_blob_in_index<R: CommandRunner, D: DependencyResolver>(
533	    ws: &Workspace<'_, R, D>,
534	    path: &str,
535	) -> Result<Option<String>, GraphError> {
536	    let spec = format!(":{path}");
537	    if !head_object_exists(ws, &spec)? {
538	        return Ok(None);
539	    }
540	    let output = ws
541	        .runner
542	        .run("git", &["show", &spec], &ws.root)
543	        .map_err(GraphError::Command)?;
544	    if !output.success() {
545	        return Err(GraphError::Command(callisto_model::CommandError::Failed {
546	            program: "git".to_string(),
547	            exit_code: output.exit_code,
548	            stderr: output.stderr,
549	        }));
550	    }
551	    Ok(Some(output.stdout))
552	}
553	
554	/// The paths that differ from `HEAD` in the working tree or the index.
555	struct SourceChanges(BTreeSet<String>);
556	
557	impl SourceChanges {
558	    fn since<R: CommandRunner, D: DependencyResolver>(
559	        ws: &Workspace<'_, R, D>,
560	        head: &str,
561	    ) -> Result<Self, GraphError> {
562	        let mut changed = BTreeSet::new();
563	        let working_tree = vec!["diff", "--name-only", "-z", head];
564	        let index = vec!["diff", "--cached", "--name-only", "-z", head];
565	        for args in [working_tree, index] {
566	            let output = ws.runner.run("git", &args, &ws.root).map_err(GraphError::Command)?;
567	            if !output.success() {
568	                return Err(GraphError::Command(callisto_model::CommandError::Failed {
569	                    program: "git".to_string(),
570	                    exit_code: output.exit_code,
571	                    stderr: output.stderr,
572	                }));
573	            }
574	            changed.extend(
575	                output
576	                    .stdout
577	                    .split('\0')
578	                    .filter(|path| !path.is_empty())
579	                    .map(str::to_owned),
580	            );
581	        }
582	        Ok(SourceChanges(changed))
583	    }
584	}
585	
586	/// Every path whose staged change could alter the effective version of `decl`: its own manifest and, for Cargo, each
587	/// manifest that could be the workspace root it inherits from. That includes the workspace the package names in the
588	/// working tree, and, when its own manifest has changed since `HEAD`, the one it named at `HEAD` and in the index.
589	fn version_source_paths<R: CommandRunner, D: DependencyResolver>(
590	    ws: &Workspace<'_, R, D>,
591	    head: &str,
592	    changed: &SourceChanges,
593	    decl: &callisto_model::ManifestDecl,
594	) -> Result<Vec<String>, GraphError> {
595	    let own = super::release_decision::normalized_git_path(&decl.path)?;
596	    let mut sources = vec![own.clone()];
597	    if decl.ecosystem() == callisto_model::Ecosystem::Cargo {
598	        for candidate in callisto_manifests::workspace_manifest_candidates(&ws.root, &decl.path)? {
599	            sources.push(super::release_decision::normalized_git_path(&candidate)?);
600	        }
601	        if changed.0.contains(&own) {
602	            for text in [manifest_blob_at(ws, head, &own)?, manifest_blob_in_index(ws, &own)?]
603	                .into_iter()
604	                .flatten()
605	            {
606	                if let Some(named) = callisto_manifests::named_workspace_manifest(&decl.path, &text)? {
607	                    sources.push(super::release_decision::normalized_git_path(&named)?);
608	                }
609	            }
610	        }
611	    }
612	    Ok(sources)
613	}
614	
615	/// Manifest text by normalized path, fetched at most once per path.
616	type ManifestTexts = RefCell<HashMap<String, Option<String>>>;
617	
618	fn cached_text(
619	    texts: &ManifestTexts,
620	    path: &std::path::Path,
621	    fetch: impl FnOnce(&str) -> Result<Option<String>, GraphError>,
622	) -> Result<Option<String>, GraphError> {
623	    let key = super::release_decision::normalized_git_path(path)?;
624	    if let Some(text) = texts.borrow().get(&key) {
625	        return Ok(text.clone());
626	    }
627	    let text = fetch(&key)?;
628	    texts.borrow_mut().insert(key, text.clone());
629	    Ok(text)
630	}
631	
632	fn manifest_version_at<R: CommandRunner, D: DependencyResolver>(
633	    ws: &Workspace<'_, R, D>,
634	    head: &str,
635	    path: &str,
636	    texts: &ManifestTexts,
637	    reads: &mut callisto_manifests::WorkspaceReads,
638	) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
639	    let path = std::path::Path::new(path);
640	    let Ok(format) = callisto_model::ManifestFormat::from_path(path) else {
641	        return Ok(None);
642	    };
643	    let at_head = |other: &std::path::Path| cached_text(texts, other, |key| manifest_blob_at(ws, head, key));
644	    let Some(source) = at_head(path)? else {
645	        return Ok(None);
646	    };
647	    callisto_manifests::read_effective_version(format, &source, path, reads, at_head)
648	}
649	
650	/// The version `path` has in the index; manifests it inherits from that the index lacks are read from `head`.
651	fn manifest_version_in_index<R: CommandRunner, D: DependencyResolver>(
652	    ws: &Workspace<'_, R, D>,
653	    head: &str,
654	    path: &str,
655	    texts: &ManifestTexts,
656	    reads: &mut callisto_manifests::WorkspaceReads,
657	) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
658	    let manifest_path = std::path::Path::new(path);
659	    let Ok(format) = callisto_model::ManifestFormat::from_path(manifest_path) else {
660	        return Ok(None);
661	    };
662	    let Some(source) = manifest_blob_in_index(ws, path)? else {
663	        return Ok(None);
664	    };
665	    let in_index_or_head = |other: &std::path::Path| {
666	        cached_text(texts, other, |key| match manifest_blob_in_index(ws, key)? {
667	            Some(text) => Ok(Some(text)),
668	            None => manifest_blob_at(ws, head, key),
669	        })
670	    };
671	    callisto_manifests::read_effective_version(format, &source, manifest_path, reads, in_index_or_head)
672	}
673	
674	/// Platform manifest version writes and owner `optionalDependencies` pin updates
675	/// for every owner with a target version in `targets`. Sources: each owner's
676	/// attached platform manifests, plus `[[fixed-group]]`
677	/// platform members.
678	pub(crate) fn platform_version_writes<R: CommandRunner, D: DependencyResolver>(
679	    ws: &Workspace<'_, R, D>,
680	    targets: &std::collections::BTreeMap<callisto_model::PackageId, callisto_model::Version>,
681	) -> Result<(Vec<PlatformWrite>, Vec<crate::plan::OptionalDepUpdate>), GraphError> {
682	    let open_ctx = OpenContext::for_workspace_root(&ws.root)?;
683	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
684	
685	    let mut members: Vec<(&callisto_model::PackageId, &std::path::Path, &str)> = Vec::new();
686	    for pkg in ws.graph.packages() {
687	        members.extend(
688	            ws.identity
689	                .attached_platforms(pkg)
690	                .map(|(name, path)| (&pkg.id, path, name)),
691	        );
692	    }
693	    for group in ws.config.groups.fixed.values() {
694	        for member in group.members(GroupMemberKind::PlatformManifest) {
695	            if let GroupMember::PlatformManifest { owner, path, name, .. } = member {
696	                members.push((owner, path, name));
697	            }
698	        }
699	    }
700	
701	    let mut seen = HashSet::new();
702	    let mut platform_writes = Vec::new();
703	    let mut optional_dep_map: std::collections::BTreeMap<std::path::PathBuf, Vec<(String, callisto_model::Version)>> =
704	        std::collections::BTreeMap::new();
705	    for (owner, path, name) in members {
706	        let Some(to) = targets.get(owner) else {
707	            continue;
708	        };
709	        if !seen.insert(path) {
710	            continue;
711	        }
712	        let fmt = callisto_model::ManifestFormat::from_path(path)?;
713	        let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
714	        let handle = open(&decl, &open_ctx)?;
715	        let current = handle.current_version()?;
716	        platform_writes.push(PlatformWrite {
717	            manifest: path.to_path_buf(),
718	            version: to.clone(),
719	            from: current,
720	        });
721	
722	        // A dual-manifest owner declares its platforms in package.json, not Cargo.toml.
723	        for owner_decl in pkg_map.get(owner).into_iter().flat_map(|p| p.canonical_manifests()) {
724	            let owner_fmt = callisto_model::ManifestFormat::from_path(&owner_decl.path)?;
725	            let owner_manifest_decl =
726	                callisto_model::ManifestDecl::new(owner_decl.path.clone(), ManifestRole::Canonical, owner_fmt)?;
727	            // Cached: owner manifest is shared across every platform target under it.
728	            let owner_handle = crate::manifest_cache::open_cached(&ws.manifest_cache, &owner_manifest_decl, &open_ctx)?;
729	            if owner_handle
730	                .iter_dependencies()
731	                .any(|dep| dep.kind == callisto_model::DepKind::Optional && dep.name == name)
732	            {
733	                optional_dep_map
734	                    .entry(owner_decl.path.clone())
735	                    .or_default()
736	                    .push((name.to_string(), to.clone()));
737	                break;
738	            }
739	        }
740	    }
741	    let optional_dep_updates = optional_dep_map
742	        .into_iter()
743	        .map(|(manifest, updates)| crate::plan::OptionalDepUpdate { manifest, updates })
744	        .collect();
745	    Ok((platform_writes, optional_dep_updates))
746	}
