10	pub fn package_paths(pkg: &Package) -> Vec<PathBuf> {
11	    let mut set = std::collections::BTreeSet::new();
12	    for m in &pkg.manifests {
13	        if let Some(parent) = m.path.parent() {
14	            if parent.as_os_str().is_empty() {
15	                set.insert(PathBuf::from("."));
16	            } else {
17	                set.insert(parent.to_path_buf());
18	            }
19	        }
20	    }
21	    set.into_iter().collect()
22	}
