90	/// Whether any of `paths` falls under one of `specs` as a literal `git`
91	/// pathspec would match it; `.` matches every path.
92	fn touches(paths: &[PathBuf], specs: &[PathBuf]) -> bool {
93	    paths.iter().any(|path| {
94	        specs
95	            .iter()
96	            .any(|spec| spec.as_path() == Path::new(".") || path.starts_with(spec))
97	    })
98	}
