106	/// `cargo publish` verifies by building the packaged tarball, which needs every
107	/// dependency -- `[dev-dependencies]` included -- resolvable from the registry.
108	pub const PUBLISH_ORDERING_KINDS: &[DepKind] = &[DepKind::Runtime, DepKind::Build, DepKind::Optional, DepKind::Dev];
