10	///
11	/// # Concurrency
12	///
13	/// **Not safe for concurrent calls on the same `path`.** Reads existing
14	/// content then writes atomically, but a second concurrent call could
15	/// read stale content between those two points. Callers must ensure
16	/// sequential access per changelog file -- if this ever moves to
17	/// parallel `apply`, add a per-path lock before removing this note.
18	pub fn prepend(
19	    root: &Path,
20	    changelog_path: &Path,
21	    display_name: &str,
22	    rendered: &str,
23	    permit: &ApplyPermit,
24	) -> Result<(), ChangelogError> {
25	    let full_path = root.join(changelog_path);
26	    if let Some(parent) = full_path.parent() {
27	        fs::create_dir_all(parent).map_err(|e| ChangelogError::WriteFailed {
28	            path: changelog_path.to_path_buf(),
29	            message: e.to_string(),
30	        })?;
31	    }
32	
33	    let existing = callisto_model::strict_fs::read_optional(&full_path)
34	        .map_err(|e| ChangelogError::ReadFailed {
35	            path: changelog_path.to_path_buf(),
36	            message: e.to_string(),
37	        })?
38	        .unwrap_or_else(|| format!("# {display_name}\n\n"));
39	
40	    // Normalise CRLF → LF so the prefix patterns always match, then restore
41	    // the original line endings on the way out if the file used CRLF.
42	    let had_crlf = existing.contains("\r\n");
43	    let normalised = if had_crlf {
44	        existing.replace("\r\n", "\n")
45	    } else {
46	        existing.clone()
47	    };
48	
49	    // Bug 8 guard: if the version heading we are about to insert already exists
50	    // in the file, skip the write entirely (idempotent behaviour). The heading
51	    // is the first line of `rendered` (e.g. "## 1.0.0").
52	    let version_heading = rendered.lines().next().unwrap_or("").trim();
53	    if !version_heading.is_empty() && normalised.lines().any(|l| l.trim() == version_heading) {
54	        return Ok(());
55	    }
56	
57	    // All three header shapes (blank line after the H1, no blank line, or no
