60	    // "the rest of the file to keep" differs, so compute just that here.
61	    let rest: &str = if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n\n")) {
62	        rest
63	    } else if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n")) {
64	        rest
65	    } else {
66	        // No matching H1 found: emit the correct H1 first so the output is
67	        // well-formed, keeping the entire existing content as the body.
68	        &normalised
