95	/// The trimmed `## {version}` section body, empty when the heading has no content;
96	/// `None` only when the heading is absent.
97	pub fn find_section<'a>(changelog: &'a str, version: &Version) -> Option<&'a str> {
98	    let target_heading = format!("## {}", version.render());
99	    let mut start_byte = None;
100	
101	    let mut offset = 0;
102	    for line in changelog.split_inclusive('\n') {
103	        let trimmed = line.trim_end();
104	        if trimmed == target_heading {
105	            start_byte = Some(offset + line.len());
106	            break;
107	        }
108	        offset += line.len();
109	    }
110	
111	    let start = start_byte?;
112	    let slice_after = &changelog[start.min(changelog.len())..];
113	
114	    let mut end = slice_after.len();
115	    let mut line_offset = 0;
116	
117	    for line in slice_after.split_inclusive('\n') {
118	        let trimmed = line.trim_start();
119	        if line_offset > 0 && (trimmed.starts_with("## ") || trimmed.starts_with("# ")) {
120	            end = line_offset;
121	            break;
122	        }
123	        line_offset += line.len();
124	    }
125	
126	    Some(slice_after[..end.min(slice_after.len())].trim())
127	}
