3	use crate::error::GraphError;
4	use crate::plan::VersionPlan;
5	use crate::resolver::DependencyResolver;
6	use crate::Workspace;
7	
8	pub fn plan_snapshot<R: CommandRunner, D: DependencyResolver>(
9	    ws: &Workspace<'_, R, D>,
10	    tag: &str,
11	) -> Result<(VersionPlan, SnapshotReport), GraphError> {
12	    // Resolve HEAD for real rather than faking it, so unrelated snapshot runs never collide.
13	    let sha = ws.git_access().head_sha()?;
14	    let sha_short = sha.short();
15	
16	    // Label for the report only; each package's actual version is built in its own grammar below.
17	    let snapshot_tag = format!("0.0.0-{tag}-{sha_short}");
18	    let base_versions = ws.base_versions()?;
19	    // No severity cascade to seed here; `ws.tags()` only checks the propagate-failure invariant below.
20	    ws.tags()?;
21	
22	    let mut bumps = Vec::new();
23	    let mut plan_bumps = Vec::new();
24	
25	    let mut snapshot_versions = std::collections::BTreeMap::new();
26	
27	    for pkg in ws.graph.packages() {
28	        let from = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
29	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
30	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
31	                field: "version",
32	            })
33	        })?;
34	        let grammar = pkg.version_grammar()?;
35	        let snapshot_ver = snapshot_version_for(grammar, tag, sha_short)?;
36	        snapshot_versions.insert(pkg.id.clone(), snapshot_ver.clone());
37	
38	        let mut writes = Vec::new();
39	        for decl in &pkg.manifests {
40	            if decl.role == callisto_model::ManifestRole::Canonical {
41	                writes.push(crate::plan::VersionWriteTarget::Manifest(decl.path.clone()));
42	            }
43	        }
44	
45	        plan_bumps.push(crate::plan::PlannedBump {
46	            package: pkg.id.clone(),
47	            from: from.clone(),
48	            to: snapshot_ver.clone(),
49	            severity: callisto_model::Severity::Patch,
50	            governed_by: None,
51	            reason: None,
52	            writes,
53	        });
54	
55	        bumps.push(callisto_model::BumpRecord {
56	            package: pkg.canonical_id(),
57	            from,
58	            to: snapshot_ver.clone(),
59	            severity: callisto_model::Severity::Patch,
60	            governed_by: None,
61	            reason: None,
62	        });
63	    }
64	
65	    // No severity to propagate; just rewrite each dependent spec that doesn't cover `snapshot_ver`.
66	    let mut rewrites: std::collections::BTreeMap<crate::cascade::RewriteKey, crate::cascade::SpecRewrite> =
67	        std::collections::BTreeMap::new();
68	    let mut diagnostics = Vec::new();
69	
70	    for pkg in ws.graph.packages() {
71	        for edge in ws.graph.dependencies_of(&pkg.id) {
72	            if matches!(
73	                edge.spec,
74	                callisto_model::DepSpec::Workspace(_) | callisto_model::DepSpec::Catalog(_)
75	            ) {
76	                if matches!(edge.spec, callisto_model::DepSpec::Catalog(_)) {
77	                    diagnostics.push(callisto_model::Diagnostic {
78	                        code: callisto_model::DiagnosticCode::CatalogSpecNotRewritten,
79	                        severity: callisto_model::DiagnosticSeverity::Warning,
80	                        message: format!(
81	                            "spec `{}` for `{}` could not be tested for coverage",
82	                            edge.spec.render(),
83	                            edge.to.display_name()
84	                        ),
85	                        package: Some(edge.from.clone()),
86	                        path: Some(edge.from_manifest.clone()),
87	                        governed_by: Some(callisto_model::ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
88	                        escalated_by: None,
89	                    });
90	                }
91	                continue;
92	            }
93	            if matches!(edge.spec, callisto_model::DepSpec::Opaque(_)) {
94	                continue;
95	            }
96	            let Some(snap_to) = snapshot_versions.get(&edge.to) else {
97	                continue;
98	            };
99	            // snap_to is always SemVer-parsed, so a Pep440 edge here surfaces as a GrammarMismatch, not silently.
100	            let covers =
101	                crate::cascade::coverage(&edge.spec, snap_to).map_err(|source| GraphError::GrammarMismatch {
102	                    from: edge.from.clone(),
103	                    to: edge.to.clone(),
104	                    source,
105	                })?;
106	            if matches!(covers, callisto_model::Coverage::Covers) {
107	                continue;
108	            }
109	
110	            match crate::cascade::rewrite_edge(edge, snap_to, &ws.config.cascade)? {
111	                crate::cascade::RewriteOutcome::Rewritten(to_spec) => {
112	                    let key = crate::cascade::dependency_rewrite_key(edge);
113	                    rewrites
114	                        .entry(key.clone())
115	                        .or_insert_with(|| crate::cascade::SpecRewrite {
116	                            key,
117	                            dependency: edge.to.clone(),
118	                            from: edge.spec.clone(),
119	                            to: to_spec,
120	                        });
121	                }
122	                crate::cascade::RewriteOutcome::LeftAlone(dg) => {
123	                    diagnostics.push(dg);
124	                }
125	            }
126	        }
127	    }
128	    let rewrites: Vec<_> = rewrites.into_values().collect();
129	
130	    let (platform_writes, optional_dep_updates) =
131	        crate::commands::version::platform_version_writes(ws, &snapshot_versions)?;
132	
133	    let plan = VersionPlan {
134	        bumps: plan_bumps,
135	        rewrites,
136	        platform_writes,
137	        optional_dep_updates,
138	        changelog_writes: Vec::new(),
139	        consumed_changesets: Vec::new(),
140	        pre_state_update: None,
141	        pre_json_path: std::path::PathBuf::new(),
142	        pre_json_original_text: None,
143	        delete_pre_json: None,
144	        pre_cursor_updates: Vec::new(),
145	        observed_versions: std::collections::BTreeMap::new(),
146	        diagnostics,
147	    };
148	
149	    let report = SnapshotReport {
150	        schema_version: PACKAGE_REPORT_SCHEMA_VERSION,
151	        snapshot_tag,
152	        bumps,
153	        diagnostics: Vec::new(),
154	    };
155	
156	    Ok((plan, report))
157	}
