160	/// the equivalent PEP 440 dev/local form `0.0.0.dev0+<tag>.<sha>` for Pep440.
161	const SNAPSHOT_SEMVER_PREFIX: &str = "0.0.0-";
162	const SNAPSHOT_PEP440_PREFIX: &str = "0.0.0.dev0+";
163	
164	/// Whether `version` has the shape `snapshot` writes; a snapshot is never tagged or published.
165	pub(crate) fn is_snapshot_version(version: &callisto_model::Version) -> bool {
166	    let rendered = version.render();
167	    rendered.starts_with(SNAPSHOT_SEMVER_PREFIX) || rendered.starts_with(SNAPSHOT_PEP440_PREFIX)
168	}
