178	        _ => {
179	            return Err(GraphError::Bump(
180	                callisto_model::format::BumpError::UnsupportedGrammar { grammar },
181	            ));
182	        }
183	    };
184	    callisto_model::Version::parse(&raw, grammar).map_err(|err| {
185	        GraphError::Bump(callisto_model::format::BumpError::ComputedVersionInvalid {
186	            raw,
187	            message: err.message,
188	        })
189	    })
190	}
