use callisto_model::{CommandRunner, SnapshotReport, PACKAGE_REPORT_SCHEMA_VERSION};

use crate::error::GraphError;
use crate::plan::VersionPlan;
use crate::resolver::DependencyResolver;
use crate::Workspace;

pub fn plan_snapshot<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    tag: &str,
) -> Result<(VersionPlan, SnapshotReport), GraphError> {
    // Resolve HEAD for real rather than faking it, so unrelated snapshot runs never collide.
    let sha = ws.git_access().head_sha()?;
    let sha_short = sha.short();

    // Label for the report only; each package's actual version is built in its own grammar below.
    let snapshot_tag = format!("0.0.0-{tag}-{sha_short}");
    let base_versions = ws.base_versions()?;
    // No severity cascade to seed here; `ws.tags()` only checks the propagate-failure invariant below.
    ws.tags()?;

    let mut bumps = Vec::new();
    let mut plan_bumps = Vec::new();

    let mut snapshot_versions = std::collections::BTreeMap::new();

    for pkg in ws.graph.packages() {
        let from = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
            GraphError::Manifest(callisto_model::ManifestError::MissingField {
                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
                field: "version",
            })
        })?;
        let grammar = pkg.version_grammar()?;
        let snapshot_ver = snapshot_version_for(grammar, tag, sha_short)?;
        snapshot_versions.insert(pkg.id.clone(), snapshot_ver.clone());

        let mut writes = Vec::new();
        for decl in &pkg.manifests {
            if decl.role == callisto_model::ManifestRole::Canonical {
                writes.push(crate::plan::VersionWriteTarget::Manifest(decl.path.clone()));
            }
        }

        plan_bumps.push(crate::plan::PlannedBump {
            package: pkg.id.clone(),
            from: from.clone(),
            to: snapshot_ver.clone(),
            severity: callisto_model::Severity::Patch,
            governed_by: None,
            reason: None,
            writes,
        });

        bumps.push(callisto_model::BumpRecord {
            package: pkg.canonical_id(),
            from,
            to: snapshot_ver.clone(),
            severity: callisto_model::Severity::Patch,
            governed_by: None,
            reason: None,
        });
    }

    // No severity to propagate; just rewrite each dependent spec that doesn't cover `snapshot_ver`.
    let mut rewrites: std::collections::BTreeMap<crate::cascade::RewriteKey, crate::cascade::SpecRewrite> =
        std::collections::BTreeMap::new();
    let mut diagnostics = Vec::new();

    for pkg in ws.graph.packages() {
        for edge in ws.graph.dependencies_of(&pkg.id) {
            if matches!(
                edge.spec,
                callisto_model::DepSpec::Workspace(_) | callisto_model::DepSpec::Catalog(_)
            ) {
                if matches!(edge.spec, callisto_model::DepSpec::Catalog(_)) {
                    diagnostics.push(callisto_model::Diagnostic {
                        code: callisto_model::DiagnosticCode::CatalogSpecNotRewritten,
                        severity: callisto_model::DiagnosticSeverity::Warning,
                        message: format!(
                            "spec `{}` for `{}` could not be tested for coverage",
                            edge.spec.render(),
                            edge.to.display_name()
                        ),
                        package: Some(edge.from.clone()),
                        path: Some(edge.from_manifest.clone()),
                        governed_by: Some(callisto_model::ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
                        escalated_by: None,
                    });
                }
                continue;
            }
            if matches!(edge.spec, callisto_model::DepSpec::Opaque(_)) {
                continue;
            }
            let Some(snap_to) = snapshot_versions.get(&edge.to) else {
                continue;
            };
            // snap_to is always SemVer-parsed, so a Pep440 edge here surfaces as a GrammarMismatch, not silently.
            let covers =
                crate::cascade::coverage(&edge.spec, snap_to).map_err(|source| GraphError::GrammarMismatch {
                    from: edge.from.clone(),
                    to: edge.to.clone(),
                    source,
                })?;
            if matches!(covers, callisto_model::Coverage::Covers) {
                continue;
            }

            match crate::cascade::rewrite_edge(edge, snap_to, &ws.config.cascade)? {
                crate::cascade::RewriteOutcome::Rewritten(to_spec) => {
                    let key = crate::cascade::dependency_rewrite_key(edge);
                    rewrites
                        .entry(key.clone())
                        .or_insert_with(|| crate::cascade::SpecRewrite {
                            key,
                            dependency: edge.to.clone(),
                            from: edge.spec.clone(),
                            to: to_spec,
                        });
                }
                crate::cascade::RewriteOutcome::LeftAlone(dg) => {
                    diagnostics.push(dg);
                }
            }
        }
    }
    let rewrites: Vec<_> = rewrites.into_values().collect();

    let (platform_writes, optional_dep_updates) =
        crate::commands::version::platform_version_writes(ws, &snapshot_versions)?;

    let plan = VersionPlan {
        bumps: plan_bumps,
        rewrites,
        platform_writes,
        optional_dep_updates,
        changelog_writes: Vec::new(),
        consumed_changesets: Vec::new(),
        pre_state_update: None,
        pre_json_path: std::path::PathBuf::new(),
        pre_json_original_text: None,
        delete_pre_json: None,
        pre_cursor_updates: Vec::new(),
        observed_versions: std::collections::BTreeMap::new(),
        diagnostics,
    };

    let report = SnapshotReport {
        schema_version: PACKAGE_REPORT_SCHEMA_VERSION,
        snapshot_tag,
        bumps,
        diagnostics: Vec::new(),
    };

    Ok((plan, report))
}

/// Builds a package's snapshot version in its own grammar: `0.0.0-<tag>-<sha>` for SemVer,
/// the equivalent PEP 440 dev/local form `0.0.0.dev0+<tag>.<sha>` for Pep440.
const SNAPSHOT_SEMVER_PREFIX: &str = "0.0.0-";
const SNAPSHOT_PEP440_PREFIX: &str = "0.0.0.dev0+";

/// Whether `version` has the shape `snapshot` writes; a snapshot is never tagged or published.
pub(crate) fn is_snapshot_version(version: &callisto_model::Version) -> bool {
    let rendered = version.render();
    rendered.starts_with(SNAPSHOT_SEMVER_PREFIX) || rendered.starts_with(SNAPSHOT_PEP440_PREFIX)
}

fn snapshot_version_for(
    grammar: callisto_model::VersionGrammar,
    tag: &str,
    sha_short: &str,
) -> Result<callisto_model::Version, GraphError> {
    let raw = match grammar {
        callisto_model::VersionGrammar::SemVer => format!("{SNAPSHOT_SEMVER_PREFIX}{tag}-{sha_short}"),
        callisto_model::VersionGrammar::Pep440 => format!("{SNAPSHOT_PEP440_PREFIX}{tag}.{sha_short}"),
        _ => {
            return Err(GraphError::Bump(
                callisto_model::format::BumpError::UnsupportedGrammar { grammar },
            ));
        }
    };
    callisto_model::Version::parse(&raw, grammar).map_err(|err| {
        GraphError::Bump(callisto_model::format::BumpError::ComputedVersionInvalid {
            raw,
            message: err.message,
        })
    })
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use crate::locate::IgnoreWalkLocator;
    use crate::Workspace;
    use callisto_model::{CommandError, CommandOutput, CommandRunner};

    use super::plan_snapshot;

    struct FailingTagsRunner;

    impl CommandRunner for FailingTagsRunner {
        fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            if program == "git" && args == ["tag", "--list"] {
                return Err(CommandError::NotFound {
                    program: "git".to_string(),
                });
            }
            Ok(CommandOutput {
                exit_code: Some(0),
                stdout: String::new(),
                stderr: String::new(),
            })
        }
    }

    fn git_init_with_commit(root: &Path) {
        callisto_fixtures::git::init_repo(root);
        std::fs::write(root.join(".gitkeep"), "").unwrap();
        for args in [vec!["add", "."], vec!["commit", "-q", "-m", "init"]] {
            std::process::Command::new("git")
                .args(&args)
                .current_dir(root)
                .output()
                .expect("git must be installed");
        }
    }

    /// When ws.tags() (TagIndex::build) fails, plan_snapshot must
    /// propagate that Err rather than silently proceeding with an
    /// empty/partial TagIndex.
    #[test]
    fn plan_snapshot_propagates_tags_build_failure() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        std::fs::create_dir_all(root.join("pkg-alpha")).unwrap();
        std::fs::write(
            root.join("pkg-alpha/Cargo.toml"),
            "[package]\nname = \"pkg-alpha\"\nversion = \"1.0.0\"\n",
        )
        .unwrap();

        let locator = IgnoreWalkLocator::new(root);
        let runner = FailingTagsRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner)
            .expect("workspace must load even though git tags will later fail");

        let result = plan_snapshot(&ws, "canary");

        assert!(
            result.is_err(),
            "plan_snapshot must propagate a tags-build failure as Err, not silently proceed"
        );
    }

    /// Plan_snapshot's synthetic snapshot version overwrites every
    /// PlannedBump.to and BumpRecord.to unconditionally, even for members of
    /// a Fixed group -- the cascade-stage target the new Fixed-group
    /// convergence block computes internally is discarded.
    #[test]
    fn plan_snapshot_overwrites_fixed_group_targets_with_synthetic_version() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        git_init_with_commit(root);

        std::fs::create_dir_all(root.join("pkg-a")).unwrap();
        std::fs::write(
            root.join("pkg-a/Cargo.toml"),
            "[package]\nname = \"pkg-a\"\nversion = \"2.0.0\"\n",
        )
        .unwrap();
        std::fs::create_dir_all(root.join("pkg-b")).unwrap();
        std::fs::write(
            root.join("pkg-b/Cargo.toml"),
            "[package]\nname = \"pkg-b\"\nversion = \"0.1.0\"\n",
        )
        .unwrap();
        std::fs::write(
            root.join("callisto.toml"),
            "[[fixed-group]]\nname = \"ab\"\nmembers = [\"cargo/pkg-a\", \"cargo/pkg-b\"]\n",
        )
        .unwrap();

        let locator = IgnoreWalkLocator::new(root);
        let runner = callisto_fixtures::git::GitRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let (plan, report) = plan_snapshot(&ws, "canary").expect("plan_snapshot must succeed");

        let expected_prefix = "0.0.0-canary-";
        for bump in &plan.bumps {
            assert!(
                bump.to.render().starts_with(expected_prefix),
                "PlannedBump.to for {:?} must be the synthetic snapshot version, got {}",
                bump.package,
                bump.to.render()
            );
        }
        for bump in &report.bumps {
            assert!(
                bump.to.render().starts_with(expected_prefix),
                "BumpRecord.to for {:?} must be the synthetic snapshot version, got {}",
                bump.package,
                bump.to.render()
            );
        }
    }

    /// `core = "1.0.0"` covers the patch-bumped 1.0.1 but not the snapshot pre-release.
    #[test]
    fn plan_snapshot_rewrites_spec_that_only_the_snapshot_version_leaves_out_of_range() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        git_init_with_commit(root);

        std::fs::create_dir_all(root.join("crates/core/src")).unwrap();
        std::fs::write(
            root.join("crates/core/Cargo.toml"),
            "[package]\nname = \"core\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
        )
        .unwrap();
        std::fs::write(root.join("crates/core/src/lib.rs"), "").unwrap();

        std::fs::create_dir_all(root.join("crates/app/src")).unwrap();
        std::fs::write(
            root.join("crates/app/Cargo.toml"),
            "[package]\nname = \"app\"\nversion = \"1.0.0\"\nedition = \"2021\"\n\n[dependencies]\ncore = { path = \"../core\", version = \"1.0.0\" }\n",
        )

