use schemars::JsonSchema;
use serde::{Deserialize, Deserializer, Serialize, Serializer};

use crate::identity::string_json_schema;
use crate::Ecosystem;

/// `SemVer` is the only implemented grammar; the rest are declared so `Ecosystem::version_grammar` is total.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
#[non_exhaustive]
pub enum VersionGrammar {
    SemVer,
    /// PEP 440 — declared, not implemented.
    Pep440,
    /// Maven's qualifier-ordering comparator — declared, not implemented.
    Maven,
}

/// The parsed form, kept alongside `raw` so comparison and component access are cheap.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub(crate) enum ParsedVersion {
    SemVer(semver::Version),
    Pep440(pep440_rs::Version),
}

/// A parsed version, tagged with the grammar it was parsed under.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Version {
    pub(crate) grammar: VersionGrammar,
    pub(crate) raw: String,
    pub(crate) parsed: ParsedVersion,
}

string_json_schema!(Version);

impl Version {
    /// Parses a native version using its owning distribution's ecosystem.
    pub fn parse_for_ecosystem(raw: &str, ecosystem: Ecosystem) -> Result<Self, VersionParseError> {
        Self::parse(raw, ecosystem.version_grammar())
    }

    pub fn parse(raw: &str, grammar: VersionGrammar) -> Result<Self, VersionParseError> {
        match grammar {
            VersionGrammar::SemVer => {
                let parsed = semver::Version::parse(raw).map_err(|e| VersionParseError {
                    raw: raw.to_string(),
                    grammar,
                    message: e.to_string(),
                })?;
                Ok(Version {
                    grammar,
                    raw: raw.to_string(),
                    parsed: ParsedVersion::SemVer(parsed),
                })
            }
            VersionGrammar::Pep440 => {
                let parsed = raw.parse::<pep440_rs::Version>().map_err(|e| VersionParseError {
                    raw: raw.to_string(),
                    grammar,
                    message: e.to_string(),
                })?;
                // PEP 440 defines multiple equivalent spellings for the same
                // version (e.g. `1.0.0-alpha1`, `1.0.0_alpha1`, `1.0.0a1`).
                // Normalize `raw` to pep440_rs's canonical rendering so that
                // logically-equal inputs produce identical `raw` values, and
                // therefore compare `==` and hash equal (derived PartialEq/Eq/
                // Hash include `raw`). SemVer has no analogous normalization
                // requirement (each version already has one canonical form),
                // so the caller's literal input is preserved for that grammar.
                let canonical = parsed.to_string();
                Ok(Version {
                    grammar,
                    raw: canonical,
                    parsed: ParsedVersion::Pep440(parsed),
                })
            }
            VersionGrammar::Maven => Err(VersionParseError {
                raw: raw.to_string(),
                grammar,
                message: format!("{grammar:?} has no versioning implementation yet"),
            }),
        }
    }

    pub fn semver(major: u64, minor: u64, patch: u64) -> Self {
        let parsed = semver::Version::new(major, minor, patch);
        Version {
            grammar: VersionGrammar::SemVer,
            raw: parsed.to_string(),
            parsed: ParsedVersion::SemVer(parsed),
        }
    }

    pub fn grammar(&self) -> VersionGrammar {
        self.grammar
    }

    pub fn render(&self) -> &str {
        &self.raw
    }

    pub fn raw(&self) -> &str {
        &self.raw
    }

    pub fn major(&self) -> Option<u64> {
        match &self.parsed {
            ParsedVersion::SemVer(v) => Some(v.major),
            ParsedVersion::Pep440(v) => v.release().first().copied(),
        }
    }

    pub fn minor(&self) -> Option<u64> {
        match &self.parsed {
            ParsedVersion::SemVer(v) => Some(v.minor),
            ParsedVersion::Pep440(v) => v.release().get(1).copied(),
        }
    }

    pub fn patch(&self) -> Option<u64> {
        match &self.parsed {
            ParsedVersion::SemVer(v) => Some(v.patch),
            ParsedVersion::Pep440(v) => v.release().get(2).copied(),
        }
    }

    pub fn is_prerelease(&self) -> bool {
        match &self.parsed {
            ParsedVersion::SemVer(v) => !v.pre.is_empty(),
            ParsedVersion::Pep440(v) => !v.is_post() && (v.is_pre() || v.is_dev()),
        }
    }

    pub fn compare(&self, other: &Version) -> Result<std::cmp::Ordering, GrammarMismatch> {
        if self.grammar != other.grammar {
            return Err(GrammarMismatch {
                left: self.grammar,
                right: other.grammar,
            });
        }
        match (&self.parsed, &other.parsed) {
            (ParsedVersion::SemVer(a), ParsedVersion::SemVer(b)) => Ok(a.cmp(b)),
            (ParsedVersion::Pep440(a), ParsedVersion::Pep440(b)) => Ok(a.cmp(b)),
            _ => unreachable!(),
        }
    }

    pub fn partial_compare(&self, other: &Version) -> Option<std::cmp::Ordering> {
        self.compare(other).ok()
    }
}

impl std::fmt::Display for Version {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.raw)
    }
}

impl Serialize for Version {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(self.render())
    }
}

impl<'de> Deserialize<'de> for Version {
    /// Generic (grammar-unaware) deserialization. `Version`'s serialized
    /// form is just its raw string, carrying no grammar info, so this can
    /// only guess by trying grammars in turn -- same as
    /// `VersionReq::deserialize` does for Cargo/Npm/Pypi.
    ///
    /// SemVer is tried first (strictest, most unambiguous); PEP 440 only
    /// if that fails. A string valid under both (e.g. `1.2.3`) always
    /// resolves to `VersionGrammar::SemVer`, never `Pep440` -- same
    /// residual-ambiguity tradeoff `VersionReq::deserialize` accepts.
    ///
    /// Callers who know the intended grammar ahead of time (a sibling
    /// field names it, or the value's from a known-SemVer-only source
    /// like a git tag) should use [`Version::parse`] with an explicit
    /// [`VersionGrammar`] instead.
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let s = String::deserialize(deserializer)?;
        Version::parse(&s, VersionGrammar::SemVer)
            .or_else(|_| Version::parse(&s, VersionGrammar::Pep440))
            .map_err(serde::de::Error::custom)
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub(crate) enum ParsedVersionReq {
    SemVer(Vec<semver::VersionReq>),
    Pep440(pep440_rs::VersionSpecifiers),
}

/// Parsed version requirement.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VersionReq {
    grammar: VersionGrammar,
    ecosystem: Ecosystem,
    req: ParsedVersionReq,
    raw: String,
}

string_json_schema!(VersionReq);

impl VersionReq {
    pub fn parse(raw: &str, ecosystem: Ecosystem) -> Result<Self, VersionParseError> {
        let grammar = ecosystem.version_grammar();
        match grammar {
            VersionGrammar::SemVer => {
                let clauses = if ecosystem == Ecosystem::Npm {
                    raw.split("||").map(str::trim).collect::<Vec<_>>()
                } else {
                    vec![raw]
                };
                let mut reqs = Vec::with_capacity(clauses.len());
                for clause in clauses {
                    if clause.is_empty() {
                        return Err(VersionParseError {
                            raw: raw.to_string(),
                            grammar,
                            message: "empty npm range alternative".to_string(),
                        });
                    }
                    let normalized = if ecosystem == Ecosystem::Npm && Version::parse(clause, grammar).is_ok() {
                        format!("={clause}")
                    } else if ecosystem == Ecosystem::Npm && is_npm_partial_version(clause) {
                        format!("{clause}.x")
                    } else {
                        clause.to_owned()
                    };
                    let req = semver::VersionReq::parse(&normalized).map_err(|e| VersionParseError {
                        raw: raw.to_string(),
                        grammar,
                        message: e.to_string(),
                    })?;
                    reqs.push(req);
                }
                Ok(VersionReq {
                    grammar,
                    ecosystem,
                    req: ParsedVersionReq::SemVer(reqs),
                    raw: raw.to_string(),
                })
            }
            VersionGrammar::Pep440 => {
                let req = raw
                    .parse::<pep440_rs::VersionSpecifiers>()
                    .map_err(|e| VersionParseError {
                        raw: raw.to_string(),
                        grammar,
                        message: e.to_string(),
                    })?;
                // Normalize raw to pep440_rs's canonical rendering so that
                // logically-equal specifiers (e.g. ">=1.0.0A1" vs ">=1.0.0a1")
                // produce identical raw values and therefore compare == and hash
                // equal (derived PartialEq/Eq/Hash include raw).
                let canonical = req.to_string();
                Ok(VersionReq {
                    grammar,
                    ecosystem,
                    req: ParsedVersionReq::Pep440(req),
                    raw: canonical,
                })
            }
            VersionGrammar::Maven => Err(VersionParseError {
                raw: raw.to_string(),
                grammar,
                message: format!("{grammar:?} version requirements not implemented"),
            }),
        }
    }

    pub fn render(&self) -> &str {
        &self.raw
    }

    pub fn ecosystem(&self) -> Ecosystem {
        self.ecosystem
    }

    pub fn matches(&self, v: &Version) -> Result<bool, GrammarMismatch> {
        if self.grammar != v.grammar() {
            return Err(GrammarMismatch {
                left: self.grammar,
                right: v.grammar(),
            });
        }
        match (&self.req, &v.parsed) {
            (ParsedVersionReq::SemVer(reqs), ParsedVersion::SemVer(sv)) => Ok(reqs.iter().any(|req| req.matches(sv))),
            (ParsedVersionReq::Pep440(req), ParsedVersion::Pep440(pv)) => Ok(req.contains(pv)),
            _ => unreachable!(),
        }
    }
}

fn is_npm_partial_version(raw: &str) -> bool {
    raw.split('.').count() == 2
