154	/// default 2-space bare-LF shape, so a CRLF or custom-indent `pre.json` (e.g. `core.autocrlf=true`, or hand-edited)
155	/// is not reformatted on a `pre exit` or mid-cycle `version` rewrite.
156	pub fn write_pre_json_preserving(state: &PreState, existing: &str) -> String {
157	    let fp = PreJsonFingerprint::detect(existing);
158	    let rendered = render_pre_json(state, &fp.indent_str());
159	    fp.apply(&rendered)
160	}
