162	fn render_pre_json(state: &PreState, indent_str: &str) -> String {
163	    let mut map = IndexMap::new();
164	    map.insert(
165	        "mode".to_string(),
166	        serde_json::to_value(state.mode).expect("a pre mode is a JSON string"),
167	    );
168	    map.insert(
169	        "tag".to_string(),
170	        serde_json::to_value(&state.tag).expect("a tag is a JSON string"),
171	    );
172	
173	    let mut init_map = IndexMap::new();
174	    for (pkg, ver) in &state.initial_versions {
175	        init_map.insert(
176	            pkg.clone(),
177	            serde_json::to_value(ver).expect("a version is a JSON string"),
178	        );
179	    }
180	    map.insert(
181	        "initialVersions".to_string(),
182	        serde_json::to_value(init_map).expect("a map of strings is a JSON object"),
183	    );
184	    map.insert(
185	        "changesets".to_string(),
186	        serde_json::to_value(&state.changesets).expect("a list of strings is a JSON array"),
187	    );
188	
189	    let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
190	    let mut buf = Vec::new();
191	    let mut serializer = serde_json::Serializer::with_formatter(&mut buf, formatter);
192	    serde::Serialize::serialize(&map, &mut serializer).expect("serializing JSON values into memory cannot fail");
193	    let mut out = String::from_utf8(buf).expect("serde_json writes UTF-8");
194	    out.push('\n');
195	    out
196	}
