198	/// Byte-level formatting facts (BOM, CRLF, indent) `pre.json` must preserve across a rewrite.
199	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
200	struct PreJsonFingerprint {
201	    has_bom: bool,
202	    crlf: bool,
203	    indent: PreJsonIndent,
204	}
205	
206	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
207	enum PreJsonIndent {
208	    Spaces(u8),
209	    Tabs,
210	}
211	
212	impl PreJsonFingerprint {
213	    fn detect(content: &str) -> Self {
214	        let has_bom = content.starts_with('\u{FEFF}');
215	        let clean = content.strip_prefix('\u{FEFF}').unwrap_or(content);
216	        let crlf = clean.contains("\r\n");
217	
218	        // The first quote-leading line is a top-level key at indent depth 1; its leading whitespace is one unit.
219	        let mut indent = PreJsonIndent::Spaces(2);
220	        for line in clean.lines() {
221	            let trimmed = line.trim_start();
222	            if trimmed.starts_with('"') && line.len() > trimmed.len() {
223	                let leading = &line[..line.len() - trimmed.len()];
224	                indent = if leading.contains('\t') {
225	                    PreJsonIndent::Tabs
226	                } else {
227	                    PreJsonIndent::Spaces(leading.len() as u8)
228	                };
229	                break;
230	            }
231	        }
232	
233	        PreJsonFingerprint { has_bom, crlf, indent }
234	    }
235	
236	    fn indent_str(&self) -> String {
237	        match self.indent {
238	            PreJsonIndent::Tabs => "\t".to_string(),
239	            PreJsonIndent::Spaces(n) => " ".repeat(n as usize),
240	        }
241	    }
242	
243	    /// Reapplies this fingerprint to `rendered`, a freshly-serialized body with bare-LF endings and no BOM.
244	    fn apply(&self, rendered: &str) -> String {
245	        let mut out = if self.crlf {
246	            rendered.replace("\r\n", "\n").replace('\n', "\r\n")
247	        } else {
248	            rendered.to_string()
249	        };
250	        if self.has_bom {
251	            out = format!("\u{FEFF}{out}");
252	        }
253	        out
254	    }
255	}
