261	    Malformed { message: String },
262	
263	    #[error("pre.json is missing required field {field:?}")]
264	    MissingField { field: &'static str },
265	
266	    #[error("pre.json field {field:?} has the wrong type")]
267	    WrongFieldType { field: &'static str },
268	
269	    #[error("pre.json has mode {found:?}, expected \"pre\" or \"exit\"")]
270	    InvalidMode { found: String },
271	
272	    #[error("pre.json initialVersions[{package:?}] = {raw:?} is not a valid version: {source}")]
273	    InvalidInitialVersion {
274	        package: String,
275	        raw: String,
276	        #[source]
277	        source: crate::VersionParseError,
278	    },
279	
280	    #[error("pre.json changesets[{index}] is not a string")]
281	    InvalidChangesetId { index: usize },
282	}
